def _type_sensitive_json_equal(left: object, right: object) -> bool:
    if type(left) is not type(right):
        return False
    if isinstance(left, dict):
        return set(left) == set(right) and all(
            _type_sensitive_json_equal(left[key], right[key]) for key in left
        )
    if isinstance(left, list):
        return len(left) == len(right) and all(
            _type_sensitive_json_equal(left_item, right_item)
            for left_item, right_item in zip(left, right, strict=True)
        )
    return left == right


def _graphql_terminal_end_cursor_is_valid(value: object) -> bool:
    return value is None or (isinstance(value, str) and bool(value))


def _graphql_page_end_cursor_is_valid(
    value: object,
    *,
    has_next_page: object,
) -> bool:
    if has_next_page is True:
        return isinstance(value, str) and bool(value)
    if has_next_page is False:
        return _graphql_terminal_end_cursor_is_valid(value)
    return False


def _json_text_nesting_is_bounded(value: str, max_depth: int) -> bool:
    if type(max_depth) is not int or max_depth <= 0:
        return False
    depth = 0
    in_string = False
    escaped = False
    for character in value:
        if in_string:
            if escaped:
                escaped = False
            elif character == "\\":
                escaped = True
            elif character == '"':
                in_string = False
            continue
        if character == '"':
            in_string = True
        elif character in "[{":
            depth += 1
            if depth > max_depth:
                return False
        elif character in "]}":
            depth -= 1
            if depth < 0:
                return False
    return depth == 0 and not in_string and not escaped


def _json_value_is_bounded(
    value: object,
    *,
    max_depth: int,
    max_container_members: int,
    max_scalar_values: int,
) -> bool:
    if any(
        type(limit) is not int or limit <= 0
        for limit in (max_depth, max_container_members, max_scalar_values)
    ):
        return False
    stack: list[tuple[object, int]] = [(value, 0)]
    seen_containers: set[int] = set()
    container_members = 0
    scalar_values = 0
    while stack:
        item, parent_depth = stack.pop()
        if isinstance(item, dict):
            container_depth = parent_depth + 1
            if container_depth > max_depth or id(item) in seen_containers:
                return False
            seen_containers.add(id(item))
            if not all(isinstance(key, str) for key in item):
                return False
            container_members += len(item)
            if container_members > max_container_members:
                return False
            stack.extend((member, container_depth) for member in item.values())
        elif isinstance(item, list):
            container_depth = parent_depth + 1
            if container_depth > max_depth or id(item) in seen_containers:
                return False
            seen_containers.add(id(item))
            container_members += len(item)
            if container_members > max_container_members:
                return False
            stack.extend((member, container_depth) for member in item)
        else:
            scalar_values += 1
            if scalar_values > max_scalar_values:
                return False
    return True


def _json_strings_are_unicode_scalar_values(value: object) -> bool:
    """Reject decoded JSON strings that contain any lone surrogate."""

    stack = [value]
    while stack:
        item = stack.pop()
        if isinstance(item, dict):
            if any(
                not isinstance(key, str)
                or any(0xD800 <= ord(character) <= 0xDFFF for character in key)
                for key in item
            ):
                return False
            stack.extend(item.values())
        elif isinstance(item, list):
            stack.extend(item)
        elif isinstance(item, str) and any(
            0xD800 <= ord(character) <= 0xDFFF for character in item
        ):
            return False
    return True


def _strict_machine_json_loads(raw: object) -> dict[str, object]:
    """Strictly parse one complete epoch or retarget machine JSON document."""

    if not isinstance(raw, str):
        raise TypeError("machine JSON input must be a string")
    try:
        raw_utf8 = raw.encode("utf-8")
    except UnicodeError as error:
        raise ValueError("machine JSON is not valid UTF-8 text") from error
    if len(raw_utf8) > _MACHINE_JSON_MAX_UTF8_BYTES:
        raise ValueError("machine JSON exceeds the UTF-8 byte limit")
    if not _json_text_nesting_is_bounded(
        raw,
        _MACHINE_JSON_MAX_NESTING_DEPTH,
    ):
        raise ValueError("machine JSON textual nesting is invalid or too deep")

    def reject_duplicate_keys(
        pairs: list[tuple[str, object]],
    ) -> dict[str, object]:
        result: dict[str, object] = {}
        for key, value in pairs:
            if key in result:
                raise ValueError(f"duplicate machine JSON key: {key}")
            result[key] = value
        return result

    def reject_nonstandard_constant(value: str) -> None:
        raise ValueError(f"nonstandard machine JSON constant: {value}")

    def parse_finite_float(value: str) -> float:
        parsed_float = float(value)
        if not math.isfinite(parsed_float):
            raise ValueError("machine JSON contains a non-finite number")
        return parsed_float

    try:
        parsed = json.loads(
            raw,
            object_pairs_hook=reject_duplicate_keys,
            parse_constant=reject_nonstandard_constant,
            parse_float=parse_finite_float,
        )
    except (json.JSONDecodeError, RecursionError, UnicodeError) as error:
        raise ValueError("machine JSON decoding failed") from error
    if not _json_value_is_bounded(
        parsed,
        max_depth=_MACHINE_JSON_MAX_NESTING_DEPTH,
        max_container_members=_MACHINE_JSON_MAX_CONTAINER_MEMBERS,
        max_scalar_values=_MACHINE_JSON_MAX_SCALAR_VALUES,
    ):
        raise ValueError("machine JSON decoded value exceeds resource limits")
    if not _json_strings_are_unicode_scalar_values(parsed):
        raise ValueError("machine JSON contains a lone surrogate")
    if not isinstance(parsed, dict):
        raise ValueError("machine JSON top level must be an object")
    return parsed


