def _restricted_yaml_block_mapping_projection(
    raw_yaml: object,
) -> list[dict[str, object]] | None:
    """Project a deliberately small, non-constructing YAML 1.2 CST subset."""

    if (
        not isinstance(raw_yaml, str)
        or not raw_yaml.endswith("\n")
        or "\r" in raw_yaml
        or "\t" in raw_yaml
        or "\x00" in raw_yaml
    ):
        return None

    def code_without_comment(raw_line: str) -> str | None:
        quote: str | None = None
        escaped = False
        index = 0
        while index < len(raw_line):
            character = raw_line[index]
            if quote == '"':
                if escaped:
                    escaped = False
                elif character == "\\":
                    escaped = True
                elif character == quote:
                    quote = None
            elif quote == "'":
                if character == quote:
                    if (
                        index + 1 < len(raw_line)
                        and raw_line[index + 1] == quote
                    ):
                        index += 1
                    else:
                        quote = None
            elif character in {'"', "'"}:
                quote = character
            elif character == "#" and (
                index == 0 or raw_line[index - 1].isspace()
            ):
                return raw_line[:index].rstrip()
            index += 1
        if quote is not None or escaped:
            return None
        return raw_line.rstrip()

    def scalar_value(value: str) -> str | None:
        if not value:
            return ""
        if value[0] == '"':
            try:
                decoded = json.loads(value)
            except (TypeError, ValueError, json.JSONDecodeError):
                return None
            return decoded if isinstance(decoded, str) else None
        if value[0] == "'":
            if len(value) < 2 or value[-1] != "'":
                return None
            return value[1:-1].replace("''", "'")
        if value[0] in "&*!{" or value.startswith("<<"):
            return None
        return value

    def mapping_parts(code: str) -> tuple[str, str] | None:
        quote: str | None = None
        escaped = False
        delimiter: int | None = None
        for index, character in enumerate(code):
            if quote == '"':
                if escaped:
                    escaped = False
                elif character == "\\":
                    escaped = True
                elif character == quote:
                    quote = None
            elif quote == "'":
                if character == quote:
                    if index + 1 < len(code) and code[index + 1] == quote:
                        continue
                    quote = None
            elif character in {'"', "'"}:
                quote = character
            elif character == ":" and (
                index + 1 == len(code) or code[index + 1].isspace()
            ):
                delimiter = index
                break
        if quote is not None or escaped or delimiter is None:
            return None
        raw_key = code[:delimiter].strip()
        raw_value = code[delimiter + 1 :].strip()
        if not raw_key or raw_key.startswith("?") or raw_key == "<<":
            return None
        key = scalar_value(raw_key)
        if (
            key is None
            or not key
            or re.fullmatch(r"[A-Za-z0-9_.-]+", key) is None
        ):
            return None
        return key, raw_value

    entries: list[dict[str, object]] = []
    container_stack: list[tuple[int, tuple[str, ...]]] = []
    keys_by_scope: dict[tuple[str, ...], set[str]] = {}
    sequence_counts: collections.Counter[tuple[tuple[str, ...], int]] = (
        collections.Counter()
    )
    block_scalar_indent: int | None = None
    for raw_line in raw_yaml.splitlines():
        if not raw_line.strip():
            continue
        indent = len(raw_line) - len(raw_line.lstrip(" "))
        if block_scalar_indent is not None and indent > block_scalar_indent:
            continue
        block_scalar_indent = None
        code = code_without_comment(raw_line)
        if code is None:
            return None
        code = code.strip()
        if not code:
            continue
        if indent % 2 != 0 or code in {"---", "..."} or code.startswith("%"):
            return None
        while container_stack and container_stack[-1][0] >= indent:
            container_stack.pop()
        parent_path = container_stack[-1][1] if container_stack else ()
        sequence_item = False
        if code.startswith("- "):
            sequence_item = True
            sequence_key = (parent_path, indent)
            sequence_index = sequence_counts[sequence_key]
            sequence_counts[sequence_key] += 1
            parent_path = (*parent_path, f"[{sequence_index}]")
            container_stack.append((indent, parent_path))
            code = code[2:].strip()
            if not code or code[0] in "&*!{" or code.startswith("?"):
                return None
        elif code == "-":
            return None
        parts = mapping_parts(code)
        if parts is None:
            if not sequence_item or scalar_value(code) is None:
                return None
            continue
        key, raw_value = parts
        scope_keys = keys_by_scope.setdefault(parent_path, set())
        if key in scope_keys:
            return None
        scope_keys.add(key)
        path = (*parent_path, key)
        value: object
        if not raw_value:
            value = None
            container_stack.append((indent + (2 if sequence_item else 0), path))
        elif raw_value in {"|", "|-", "|+", ">", ">-", ">+"}:
            value = raw_value
            block_scalar_indent = indent + (2 if sequence_item else 0)
        elif raw_value.startswith("["):
            if not raw_value.endswith("]"):
                return None
            raw_members = raw_value[1:-1].strip()
            members = [] if not raw_members else [
                member.strip() for member in raw_members.split(",")
            ]
            if any(
                not member
                or re.fullmatch(r"[A-Za-z][A-Za-z0-9_-]*", member) is None
                for member in members
            ) or len(set(members)) != len(members):
                return None
            value = members
        else:
            value = scalar_value(raw_value)
            if value is None:
                return None
        entries.append(
            {
                "path": path,
                "key": key,
                "value": value,
            }
        )
    return entries


def _action_caller_workflow_is_canonical(raw_workflow: object) -> bool:
    entries = _restricted_yaml_block_mapping_projection(raw_workflow)
    if entries is None:
        return False
    entries_by_path = {
        tuple(entry["path"]): entry["value"] for entry in entries
    }
    top_level_paths = {
        path for path in entries_by_path if len(path) == 1
    }
    if top_level_paths != {
        ("name",),
        ("on",),
        ("permissions",),
        ("concurrency",),
        ("jobs",),
    }:
        return False
    if (
        not isinstance(entries_by_path[("name",)], str)
        or not entries_by_path[("name",)]
        or any(
            entries_by_path[path] is not None
            for path in (("on",), ("permissions",), ("concurrency",), ("jobs",))
        )
    ):
        return False
    event_paths = {
        path
        for path in entries_by_path
        if path[:1] == ("on",) and len(path) == 2
    }
    if not event_paths or any(
        entries_by_path.get(event_path) is not None
        for event_path in event_paths
    ):
        return False
    for path, value in entries_by_path.items():
        if (
            len(path) != 3
            or path[:1] != ("on",)
            or path[2] != "types"
        ):
            continue
        allowed_types = _ACTION_CALLER_EVENT_TYPE_ALLOWLISTS.get(path[1])
        if (
            allowed_types is None
            or not isinstance(value, list)
            or any(member not in allowed_types for member in value)
        ):
            return False
    jobs_children = {
        path for path in entries_by_path if path[:1] == ("jobs",) and len(path) == 2
    }
    job_path = ("jobs", "codex-review-gate")
    if jobs_children != {job_path} or entries_by_path.get(job_path) is not None:
        return False
    job_fields = {
        path for path in entries_by_path if path[:2] == job_path and len(path) == 3
    }
    if job_fields != {
        (*job_path, "name"),
        (*job_path, "uses"),
    }:
        return False
    if (
        entries_by_path.get((*job_path, "name"))
        != "codex/review-gate runner"
        or entries_by_path.get((*job_path, "uses"))
        != _ACTION_REUSABLE_WORKFLOW_SELECTOR
    ):
        return False
    for path, value in entries_by_path.items():
        if path[-1] == "uses" and path != (*job_path, "uses"):
            return False
        if value == _ACTION_REUSABLE_WORKFLOW_SELECTOR and path != (
            *job_path,
            "uses",
        ):
            return False
        if isinstance(value, list) and not (
            len(path) == 3
            and path[0] == "on"
            and path[-1] == "types"
        ):
            return False
    return all(
        any(path[:1] == (required,) and len(path) > 1 for path in entries_by_path)
        for required in ("on", "permissions", "concurrency")
    )
_ACTION_CALLED_WORKFLOW_BODY_V1_5_1 = """
on:
  workflow_call:
    outputs:
      producer-receipt-artifact-id:
        description: GitHub artifact ID for the run-attempt producer receipt.
        value: ${{ jobs.codex-review-gate.outputs.producer-receipt-artifact-id }}
      producer-receipt-artifact-url:
        description: GitHub URL for the run-attempt producer receipt artifact.
        value: ${{ jobs.codex-review-gate.outputs.producer-receipt-artifact-url }}
      producer-receipt-artifact-digest:
        description: SHA-256 digest reported for the producer receipt artifact.
        value: ${{ jobs.codex-review-gate.outputs.producer-receipt-artifact-digest }}

jobs:
  codex-review-gate:
    name: codex/review-gate runner
    if: >-
      ${{
        (github.event_name != 'schedule' || vars.CODEX_REVIEW_GATE_AUTO_RETRY != 'false') &&
        (github.event_name != 'pull_request_target' ||
          github.event.pull_request.user.login != 'dependabot[bot]') &&
        (github.event_name != 'issue_comment' ||
          github.event.issue.user.login != 'dependabot[bot]') &&
        (github.event_name != 'pull_request_review' ||
          github.event.pull_request.user.login != 'dependabot[bot]') &&
        (github.event_name != 'pull_request_review_comment' ||
          github.event.pull_request.user.login != 'dependabot[bot]') &&
        (github.event_name != 'issue_comment' ||
          (github.event.issue.pull_request &&
            (contains(format(',chatgpt-codex-connector,chatgpt-codex-connector[bot],{0},',
              vars.CODEX_REVIEW_GATE_BOT_LOGINS), format(',{0},', github.event.comment.user.login)) ||
             contains(format(',chatgpt-codex-connector,chatgpt-codex-connector[bot],{0},',
              vars.CODEX_REVIEW_GATE_BOT_LOGINS), format(', {0},', github.event.comment.user.login))))) &&
        (github.event_name != 'pull_request_review' ||
          (vars.CODEX_REVIEW_GATE_EVENT_MODE != 'comment-only' &&
            github.event.pull_request.head.repo.full_name == github.event.pull_request.base.repo.full_name &&
            (contains(format(',chatgpt-codex-connector,chatgpt-codex-connector[bot],{0},',
              vars.CODEX_REVIEW_GATE_BOT_LOGINS), format(',{0},', github.event.review.user.login)) ||
             contains(format(',chatgpt-codex-connector,chatgpt-codex-connector[bot],{0},',
              vars.CODEX_REVIEW_GATE_BOT_LOGINS), format(', {0},', github.event.review.user.login))))) &&
        (github.event_name != 'pull_request_review_comment' ||
          (vars.CODEX_REVIEW_GATE_EVENT_MODE == 'full' &&
            github.event.pull_request.head.repo.full_name == github.event.pull_request.base.repo.full_name &&
            (contains(format(',chatgpt-codex-connector,chatgpt-codex-connector[bot],{0},',
              vars.CODEX_REVIEW_GATE_BOT_LOGINS), format(',{0},', github.event.comment.user.login)) ||
             contains(format(',chatgpt-codex-connector,chatgpt-codex-connector[bot],{0},',
              vars.CODEX_REVIEW_GATE_BOT_LOGINS), format(', {0},', github.event.comment.user.login)))))
      }}
    runs-on: ubuntu-slim
    timeout-minutes: 15
    outputs:
      producer-receipt-artifact-id: ${{ steps.gate.outputs.producer-receipt-artifact-id }}
      producer-receipt-artifact-url: ${{ steps.gate.outputs.producer-receipt-artifact-url }}
      producer-receipt-artifact-digest: ${{ steps.gate.outputs.producer-receipt-artifact-digest }}
    steps:
      - name: Check out exact called-workflow release
        id: checkout
        uses: actions/checkout@__CHECKOUT_PIN__ # release-selected
        with:
          repository: ${{ job.workflow_repository }}
          ref: ${{ job.workflow_sha }}
          path: .codex-review-gate-action
          persist-credentials: false

      - name: Run Codex review gate
        id: gate
        uses: ./.codex-review-gate-action
        env:
          CODEX_REVIEW_GATE_CHECKED_OUT_ACTION_COMMIT_SHA: ${{ steps.checkout.outputs.commit }}
        with:
          github-token: ${{ github.token }}
          pull-request: ${{ github.event.pull_request.number || github.event.issue.number || github.event.inputs.pull_request }}
          head-sha: ${{ github.event.pull_request.head.sha || '' }}
          event-mode: ${{ vars.CODEX_REVIEW_GATE_EVENT_MODE }}
          codex-bot-logins: ${{ vars.CODEX_REVIEW_GATE_BOT_LOGINS }}
          completion-signal-buffer-seconds: ${{ vars.CODEX_REVIEW_GATE_COMPLETION_SIGNAL_BUFFER_SECONDS }}
          failed-findings-recovery: ${{ vars.CODEX_REVIEW_GATE_FAILED_FINDINGS_RECOVERY }}
          failed-findings-recovery-mode: ${{ vars.CODEX_REVIEW_GATE_FAILED_FINDINGS_RECOVERY_MODE }}
"""
_ACTION_CALLED_WORKFLOW_BODY = (
    _ACTION_CALLED_WORKFLOW_BODY_V1_5_1.replace(
        (
            "        (github.event_name != 'schedule' || "
            "vars.CODEX_REVIEW_GATE_AUTO_RETRY != 'false') &&"
        ),
        (
            "        ((github.event_name != 'schedule' &&\n"
            "          (github.event_name != 'workflow_dispatch' ||\n"
            "            github.event.inputs.codex_review_gate_trigger != "
            "'scheduled-target-v1')) ||\n"
            "          vars.CODEX_REVIEW_GATE_AUTO_RETRY != 'false') &&"
        ),
        1,
    ).replace(
        (
            "          CODEX_REVIEW_GATE_CHECKED_OUT_ACTION_COMMIT_SHA: "
            "${{ steps.checkout.outputs.commit }}\n"
        ),
        (
            "          CODEX_REVIEW_GATE_CHECKED_OUT_ACTION_COMMIT_SHA: "
            "${{ steps.checkout.outputs.commit }}\n"
            "          CODEX_REVIEW_GATE_AUTO_RETRY: "
            "${{ vars.CODEX_REVIEW_GATE_AUTO_RETRY }}\n"
        ),
        1,
    )
)


def _canonical_action_called_workflow_fixture(
    *,
    release_version: str = "1.5.1",
    name: str = "Codex Review Gate",
    release_comment: str | None = None,
    checkout_pin: str = _ACTION_FIXTURE_CHECKOUT_PIN,
) -> str:
    release_components = _strict_action_semver_components(release_version)
    if re.fullmatch(r"[A-Za-z0-9][A-Za-z0-9 .-]*", name) is None:
        raise ValueError("invalid fixture workflow name")
    if re.fullmatch(r"[0-9a-f]{40}", checkout_pin) is None:
        raise ValueError("invalid fixture checkout pin")
    if release_comment is not None and (
        not release_comment
        or re.fullmatch(r"[A-Za-z0-9][A-Za-z0-9 .:/_-]*", release_comment)
        is None
    ):
        raise ValueError("invalid fixture release comment")
    comment = "" if release_comment is None else f"# {release_comment}\n"
    workflow_body = (
        _ACTION_CALLED_WORKFLOW_BODY
        if release_components is not None
        and release_components >= (1, 5, 2)
        else _ACTION_CALLED_WORKFLOW_BODY_V1_5_1
    )
    return (
        f"name: {name}\n{comment}"
        + workflow_body.replace(
            "__CHECKOUT_PIN__",
            checkout_pin,
        )
    )


def _parse_action_called_workflow_runtime(
    raw_workflow: object,
) -> dict[str, object] | None:
    """Strictly project the release-selected reusable workflow runtime."""

    if (
        not isinstance(raw_workflow, str)
        or not raw_workflow.endswith("\n")
        or "\r" in raw_workflow
        or "\t" in raw_workflow
        or "\x00" in raw_workflow
    ):
        return None
    raw_lines = raw_workflow.splitlines()
    if not raw_lines or not raw_lines[0].startswith("name: "):
        return None
    name = raw_lines[0].removeprefix("name: ")
    if re.fullmatch(r"[A-Za-z0-9][A-Za-z0-9 .-]*", name) is None:
        return None
    lines = [
        line
        for line in raw_lines
        if line.strip() and not line.lstrip().startswith("#")
    ]
    if any(
        re.search(
            r"(^|[ :\[{,])(?:&[A-Za-z0-9_-]+|\*[A-Za-z0-9_-]+|"
            r"!(?!=)[A-Za-z0-9_!-]+|<<:)",
            line.strip(),
        )
        for line in lines
    ):
        return None

    def mapping_keys_at(indent: int, start: int, end: int) -> list[str]:
        keys: list[str] = []
        prefix = " " * indent
        for line in lines[start:end]:
            if not line.startswith(prefix) or line.startswith(prefix + " "):
                continue
            match = re.match(r"[ -]*([A-Za-z0-9_-]+):", line[indent:])
            if match is not None:
                keys.append(match.group(1))
        return keys

    top_level_keys = mapping_keys_at(0, 0, len(lines))
    if top_level_keys != ["name", "on", "jobs"]:
        return None
    jobs_index = lines.index("jobs:")
    if mapping_keys_at(2, jobs_index + 1, len(lines)) != [
        "codex-review-gate"
    ]:
        return None
    job_index = lines.index("  codex-review-gate:", jobs_index + 1)
    job_keys = mapping_keys_at(4, job_index + 1, len(lines))
    if job_keys != [
        "name",
        "if",
        "runs-on",
        "timeout-minutes",
        "outputs",
        "steps",
    ]:
        return None
    required_exact_lines = {
        "    name: codex/review-gate runner",
        "    runs-on: ubuntu-slim",
        "    timeout-minutes: 15",
        "          repository: ${{ job.workflow_repository }}",
        "          ref: ${{ job.workflow_sha }}",
        f"          path: {_ACTION_CHECKOUT_PATH}",
        "          persist-credentials: false",
        f"        uses: ./{_ACTION_CHECKOUT_PATH}",
        (
            f"          {_ACTION_CHECKED_OUT_COMMIT_ENVIRONMENT}: "
            f"{_ACTION_CHECKOUT_COMMIT_OUTPUT}"
        ),
    }
    auto_retry_environment_line = (
        "          CODEX_REVIEW_GATE_AUTO_RETRY: "
        "${{ vars.CODEX_REVIEW_GATE_AUTO_RETRY }}"
    )
    auto_retry_environment_count = lines.count(auto_retry_environment_line)
    if auto_retry_environment_count not in {0, 1}:
        return None
    if auto_retry_environment_count == 1:
        required_exact_lines.add(auto_retry_environment_line)
        if (
            raw_workflow.count(_ACTION_SCHEDULED_TARGET_TRIGGER) != 1
            or raw_workflow.count(_ACTION_AUTO_RETRY_ENVIRONMENT) != 3
            or (
                "((github.event_name != 'schedule' &&\n"
                "          (github.event_name != 'workflow_dispatch' ||\n"
                "            github.event.inputs.codex_review_gate_trigger "
                "!= 'scheduled-target-v1')) ||\n"
                "          vars.CODEX_REVIEW_GATE_AUTO_RETRY != 'false')"
            )
            not in raw_workflow
        ):
            return None
    elif (
        _ACTION_SCHEDULED_TARGET_TRIGGER in raw_workflow
        or raw_workflow.count(_ACTION_AUTO_RETRY_ENVIRONMENT) != 1
        or (
            "(github.event_name != 'schedule' || "
            "vars.CODEX_REVIEW_GATE_AUTO_RETRY != 'false')"
        )
        not in raw_workflow
    ):
        return None
    if any(lines.count(line) != 1 for line in required_exact_lines):
        return None
    step_starts = [
        index
        for index, line in enumerate(lines)
        if line.startswith("      - ")
    ]
    if len(step_starts) != 2 or step_starts[0] >= step_starts[1]:
        return None
    checkout_start, gate_start = step_starts
    checkout_keys = [
        "name",
        *mapping_keys_at(8, checkout_start + 1, gate_start),
    ]
    gate_keys = [
        "name",
        *mapping_keys_at(8, gate_start + 1, len(lines)),
    ]
    if checkout_keys != ["name", "id", "uses", "with"] or gate_keys != [
        "name",
        "id",
        "uses",
        "env",
        "with",
    ]:
        return None
    if lines.count("        id: checkout") != 1 or lines.count(
        "        id: gate"
    ) != 1:
        return None
    uses_lines = [line.strip() for line in lines if "uses:" in line]
    if len(uses_lines) != 2:
        return None
    checkout_match = re.fullmatch(
        r"uses: actions/checkout@([0-9a-f]{40})(?: +# [^\r\n]+)?",
        uses_lines[0],
    )
    if checkout_match is None or uses_lines[1] != (
        f"uses: ./{_ACTION_CHECKOUT_PATH}"
    ):
        return None
    checkout_with_keys = mapping_keys_at(
        10,
        checkout_start + 1,
        gate_start,
    )
    if checkout_with_keys != [
        "repository",
        "ref",
        "path",
        "persist-credentials",
    ]:
        return None
    gate_nested_keys = mapping_keys_at(10, gate_start + 1, len(lines))
    expected_gate_nested_keys = [
        _ACTION_CHECKED_OUT_COMMIT_ENVIRONMENT,
        *(
            [_ACTION_AUTO_RETRY_ENVIRONMENT]
            if auto_retry_environment_count == 1
            else []
        ),
        "github-token",
        "pull-request",
        "head-sha",
        "event-mode",
        "codex-bot-logins",
        "completion-signal-buffer-seconds",
        "failed-findings-recovery",
        "failed-findings-recovery-mode",
    ]
    if gate_nested_keys != expected_gate_nested_keys:
        return None
    return {
        "checkout_pin": checkout_match.group(1),
        "checkout_uses": f"actions/checkout@{checkout_match.group(1)}",
        "checkout_repository": "${{ job.workflow_repository }}",
        "checkout_ref": "${{ job.workflow_sha }}",
        "checkout_path": _ACTION_CHECKOUT_PATH,
        "persist_credentials": False,
        "commit_output": _ACTION_CHECKOUT_COMMIT_OUTPUT,
        "local_action_step_id": "gate",
        "local_action_uses": f"./{_ACTION_CHECKOUT_PATH}",
        "commit_environment_name": _ACTION_CHECKED_OUT_COMMIT_ENVIRONMENT,
        "commit_environment_value": _ACTION_CHECKOUT_COMMIT_OUTPUT,
    }


def _parse_action_definition_external_actions(
    raw_action_definition: object,
) -> list[tuple[str, str]] | None:
    """Return the complete full-SHA external-use closure from action.yml."""

    entries = _restricted_yaml_block_mapping_projection(raw_action_definition)
    if entries is None:
        return None
    external_actions: list[tuple[str, str]] = []
    for entry in entries:
        if entry["key"] != "uses":
            continue
        path = tuple(entry["path"])
        uses = entry["value"]
        if (
            len(path) < 4
            or path[0] != "runs"
            or path[1] != "steps"
            or not re.fullmatch(r"\[[0-9]+\]", path[2])
            or path[-1] != "uses"
            or not isinstance(uses, str)
        ):
            return None
        if uses.startswith("./"):
            continue
        match = re.fullmatch(
            r"([A-Za-z0-9_.-]+/[A-Za-z0-9_.-]+)@([0-9a-f]{40})",
            uses,
        )
        if match is None:
            return None
        external_actions.append((match.group(1), match.group(2)))
    if len(external_actions) != 1 or external_actions[0][0] != (
        "actions/upload-artifact"
    ):
        return None
    return external_actions


def _canonical_action_definition_fixture(
    *,
    release_version: str,
    upload_artifact_pin: str = _ACTION_FIXTURE_UPLOAD_PIN,
    release_comment: str | None = None,
) -> str:
    if (
        _strict_action_semver_components(release_version) is None
        or re.fullmatch(r"[0-9a-f]{40}", upload_artifact_pin) is None
    ):
        raise ValueError("invalid action-definition fixture input")
    if release_comment is not None and (
        not release_comment
        or re.fullmatch(r"[A-Za-z0-9][A-Za-z0-9 .:/_-]*", release_comment)
        is None
    ):
        raise ValueError("invalid action-definition fixture comment")
    comment = "" if release_comment is None else f"# {release_comment}\n"
    return (
        f"name: Codex Review Gate {release_version}\n"
        f"{comment}"
        "description: Release-selected composite action.\n"
        "runs:\n"
        "  using: composite\n"
        "  steps:\n"
        "    - name: Upload producer receipt\n"
        f"      uses: actions/upload-artifact@{upload_artifact_pin}\n"
    )


def _action_called_workflow_runtime_is_closed(raw_workflow: object) -> bool:
    return _parse_action_called_workflow_runtime(raw_workflow) is not None
_ACTION_PRODUCER_RECEIPT_SCHEMA = (
    "urn:joeyteng:codex-review-gate:producer-receipt:1"
)
_ACTION_RELEASE_PROVENANCE_SCHEMA = (
    "urn:joeyteng:codex-review-gate:release-provenance:2"
)
_ACTION_RELEASE_ADMISSION_SCHEMA = (
    "urn:joeyteng:codex-review-gate:release-admission:2"
)
_ACTION_TRUSTED_SIGNER_FINGERPRINT = (
    "EFBBC913F49A5F6E0AF0D248F70246143DC28F32"
)
_ACTION_SEMVER_MAX_ASCII_LENGTH = 255
_ACTION_STRICT_SEMVER_CORE_PATTERN = (
    r"(0|[1-9][0-9]*)\."
    r"(0|[1-9][0-9]*)\."
    r"(0|[1-9][0-9]*)"
)
_ACTION_STRICT_SEMVER_PATTERN = (
    _ACTION_STRICT_SEMVER_CORE_PATTERN
    + r"(?:-(?:0|[1-9][0-9]*|[0-9]*[A-Za-z-][0-9A-Za-z-]*)"
    r"(?:\.(?:0|[1-9][0-9]*|[0-9]*[A-Za-z-][0-9A-Za-z-]*))*)?"
    r"(?:\+[0-9A-Za-z-]+(?:\.[0-9A-Za-z-]+)*)?"
)


def _strict_action_semver_components(
    value: object,
    *,
    release_tag: bool = False,
) -> tuple[int, int, int] | None:
    if type(release_tag) is not bool or not isinstance(value, str):
        return None
    semantic_value = value
    pattern = _ACTION_STRICT_SEMVER_PATTERN
    if release_tag:
        if not value.startswith("v"):
            return None
        semantic_value = value[1:]
        pattern = _ACTION_STRICT_SEMVER_CORE_PATTERN
    if (
        not semantic_value
        or len(semantic_value) > _ACTION_SEMVER_MAX_ASCII_LENGTH
    ):
        return None
    match = re.fullmatch(pattern, semantic_value)
    if match is None:
        return None
    try:
        return tuple(int(match.group(index)) for index in range(1, 4))
    except (TypeError, ValueError):
        return None
