class RepositoryContractTest(unittest.TestCase):
    def test_graphql_terminal_end_cursor_contract(self) -> None:
        for valid_cursor in (None, "TERMINAL_CURSOR"):
            with self.subTest(valid_cursor=valid_cursor):
                self.assertTrue(
                    _graphql_terminal_end_cursor_is_valid(valid_cursor)
                )
        for invalid_cursor in ("", 0, False, True, [], {}):
            with self.subTest(invalid_cursor=invalid_cursor):
                self.assertFalse(
                    _graphql_terminal_end_cursor_is_valid(invalid_cursor)
                )

    def test_completion_registry_graphql_outer_end_cursor_contract(self) -> None:
        for terminal_cursor in (None, "THREAD_TERMINAL_CURSOR"):
            with self.subTest(terminal_cursor=terminal_cursor):
                self.assertTrue(
                    _graphql_page_end_cursor_is_valid(
                        terminal_cursor,
                        has_next_page=False,
                    )
                )
        for invalid_terminal_cursor in ("", 0, True, [], {}):
            with self.subTest(invalid_terminal_cursor=invalid_terminal_cursor):
                self.assertFalse(
                    _graphql_page_end_cursor_is_valid(
                        invalid_terminal_cursor,
                        has_next_page=False,
                    )
                )
        self.assertTrue(
            _graphql_page_end_cursor_is_valid(
                "THREAD_PAGE_1",
                has_next_page=True,
            )
        )
        for invalid_continuation_cursor in ("", None):
            with self.subTest(
                invalid_continuation_cursor=invalid_continuation_cursor
            ):
                self.assertFalse(
                    _graphql_page_end_cursor_is_valid(
                        invalid_continuation_cursor,
                        has_next_page=True,
                    )
                )

    def test_reaction_audit_raw_http_json_is_strict(self) -> None:
        reordered_raw = '{\n  "z": 2,\n  "a": [ true, null ]\n}'
        self.assertEqual(
            _strict_raw_http_json_loads(reordered_raw),
            {"z": 2, "a": [True, None]},
        )
        for invalid_raw in (
            '{"a":1,"a":2}',
            "[NaN]",
            "[Infinity]",
            '"\\ud800"',
        ):
            with self.subTest(raw_http_json_rejection=invalid_raw):
                with self.assertRaises((UnicodeError, ValueError)):
                    _strict_raw_http_json_loads(invalid_raw)

