    def test_role_documents_route_the_bare_triple_exception_without_expanding_it(
        self,
    ) -> None:
        role_documents = {
            "repository-policy": _repository_agents_path(
                REPO_ROOT,
                CI_PROFILE,
            ).read_text(encoding="utf-8"),
            "skill": (SKILL_ROOT / "SKILL.md").read_text(encoding="utf-8"),
            "interface": (SKILL_ROOT / "agents/openai.yaml").read_text(
                encoding="utf-8"
            ),
            "readiness": (
                SKILL_ROOT / "references/pr-readiness.md"
            ).read_text(encoding="utf-8"),
            "egress": (
                SKILL_ROOT / "references/egress-consent.md"
            ).read_text(encoding="utf-8"),
        }
        if CI_PROFILE == "canonical":
            role_documents["readme"] = (REPO_ROOT / "README.md").read_text(
                encoding="utf-8"
            )

        forbidden_mutations = (
            "branch creation",
            "commits",
            "push",
            "pr creation",
            "pr metadata mutation",
            "anchor commit",
            "fixes",
            "delivery",
            "merge",
        )

        def mutation_is_independently_denied(
            document: str,
            mutation: str,
        ) -> bool:
            normalized = document.lower().replace("`", "")
            clauses = re.split(r"(?<=[.!?])\s+|\n+", normalized)
            negative_markers = (
                "authorizes no mutation except",
                "does not authorize",
                "require explicit",
                "requires explicit",
                "never ",
            )
            explicit_positive_markers = (
                f"explicitly-authorizes:{mutation}",
            )
            return any(
                mutation in clause
                and any(marker in clause for marker in negative_markers)
                and not any(
                    marker in clause
                    for marker in explicit_positive_markers
                )
                for clause in clauses
            )

        def bare_triple_exception_is_non_expanding(document: str) -> bool:
            normalized = document.lower().replace("`", "")
            negative_anchor = "authorizes no mutation except"
            anchor_index = normalized.find(negative_anchor)
            if anchor_index < 0:
                return False
            authority_window = normalized[anchor_index : anchor_index + 3_000]
            return (
                "bare-triple request-comment flow" in authority_window
                and "@codex review" in authority_window
                and (
                    "eligible existing pr" in authority_window
                    or "eligible existing pr's" in authority_window
                    or "existing-pr request-comment flow" in authority_window
                )
                and "serial attempt" in authority_window
                and all(
                    mutation_is_independently_denied(document, mutation)
                    for mutation in forbidden_mutations
                )
                and (
                    "does not authorize" in authority_window
                    or "require explicit" in authority_window
                )
            )

        for name, document in role_documents.items():
            with self.subTest(role_document=name):
                normalized_document = document.lower().replace("`", "")
                self.assertTrue(
                    bare_triple_exception_is_non_expanding(document),
                    name,
                )
                for forbidden_without_separate_authorization in forbidden_mutations:
                    self.assertTrue(
                        mutation_is_independently_denied(
                            normalized_document,
                            forbidden_without_separate_authorization,
                        ),
                        forbidden_without_separate_authorization,
                    )
                    independently_reversed = normalized_document.replace(
                        forbidden_without_separate_authorization,
                        "explicitly-authorizes:"
                        + forbidden_without_separate_authorization,
                    )
                    self.assertNotEqual(
                        independently_reversed,
                        normalized_document,
                        forbidden_without_separate_authorization,
                    )
                    self.assertFalse(
                        mutation_is_independently_denied(
                            independently_reversed,
                            forbidden_without_separate_authorization,
                        ),
                        (
                            f"{name} must reject an explicit reversal of "
                            f"{forbidden_without_separate_authorization}"
                        ),
                    )
                reversed_authority = document.replace(
                    "authorizes no mutation except",
                    "authorizes mutation beyond",
                    1,
                )
                self.assertNotEqual(reversed_authority, document, name)
                self.assertFalse(
                    bare_triple_exception_is_non_expanding(
                        reversed_authority
                    ),
                    f"{name} must reject reversal of the non-expansion rule",
                )

        self.assertIn(
            "[pr-readiness.md](references/pr-readiness.md)",
            role_documents["skill"],
        )
        self.assertIn(
            "[egress-consent.md](references/egress-consent.md)",
            role_documents["skill"],
        )
        self.assertIn(
            "[canonical admission section](../SKILL.md#prmaster-secret-admission)",
            role_documents["readiness"],
        )
        self.assertIn(
            "[github-codex-evidence-authority.md]"
            "(github-codex-evidence-authority.md)",
            role_documents["egress"],
        )

