                "required: false\n        type: string",
                "permissions:\n  contents: read\n  issues: write\n  pull-requests: write\n  statuses: write",
                "concurrency:\n  group: codex-review-gate-${{ github.repository }}-${{ github.event.pull_request.number || github.event.issue.number || inputs.pull_request }}\n  cancel-in-progress: false",
                "jobs:\n  codex-review-gate:",
