                    '"$isolated_python" -I -B -S - "$isolated_source"',
                    '"$gate_manifest" "$gate_manifest_digest" hosted-readonly',
                    '"$isolated_root/payload/runtime" "$isolated_root/payload"',
                    'checkout_git_objects="$checkout_git_dir/objects"',
