        def accepted_by_closed_consumer(
            candidate: object,
            *,
            consumer_version: int,
            consumer_root_fields: set[str],
            consumer_version_contract_fields: set[str],
        ) -> bool:
            if not isinstance(candidate, dict):
                return False
            candidate_version_contract = candidate.get("version_contract")
            if not isinstance(candidate_version_contract, dict):
                return False
            declared_root_fields = candidate_version_contract.get(
                "root_closed_required_fields"
            )
            declared_version_contract_fields = candidate_version_contract.get(
                "closed_required_fields"
            )
            return (
                type(candidate.get("version")) is int
                and candidate.get("version") == consumer_version
                and set(candidate) == consumer_root_fields
                and isinstance(declared_root_fields, list)
                and set(declared_root_fields) == consumer_root_fields
                and len(declared_root_fields) == len(consumer_root_fields)
                and candidate_version_contract.get(
                    "root_additional_fields_allowed"
                )
                is False
                and set(candidate_version_contract)
                == consumer_version_contract_fields
                and isinstance(declared_version_contract_fields, list)
                and set(declared_version_contract_fields)
                == consumer_version_contract_fields
                and len(declared_version_contract_fields)
                == len(consumer_version_contract_fields)
                and candidate_version_contract.get(
                    "additional_fields_allowed"
                )
                is False
                and candidate_version_contract.get("role")
                == "closed-schema-discriminator"
                and candidate_version_contract.get(
                    "compatible_consumer_versions"
                )
                == [consumer_version]
                and _type_sensitive_json_equal(
                    candidate_version_contract.get(
                        "raw_json_decoder_contract"
                    ),
                    _MACHINE_RAW_JSON_DECODER_CONTRACT,
                )
                and all(
                    type(version) is int
                    for version in candidate_version_contract[
                        "compatible_consumer_versions"
                    ]
                )
                and candidate_version_contract.get(
                    "breaking_closed-schema-change_requires-version-increment"
                )
                is True
                and all(
                    candidate_version_contract.get(
                        f"version_{old_version}_consumer_may_accept_this_shape"
                    )
                    is False
                    for old_version in range(1, consumer_version)
                )
            )

        def accepted_by_v41_consumer(candidate: object) -> bool:
            return accepted_by_closed_consumer(
                candidate,
                consumer_version=41,
                consumer_root_fields=expected_root_fields,
                consumer_version_contract_fields=(
                    expected_version_contract_fields
                ),
            )

        def fixed_semantic_fingerprint_from_raw(
            raw: object,
        ) -> str | None:
            try:
                candidate = _strict_machine_json_loads(raw)
            except (TypeError, UnicodeError, ValueError):
                return None
            try:
                canonical_raw = json.dumps(
                    candidate,
                    allow_nan=False,
                    ensure_ascii=False,
                    separators=(",", ":"),
                    sort_keys=True,
                )
            except (TypeError, UnicodeError, ValueError):
                return None
            return hashlib.sha256(
                canonical_raw.encode("utf-8")
            ).hexdigest()

        def canonical_machine_raw(candidate: object) -> str:
            return json.dumps(
                candidate,
                allow_nan=False,
                ensure_ascii=False,
                separators=(",", ":"),
                sort_keys=True,
            )

