        for case, raw in strict_raw_negatives.items():
            with self.subTest(strict_raw_negative=case):
                with self.assertRaises(ValueError):
                    _strict_machine_json_loads(raw)
                self.assertFalse(accepted_raw_by_v41_consumer(raw))
                self.assertIsNone(fixed_semantic_fingerprint_from_raw(raw))

        numeric_root_version_alias = dict(machine)
