        def graphql_thread_page_body(thread_count: int) -> str:
            return json.dumps(
                {
                    "data": {
                        "repository": {
                            "pullRequest": {
                                "reviewThreads": {
                                    "nodes": [
                                        {
                                            "id": f"PRRT_{index}",
                                            "comments": {"nodes": []},
                                        }
                                        for index in range(thread_count)
                                    ]
                                }
                            }
                        }
                    }
                },
                ensure_ascii=False,
                separators=(",", ":"),
                sort_keys=True,
            )

