        def retention_ref_resource_graph(
            candidate_count: int,
        ) -> dict[str, object]:
            return {
                phase: {
                    "candidate_release_admission_captures": [
                        {
                            role: {
                                "request_url": (
                                    "https://api.github.com/repos/"
                                    f"{_ACTION_REPOSITORY}/git/ref/tags/"
                                    "codex-review-gate-retention/"
                                    f"v1.5.{candidate_index}/{role}"
                                ),
                                "raw_body_utf8": "{}",
                            }
                            for role in ("minor", "major")
                        }
                        for candidate_index in range(candidate_count)
                    ]
                }
                for phase in ("initial", "final")
            }

