        def graphql_status_context_rereads(
            statuses: list[dict[str, object]],
            *,
            commit_sha: str,
            date_header: str,
        ) -> list[dict[str, object]]:
            rereads: list[dict[str, object]] = []
            for row in statuses:
                creator = row.get("creator")
                creator_id = (
                    creator.get("id") if isinstance(creator, dict) else None
                )
                creator_login = (
                    creator.get("login")
                    if isinstance(creator, dict)
                    else None
                )
                creator_type = (
                    creator.get("type")
                    if isinstance(creator, dict)
                    else None
                )
                request_body = json.dumps(
                    {
                        "query": _STATUS_CONTEXT_NODE_QUERY,
                        "variables": {"id": row.get("node_id")},
                    },
                    ensure_ascii=False,
                    separators=(",", ":"),
                    sort_keys=True,
                )
                response_body = json.dumps(
                    {
                        "data": {
                            "node": {
                                "__typename": "StatusContext",
                                "id": row.get("node_id"),
                                "context": row.get("context"),
                                "state": str(row.get("state")).upper(),
                                "targetUrl": row.get("target_url"),
                                "createdAt": row.get("created_at"),
                                "commit": {"oid": commit_sha},
                                "creator": {
                                    "__typename": creator_type,
                                    "login": creator_login,
                                    "databaseId": creator_id,
                                },
                            }
                        }
                    },
                    ensure_ascii=False,
                    separators=(",", ":"),
                    sort_keys=True,
                )
                rereads.append(
                    {
                        "request_url": "https://api.github.com/graphql",
                        "http_status": 200,
                        "date_header": date_header,
                        "request_body_utf8": request_body,
                        "request_body_sha256": hashlib.sha256(
                            request_body.encode("utf-8")
                        ).hexdigest(),
                        "raw_body_utf8": response_body,
                        "raw_body_sha256": hashlib.sha256(
                            response_body.encode("utf-8")
                        ).hexdigest(),
                    }
                )
            return rereads

        def status_receipt(
            statuses: list[dict[str, object]],
            *,
            commit_sha: str = current_head,
            pagination_complete: bool = True,
            date_header: str = "Sun, 09 Aug 2026 12:00:00 GMT",
            link_header: str | None = None,
        ) -> dict[str, object]:
            raw_body = json.dumps(
                statuses,
                ensure_ascii=False,
                separators=(",", ":"),
                sort_keys=True,
            )
            return {
                "endpoint_url": (
                    "https://api.github.com/repos/OWNER/REPO/commits/"
                    f"{commit_sha}/statuses?per_page=100&page=1"
                ),
                "commit_sha": commit_sha,
                "pagination_complete": pagination_complete,
                "pages": [
                    {
                        "request_url": (
                            "https://api.github.com/repos/OWNER/REPO/commits/"
                            f"{commit_sha}/statuses?per_page=100&page=1"
                        ),
                        "http_status": 200,
                        "date_header": date_header,
                        "link_header": link_header,
                        "raw_body_utf8": raw_body,
                        "raw_body_sha256": hashlib.sha256(
                            raw_body.encode("utf-8")
                        ).hexdigest(),
                    }
                ],
                "graphql_status_context_rereads": (
                    graphql_status_context_rereads(
                        statuses,
                        commit_sha=commit_sha,
                        date_header=date_header,
                    )
                ),
            }

        def raw_json_capture(
            request_url: str,
            payload: dict[str, object],
            *,
            date_header: str = "Sun, 09 Aug 2026 12:00:00 GMT",
        ) -> dict[str, object]:
            raw_body = json.dumps(
                payload,
                ensure_ascii=False,
                separators=(",", ":"),
                sort_keys=True,
            )
            return {
                "request_url": request_url,
                "http_status": 200,
                "date_header": date_header,
                "raw_body_utf8": raw_body,
                "raw_body_sha256": hashlib.sha256(
                    raw_body.encode("utf-8")
                ).hexdigest(),
            }

        def producer_receipt_archive(
            receipt: dict[str, object],
            *,
            members: list[tuple[str, str]] | None = None,
        ) -> bytes:
            receipt_raw = json.dumps(
                receipt,
                ensure_ascii=False,
                separators=(",", ":"),
                sort_keys=True,
            )
            selected_members = members or [
                ("codex-review-gate-producer-receipt.json", receipt_raw)
            ]
            archive_buffer = io.BytesIO()
            with zipfile.ZipFile(
                archive_buffer,
                "w",
                compression=zipfile.ZIP_STORED,
            ) as archive:
                for member_name, member_raw in selected_members:
                    member = zipfile.ZipInfo(
                        member_name,
                        date_time=(2026, 8, 9, 12, 0, 0),
                    )
                    member.compress_type = zipfile.ZIP_STORED
                    archive.writestr(member, member_raw.encode("utf-8"))
            return archive_buffer.getvalue()

        def producer_receipt_evidence(
            selected_status: dict[str, object],
            *,
            additional_receipt_statuses: list[dict[str, object]] | None = None,
            workflow_sha_candidate_kind: str = "signed-major-tag-object",
            release_version: str = "1.5.1",
        ) -> dict[str, object]:
            if workflow_sha_candidate_kind == "signed-major-tag-object":
                selected_workflow_sha = called_tag_object_oid
            elif workflow_sha_candidate_kind == "exact-action-commit":
                selected_workflow_sha = called_commit
            else:
                raise ValueError("unsupported workflow SHA candidate kind")
            run_id = required_action_producer_binding["workflow_run_id"]
            run_attempt = required_action_producer_binding[
                "workflow_run_attempt"
            ]
            workflow_run_url = required_action_producer_binding[
                "workflow_run_url"
            ]
            caller_workflow_path = required_action_producer_binding[
                "caller_workflow_path"
            ]
            caller_workflow_raw = _ACTION_CANONICAL_CALLER_WORKFLOW_BODY
            called_workflow_raw = _canonical_action_called_workflow_fixture(
                release_version=release_version
            )
            caller_workflow_ref = (
                f"OWNER/REPO/{caller_workflow_path}@refs/heads/master"
            )
