        def canonical_record_sha256(record: object) -> str:
            return hashlib.sha256(
                json.dumps(
                    record,
                    ensure_ascii=False,
                    separators=(",", ":"),
                    sort_keys=True,
                ).encode("utf-8")
            ).hexdigest()

        def component_readback_identity(
            coordinate: dict[str, object],
        ) -> str:
            return canonical_record_sha256(
                {
                    key: coordinate[key]
                    for key in (
                        "store_id",
                        "store_revision",
                        "store_entry_index",
                        "entry_sha256",
                    )
                }
            )

        def register_focused_required_status_membership(
            status_authority: dict[str, object],
        ) -> dict[str, object]:
            components: list[dict[str, object]] = []
            for role in _REQUIRED_STATUS_READBACK_ROLES:
                store_id = f"github-codex-required-status:{role}"
                records = parent_required_status_component_stores.setdefault(
                    store_id, []
                )
                record = {
                    "role": role,
                    "review_epoch": copy.deepcopy(status_review_epoch),
                    "selected_status_state": (
                        status_authority["selected_status_state"]
                        if role == "final-status-capture"
                        else None
                    ),
                }
                records.append(record)
                coordinate = {
                    "role": role,
                    "store_id": store_id,
                    "store_revision": len(records),
                    "store_entry_index": len(records) - 1,
                    "entry_sha256": canonical_record_sha256(record),
                }
                coordinate["readback_identity_sha256"] = (
                    canonical_record_sha256(coordinate)
                )
                components.append(coordinate)
            registry_revision = components[0]["store_revision"]
            registry_id = (
                "github-codex-required-status-membership:"
                + canonical_record_sha256(
                    {
                        "review_epoch": status_review_epoch,
                        "components": components,
                    }
                )
            )
            registry_readback = {
                "registry_id": registry_id,
                "registry_revision": registry_revision,
                "components": components,
            }
            return {
                "kind": (
                    "github-codex-required-status-authority-membership-v1"
                ),
                "review_epoch": copy.deepcopy(status_review_epoch),
                "registry_id": registry_id,
                "registry_revision": registry_revision,
                "components": components,
                "registry_readback_identity_sha256": (
                    canonical_record_sha256(registry_readback)
                ),
            }

        def load_focused_required_status_membership(
            membership: object,
        ) -> str | None:
            membership_fields = {
                "kind",
                "review_epoch",
                "registry_id",
                "registry_revision",
                "components",
                "registry_readback_identity_sha256",
            }
            if (
                not isinstance(membership, dict)
                or set(membership) != membership_fields
                or membership.get("kind")
                != "github-codex-required-status-authority-membership-v1"
                or not _type_sensitive_json_equal(
                    membership.get("review_epoch"), status_review_epoch
                )
                or not isinstance(membership.get("components"), list)
                or [
                    component.get("role")
                    for component in membership["components"]
                    if isinstance(component, dict)
                ]
                != list(_REQUIRED_STATUS_READBACK_ROLES)
            ):
                return None
            registry_readback = {
                "registry_id": membership.get("registry_id"),
                "registry_revision": membership.get("registry_revision"),
                "components": membership["components"],
            }
            if membership.get("registry_readback_identity_sha256") != (
                canonical_record_sha256(registry_readback)
            ):
                return None
            selected_status_state: object = None
            for component in membership["components"]:
                if (
                    not isinstance(component, dict)
                    or set(component)
                    != {
                        "role",
                        "store_id",
                        "store_revision",
                        "store_entry_index",
                        "entry_sha256",
                        "readback_identity_sha256",
                    }
                    or type(component.get("store_revision")) is not int
                    or type(component.get("store_entry_index")) is not int
                    or component.get("readback_identity_sha256")
                    != canonical_record_sha256(
                        {
                            key: component[key]
                            for key in component
                            if key != "readback_identity_sha256"
                        }
                    )
                ):
                    return None
                records = parent_required_status_component_stores.get(
                    component["store_id"]
                )
                if (
                    not isinstance(records, list)
                    or component["store_revision"] != len(records)
                    or not 0
                    <= component["store_entry_index"]
                    < len(records)
                ):
                    return None
                record = records[component["store_entry_index"]]
                if (
                    canonical_record_sha256(record)
                    != component["entry_sha256"]
                    or record.get("role") != component["role"]
                    or not _type_sensitive_json_equal(
                        record.get("review_epoch"), status_review_epoch
                    )
                ):
                    return None
                if component["role"] == "final-status-capture":
                    selected_status_state = record.get(
                        "selected_status_state"
                    )
            return (
                selected_status_state
                if selected_status_state
                in {"success", "failure", "pending", "error"}
                else None
            )

        def register_reduction_component(
            store_id: str,
            record: dict[str, object],
        ) -> dict[str, object]:
            records = parent_reduction_component_stores.setdefault(
                store_id, []
            )
            records.append(copy.deepcopy(record))
            coordinate = {
                "store_id": store_id,
                "store_revision": len(records),
                "store_entry_index": len(records) - 1,
                "entry_sha256": canonical_record_sha256(record),
            }
            coordinate["readback_identity_sha256"] = (
                component_readback_identity(coordinate)
            )
            return coordinate

        def load_reduction_component(
            coordinate: object,
            *,
            expected_store_id: str,
        ) -> dict[str, object] | None:
            if (
                not isinstance(coordinate, dict)
                or set(coordinate)
                != {
                    "store_id",
                    "store_revision",
                    "store_entry_index",
                    "entry_sha256",
                    "readback_identity_sha256",
                }
                or coordinate.get("store_id") != expected_store_id
                or type(coordinate.get("store_revision")) is not int
                or type(coordinate.get("store_entry_index")) is not int
                or not isinstance(coordinate.get("entry_sha256"), str)
                or re.fullmatch(
                    r"[0-9a-f]{64}", coordinate["entry_sha256"]
                )
                is None
                or not isinstance(
                    coordinate.get("readback_identity_sha256"), str
                )
                or re.fullmatch(
                    r"[0-9a-f]{64}",
                    coordinate["readback_identity_sha256"],
                )
                is None
            ):
                return None
            records = parent_reduction_component_stores.get(
                expected_store_id
            )
            if (
                not isinstance(records, list)
                or coordinate["store_revision"] != len(records)
                or not 0
                <= coordinate["store_entry_index"]
                < len(records)
                or coordinate["readback_identity_sha256"]
                != component_readback_identity(coordinate)
            ):
                return None
            record = records[coordinate["store_entry_index"]]
            if canonical_record_sha256(record) != coordinate["entry_sha256"]:
                return None
            return copy.deepcopy(record)

        def reduction_readback_identity(
            coordinate: dict[str, object],
        ) -> str:
            return canonical_record_sha256(
                {
                    key: coordinate[key]
                    for key in (
                        "reduction_store_id",
                        "reduction_store_revision",
                        "reduction_store_entry_index",
                        "reduction_entry_sha256",
                    )
                }
            )

        def register_reduction_record(
            record: dict[str, object],
        ) -> dict[str, object]:
            parent_reduction_store.append(copy.deepcopy(record))
            coordinate = {
                "kind": (
                    "github-codex-sealed-reduction-authority-coordinate-v1"
                ),
                "reduction_store_id": "github-codex-reduction-authorities",
                "reduction_store_revision": len(parent_reduction_store),
                "reduction_store_entry_index": (
                    len(parent_reduction_store) - 1
                ),
                "reduction_entry_sha256": canonical_record_sha256(record),
            }
            coordinate["reduction_readback_identity_sha256"] = (
                reduction_readback_identity(coordinate)
            )
            return coordinate

        def load_reduction_authority_payload(
            coordinate: object,
        ) -> dict[str, object] | None:
            if (
                not isinstance(coordinate, dict)
                or set(coordinate)
                != {
                    "kind",
                    "reduction_store_id",
                    "reduction_store_revision",
                    "reduction_store_entry_index",
                    "reduction_entry_sha256",
                    "reduction_readback_identity_sha256",
                }
                or coordinate.get("kind")
                != "github-codex-sealed-reduction-authority-coordinate-v1"
                or coordinate.get("reduction_store_id")
                != "github-codex-reduction-authorities"
                or type(coordinate.get("reduction_store_revision")) is not int
                or coordinate["reduction_store_revision"]
                != len(parent_reduction_store)
                or type(coordinate.get("reduction_store_entry_index"))
                is not int
                or not 0
                <= coordinate["reduction_store_entry_index"]
                < len(parent_reduction_store)
                or coordinate.get("reduction_readback_identity_sha256")
                != reduction_readback_identity(coordinate)
            ):
                return None
            record = parent_reduction_store[
                coordinate["reduction_store_entry_index"]
            ]
            if (
                canonical_record_sha256(record)
                != coordinate.get("reduction_entry_sha256")
                or set(record)
                != {
                    "kind",
                    "review_epoch",
                    "required_action_status_registry_membership_coordinate",
                    "provider_validation_coordinate",
                    "epoch_first_attempt_clock_coordinate",
                    "current_marker_attempt_coordinate",
                }
                or record.get("kind")
                != "github-codex-sealed-reduction-authority-record-v1"
                or not isinstance(record.get("review_epoch"), dict)
                or set(record["review_epoch"])
                != {
                    "repository_id",
                    "repository_full_name",
                    "pull_request_number",
                    "pr_merge_base",
                    "head_sha",
                }
                or type(record["review_epoch"].get("repository_id")) is not int
                or not isinstance(
                    record["review_epoch"].get("repository_full_name"), str
                )
                or type(record["review_epoch"].get("pull_request_number"))
                is not int
                or any(
                    not isinstance(record["review_epoch"].get(field), str)
                    or re.fullmatch(
                        r"[0-9a-f]{40}", record["review_epoch"][field]
                    )
                    is None
                    for field in ("pr_merge_base", "head_sha")
                )
            ):
                return None
            component_specs = {
                "required_action_status_registry_membership_coordinate": (
                    "github-codex-required-status-memberships",
                    "github-codex-required-status-authority-membership-v1",
                ),
                "provider_validation_coordinate": (
                    "github-codex-provider-validations",
                    "github-codex-provider-validation-v1",
                ),
                "epoch_first_attempt_clock_coordinate": (
                    "github-codex-epoch-first-attempt-clocks",
                    "github-codex-epoch-first-attempt-clock-v1",
                ),
                "current_marker_attempt_coordinate": (
                    "github-codex-current-marker-attempts",
                    "github-codex-current-marker-attempt-v1",
                ),
            }
            loaded_components: dict[str, dict[str, object]] = {}
            for field, (store_id, kind) in component_specs.items():
                component = load_reduction_component(
                    record.get(field),
                    expected_store_id=store_id,
                )
                if (
                    component is None
                    or component.get("kind") != kind
                    or not _type_sensitive_json_equal(
                        component.get("review_epoch"),
                        record["review_epoch"],
                    )
                ):
                    return None
                loaded_components[field] = component
            status_component = loaded_components[
                "required_action_status_registry_membership_coordinate"
            ]
            provider_component = loaded_components[
                "provider_validation_coordinate"
            ]
            clock_component = loaded_components[
                "epoch_first_attempt_clock_coordinate"
            ]
            marker_component = loaded_components[
                "current_marker_attempt_coordinate"
            ]
            selected_status_state = (
                load_focused_required_status_membership(status_component)
            )
            if (
                selected_status_state is None
                or provider_component.get("current_head")
                != record["review_epoch"].get("head_sha")
                or provider_component.get("provider_classification")
                not in {
                    "clean",
                    "findings",
                    "progress",
                    "transient-incomplete",
                    "malformed",
                    "pending",
                    "inconclusive",
                }
                or not isinstance(provider_component.get("provider_events"), list)
                or type(clock_component.get("first_authenticated_epoch_date"))
                is not int
                or clock_component.get("overall_deadline_at")
                != clock_component["first_authenticated_epoch_date"]
                + _ACTION_OVERALL_TIMEOUT_SECONDS
                or not isinstance(marker_component.get("marker"), dict)
                or marker_component["marker"].get(
                    "epoch_first_attempt_write_ahead_created_at"
                )
                != clock_component["first_authenticated_epoch_date"]
            ):
                return None
            provider_events = provider_component["provider_events"]
            if not isinstance(provider_events, list) or not all(
                isinstance(event, dict) for event in provider_events
            ):
                return None
            return {
                "review_epoch": copy.deepcopy(record["review_epoch"]),
                "current_head": provider_component["current_head"],
                "selected_status_state": selected_status_state,
                "provider_classification": provider_component[
                    "provider_classification"
                ],
                "provider_events": copy.deepcopy(provider_events),
                "marker": copy.deepcopy(marker_component["marker"]),
                "ancestry_budget_remaining": provider_component.get(
                    "ancestry_budget_remaining"
                ),
                "acquisition_budget_remaining": provider_component.get(
                    "acquisition_budget_remaining"
                ),
                "watermark_head": provider_component.get("watermark_head"),
                "eyes_observed": provider_component.get("eyes_observed"),
                "plus_one_observed": provider_component.get(
                    "plus_one_observed"
                ),
            }

        def load_reduction_authority_coordinate(
            coordinate: object,
        ) -> _ValidatedGithubCodexReductionAuthorityCoordinate | None:
            if load_reduction_authority_payload(coordinate) is None:
                return None
            assert isinstance(coordinate, dict)
            issuance_token = object()
            issued_reduction_coordinates[issuance_token] = copy.deepcopy(
                coordinate
            )

            def load_issued_reduction_authority(
                token: object,
            ) -> dict[str, object] | None:
                issued_coordinate = issued_reduction_coordinates.get(token)
                if not isinstance(issued_coordinate, dict):
                    return None
                initial = load_reduction_authority_payload(issued_coordinate)
                final = load_reduction_authority_payload(issued_coordinate)
                if (
                    initial is None
                    or final is None
                    or not _type_sensitive_json_equal(initial, final)
                ):
                    return None
                return final

            return _register_validated_github_codex_reduction_authority(
                registrar_capability=(
                    _VALIDATED_GITHUB_CODEX_REDUCTION_REGISTRAR_CAPABILITY
                ),
                issuance_token=issuance_token,
                public_coordinate=coordinate,
                parent_loader=load_issued_reduction_authority,
            )

        def mint_reduction_authority_coordinate(
            *,
            status_authority: dict[str, object],
            projected_events: object,
            logic_arguments: dict[str, object],
        ) -> tuple[
            dict[str, object],
            _ValidatedGithubCodexReductionAuthorityCoordinate | None,
        ]:
            provider_projection = projected_events
            selected_marker = logic_arguments.pop(
                "marker", copy.deepcopy(marker)
            )
            if not isinstance(provider_projection, list) or not all(
                isinstance(event, dict) for event in provider_projection
            ):
                return {}, None
            provider_kinds = {
                event.get("kind") for event in provider_projection
            }
            if "finding" in provider_kinds:
                provider_classification = "findings"
            elif "malformed" in provider_kinds:
                provider_classification = "malformed"
            elif "transient-incomplete" in provider_kinds:
                provider_classification = "transient-incomplete"
            elif "progress" in provider_kinds:
                provider_classification = "progress"
            elif "clean" in provider_kinds:
                provider_classification = "clean"
            else:
                provider_classification = "pending"
            component_records = {
                "required_action_status_registry_membership_coordinate": (
                    "github-codex-required-status-memberships",
                    register_focused_required_status_membership(
                        status_authority
                    ),
                ),
                "provider_validation_coordinate": (
                    "github-codex-provider-validations",
                    {
                        "kind": "github-codex-provider-validation-v1",
                        "review_epoch": copy.deepcopy(status_review_epoch),
                        "current_head": current_head,
                        "provider_classification": provider_classification,
                        "provider_events": copy.deepcopy(
                            provider_projection
                        ),
                        "ancestry_budget_remaining": logic_arguments.pop(
                            "ancestry_budget_remaining", True
                        ),
                        "acquisition_budget_remaining": logic_arguments.pop(
                            "acquisition_budget_remaining", True
                        ),
                        "watermark_head": logic_arguments.pop(
                            "watermark_head", None
                        ),
                        "eyes_observed": logic_arguments.pop(
                            "eyes_observed", False
                        ),
                        "plus_one_observed": logic_arguments.pop(
                            "plus_one_observed", False
                        ),
                    },
                ),
                "epoch_first_attempt_clock_coordinate": (
                    "github-codex-epoch-first-attempt-clocks",
                    {
                        "kind": (
                            "github-codex-epoch-first-attempt-clock-v1"
                        ),
                        "review_epoch": copy.deepcopy(status_review_epoch),
                        "first_authenticated_epoch_date": selected_marker[
                            "epoch_first_attempt_write_ahead_created_at"
                        ],
                        "overall_deadline_at": selected_marker[
                            "epoch_first_attempt_write_ahead_created_at"
                        ]
                        + _ACTION_OVERALL_TIMEOUT_SECONDS,
                    },
                ),
                "current_marker_attempt_coordinate": (
                    "github-codex-current-marker-attempts",
                    {
                        "kind": "github-codex-current-marker-attempt-v1",
                        "review_epoch": copy.deepcopy(status_review_epoch),
                        "marker": copy.deepcopy(selected_marker),
                    },
                ),
            }
            sealed_record: dict[str, object] = {
                "kind": (
                    "github-codex-sealed-reduction-authority-record-v1"
                ),
                "review_epoch": copy.deepcopy(status_review_epoch),
            }
            for field, (store_id, record) in component_records.items():
                sealed_record[field] = register_reduction_component(
                    store_id, record
                )
            coordinate = register_reduction_record(sealed_record)
            return coordinate, load_reduction_authority_coordinate(coordinate)

        def reduce_logic_fixture(
            projected_events: object,
            **overrides: object,
        ) -> dict[str, object]:
            _ = overrides
            return _reduce_github_codex_lane_logic_fixture(
                sealed_reduction_authority_coordinate=projected_events,
            )

        def reduce(
            projected_events: list[dict[str, object]],
            **overrides: object,
        ) -> dict[str, object]:
            # This raw-parser table is non-authoritative. The composed
            # integration below accepts only parent-owned readback coordinates.
            if "resource_budget_ledger" in overrides:
                return {
                    "decision": "ERROR",
                    "action_status": "error",
                    "reason": "caller-budget-projection-forbidden",
                    "marker_state": None,
                    "deadline_at": None,
                    "automatic_post_count": 0,
                }
            logic_arguments = {
                key: overrides.pop(key)
                for key in tuple(overrides)
                if key
                in {
                    "marker",
                    "ancestry_budget_remaining",
                    "acquisition_budget_remaining",
                    "watermark_head",
                    "eyes_observed",
                    "plus_one_observed",
                }
            }
            arguments: dict[str, object] = {
                "expected_review_epoch": copy.deepcopy(
                    status_review_epoch
                ),
                "current_pull_request_number": current_pull_request_number,
                "current_head": current_head,
                "initial_status_receipt": copy.deepcopy(
                    initial_status_receipt
                ),
                "final_status_receipt": copy.deepcopy(final_status_receipt),
                "required_action_producer_binding": copy.deepcopy(
                    required_action_producer_binding
                ),
                "required_action_producer_receipt": copy.deepcopy(
                    required_action_producer_receipt
                ),
                "required_action_release_policy": copy.deepcopy(
                    required_action_release_policy
                ),
                "resource_budget_ledger": (
                    _new_evidence_resource_budget_ledger(
                        evidence_resource_budget_authority
                    )
                ),
            }
            arguments.update(overrides)
            status_authority = (
                _parse_github_codex_action_status_authority_fixture(
                    **arguments
                )
            )
            if status_authority.get("valid") is not True:
                return {
                    "decision": "ERROR",
                    "action_status": "error",
                    "reason": status_authority.get("reason"),
                    "marker_state": None,
                    "deadline_at": None,
                    "automatic_post_count": 0,
                }
            _, sealed_authority = mint_reduction_authority_coordinate(
                status_authority=status_authority,
                projected_events=projected_events,
                logic_arguments=logic_arguments,
            )
            if sealed_authority is None:
                return {
                    "decision": "ERROR",
                    "action_status": "error",
                    "reason": "sealed-reduction-authority-invalid",
                    "marker_state": None,
                    "deadline_at": None,
                    "automatic_post_count": 0,
                }
            return _reduce_github_codex_lane_logic_fixture(
                sealed_reduction_authority_coordinate=sealed_authority,
            )

