        for case, (events, overrides, expected) in table.items():
            with self.subTest(action_status_reduction=case):
                reduced = reduce(events, **overrides)
                self.assertEqual(
                    (reduced["decision"], reduced["action_status"]),
                    expected,
                )
                if case == "progress-preserves-deadline":
                    self.assertEqual(reduced["deadline_at"], marker["deadline_at"])
                if case == "deterministic-malformed":
                    self.assertEqual(reduced["automatic_post_count"], 0)
                if case == "plus-one-has-no-pass-or-ack":
                    self.assertEqual(reduced["marker_state"], "waiting_ack")
                if case == "eyes-only-acks":
                    self.assertEqual(reduced["marker_state"], "waiting_result")
                    self.assertEqual(reduced["deadline_at"], marker["deadline_at"])

