        def reseal_workflow_authority(
            candidate: dict[str, object],
            workflow_raw: str,
            *,
            update_independent_pin: bool,
        ) -> None:
            del update_independent_pin
            workflow_digest = hashlib.sha256(
                workflow_raw.encode("utf-8")
            ).hexdigest()
            evidence = candidate["required_action_producer_receipt"]
            assert isinstance(evidence, dict)
            for phase in ("initial", "final"):
                capture = evidence[f"{phase}_caller_workflow_capture"]
                assert isinstance(capture, dict)
                capture["raw_body_utf8"] = workflow_raw
                capture["raw_body_sha256"] = workflow_digest

