        base_workflow_raw = base_workflow_capture["raw_body_utf8"]
        assert isinstance(base_workflow_raw, str)
        expected_action_uses = _ACTION_REUSABLE_WORKFLOW_SELECTOR
        exact_uses_pattern = re.compile(
            rf"(?m)^(\s*(?:-\s*)?uses:\s*)"
            rf"{re.escape(expected_action_uses)}"
            r"(\s*(?:#.*)?)$"
        )
        self.assertEqual(
            len(exact_uses_pattern.findall(base_workflow_raw)),
            1,
            "the caller contains one canonical reusable job-level use",
        )

