        candidate = negative_case()
        evidence = candidate["required_action_producer_receipt"]

        def collide_with_non_tree_ancestor(
            payload: dict[str, object],
        ) -> None:
            tree_entries = payload.get("tree")
            assert isinstance(tree_entries, list)
            matches = [
                entry
                for entry in tree_entries
                if isinstance(entry, dict)
                and entry.get("path") == ".github"
            ]
            self.assertEqual(len(matches), 1)
            entry = matches[0]
            oid = entry["sha"]
