        class CandidateDeadlineGraph(dict):
            def __deepcopy__(self, memo: dict[int, object]) -> object:
                return copy.deepcopy(dict(self), memo)

            def get(
                self,
                key: object,
                default: object = None,
            ) -> object:
                if key == "critical_file_captures":
                    candidate_deadline_state["now"] = float(
                        candidate_deadline_seconds + 1
                    )
                    candidate_deadline_state["triggered"] = True
                return super().get(key, default)

        class CandidateAccessProbeGraph(dict):
            def __deepcopy__(self, memo: dict[int, object]) -> object:
                return copy.deepcopy(dict(self), memo)

            def get(
                self,
                key: object,
                default: object = None,
            ) -> object:
                if key == "critical_file_captures":
                    candidate_deadline_state[
                        "second_candidate_late_reads"
                    ] = (
                        int(
                            candidate_deadline_state[
                                "second_candidate_late_reads"
                            ]
                        )
                        + 1
                    )
                return super().get(key, default)

