        status_negative_cases[
            "release-source-commit-tree-canonical-url-mismatch"
        ] = candidate

        candidate = negative_case()
        evidence = candidate["required_action_producer_receipt"]
        for release_capture in release_admission_captures(evidence):
            asset_inventory = primary_release_candidate(release_capture)[
                "release_asset_inventory_capture"
            ]
            assert isinstance(asset_inventory, dict)
            endpoint = asset_inventory["endpoint_url"]
            pages = asset_inventory["pages"]
            assert isinstance(endpoint, str)
            assert isinstance(pages, list) and len(pages) == 1
            page = pages[0]
            assert isinstance(page, dict)
            page["link_header"] = (
                f'<{re.sub(r"&page=1$", "&page=2", endpoint)}>; '
                'rel="next"'
            )
        status_negative_cases[
            "release-assets-hidden-next-page"
        ] = candidate

        candidate = negative_case()
        evidence = candidate["required_action_producer_receipt"]
        for release_capture in release_admission_captures(evidence):
            graph = primary_release_candidate(release_capture)
            asset_page, asset_rows = release_inventory_rows(
                graph["release_asset_inventory_capture"]
            )
            selected_name = (
                f"{graph['release_tag']}-release-provenance.json"
            )
            selected_assets = [
                asset
                for asset in asset_rows
                if isinstance(asset, dict)
                and asset.get("name") == selected_name
            ]
            self.assertEqual(len(selected_assets), 1)
            duplicate_asset = copy.deepcopy(selected_assets[0])
            duplicate_asset["id"] = int(duplicate_asset["id"]) + 99_000
            asset_rows.append(duplicate_asset)
            reseal_list_capture(asset_page, asset_rows)
        status_negative_cases[
            "release-assets-duplicate-selected-provenance-name"
        ] = candidate

        candidate = negative_case()
        evidence = candidate["required_action_producer_receipt"]
        mutate_selected_release_asset(
            evidence,
            lambda asset: asset.__setitem__("digest", f"sha256:{'0' * 64}"),
        )
        status_negative_cases[
            "release-provenance-asset-digest-mismatch"
        ] = candidate

        candidate = negative_case()
        evidence = candidate["required_action_producer_receipt"]
        mutate_candidate_provenance(
            evidence,
            lambda payload: payload["source"].__setitem__(
                "commit_oid", called_commit
            ),
        )
        status_negative_cases[
            "release-source-commit-incorrectly-used-as-C"
        ] = candidate

        candidate = negative_case()
        evidence = candidate["required_action_producer_receipt"]
        mutate_candidate_provenance(
            evidence,
            lambda payload: payload["source"].__setitem__(
                "repository", "OWNER/forged-source"
            ),
        )
        status_negative_cases[
            "release-source-repository-mismatch"
        ] = candidate

        candidate = negative_case()
        evidence = candidate["required_action_producer_receipt"]
        mutate_candidate_provenance(
            evidence,
            lambda payload: payload["source"].__setitem__(
                "tree_oid", "0" * 40
            ),
        )
        status_negative_cases[
            "release-source-root-tree-OID-mismatch"
        ] = candidate

        candidate = negative_case()
        evidence = candidate["required_action_producer_receipt"]
        mutate_candidate_provenance(
            evidence,
            lambda payload: payload["proofs"].__setitem__(
                "source_subtree_equals_action_root", False
            ),
        )
        status_negative_cases[
            "release-source-subtree-proof-false"
        ] = candidate

        candidate = negative_case()
        evidence = candidate["required_action_producer_receipt"]
        mutate_candidate_provenance(
            evidence,
            lambda payload: payload["critical_files"][
                "reusable_workflow"
            ].__setitem__("frozen_admission_sha256", "0" * 64),
        )
        status_negative_cases[
            "release-reusable-workflow-frozen-digest-mismatch"
        ] = candidate

        for case, overrides in status_negative_cases.items():
            with self.subTest(required_status_authority_negative=case):
                reduced = reduce([strong_clean], **overrides)
                self.assertEqual(reduced["decision"], "ERROR")
                self.assertNotEqual(reduced["action_status"], "success")
                if case.startswith(
                    (
                        "release-final-only-protected-projection-",
                        "release-inventory-",
                        "release-commit-capture-",
                        "release-tree-capture-",
                        "release-critical-file-capture-",
                    )
                ):
                    self.assertEqual(
                        reduced["reason"],
                        "required-action-producer-receipt-invalid",
                    )
                if case == (
                    "newer-case-variant-participates-"
                    "no-exact-context-fallback"
                ):
                    self.assertEqual(
                        reduced["reason"],
                        "required-status-selected-context-not-exact",
                    )
                if case == "latest-compatibility-row-no-trusted-fallback":
                    self.assertEqual(
                        reduced["reason"],
                        "required-status-producer-mismatch",
                    )

