        _validated_completion_projection_seal = object()

        class _ValidatedCompletionMembershipProjection:
            __slots__ = (
                "membership_sha256",
                "phase_states_raw_utf8",
                "ancestry_exit_by_commit_raw_utf8",
                "capture_authority_by_check_raw_utf8",
                "artifact_commit_id",
                "snapshot_sha256",
            )

            def __init__(
                self,
                *,
                seal: object,
                membership_sha256: str,
                phase_states_raw_utf8: str,
                ancestry_exit_by_commit_raw_utf8: str,
                capture_authority_by_check_raw_utf8: str,
                artifact_commit_id: str,
                snapshot_sha256: str,
            ) -> None:
                if seal is not _validated_completion_projection_seal:
                    raise TypeError("validated projection factory is private")
                self.membership_sha256 = membership_sha256
                self.phase_states_raw_utf8 = phase_states_raw_utf8
                self.ancestry_exit_by_commit_raw_utf8 = (
                    ancestry_exit_by_commit_raw_utf8
                )
                self.capture_authority_by_check_raw_utf8 = (
                    capture_authority_by_check_raw_utf8
                )
                self.artifact_commit_id = artifact_commit_id
                self.snapshot_sha256 = snapshot_sha256

