            definitive_no_dispatch_history_raw: str | None = None
            definitive_no_dispatch_history_identity: str | None = None
            marker_ledger_revision = 0 if empty_initial_marker_ledger else 7
            if empty_marker_ledger_after_definitive_no_dispatch:
                marker_ledger_revision = 1
                marker_attempt_records = []
