        def reseal_historical_nested_receipt(
            receipt: dict[str, object],
        ) -> None:
            payload = {
                key: value
                for key, value in receipt.items()
                if key != "receipt_sha256"
            }
            receipt["receipt_sha256"] = hashlib.sha256(
                completion_json(payload).encode("utf-8")
            ).hexdigest()

        self.assertEqual(
            completion_expected_ack_backoff_by_attempt(
                {
                    "1": {"state": "missed_ack"},
                    "2": {"state": "missed_ack"},
                    "3": {"state": "missed_ack"},
                    "4": {"state": "missed_ack"},
                    "5": {"state": "posting"},
                }
            ),
            {
                1: (0, 300),
                2: (1, 600),
                3: (2, 1200),
                4: (3, 1800),
                5: (4, 1800),
            },
        )
        self.assertEqual(
            completion_expected_ack_backoff_by_attempt(
                {
                    "1": {"state": "missed_ack"},
                    "2": {"state": "post_not_persisted"},
                    "3": {"state": "posting"},
                }
            ),
            {
                1: (0, 300),
                2: (1, 600),
                3: (0, 300),
            },
        )
