        def ledger_with_rebound_marker_authority(
            mutate_authority: Callable[[dict[str, object]], None],
        ) -> dict[str, object]:
            rebound_ledger = json.loads(json.dumps(historical_nested_before))
            receipt = rebound_ledger["attempts"]["1"][
                "marker_persistence_receipt"
            ]
            assert isinstance(receipt, dict)
            membership = receipt["comment_authority_membership"]
            assert isinstance(membership, dict)
            old_readback_raw = trusted_marker_comment_authority_readbacks[
                membership["registry_readback_identity_sha256"]
            ]
            rebound_readback = strict_completion_json_loads(
                old_readback_raw
            )
            records = rebound_readback["records"]
            authority = records[membership["store_entry_index"]]
            mutate_authority(authority)
            membership["entry_sha256"] = hashlib.sha256(
                completion_json(authority).encode("utf-8")
            ).hexdigest()
            rebound_readback_raw = completion_json(rebound_readback)
            rebound_readback_identity = hashlib.sha256(
                rebound_readback_raw.encode("utf-8")
            ).hexdigest()
            trusted_marker_comment_authority_readbacks[
                rebound_readback_identity
            ] = rebound_readback_raw
            membership["registry_readback_identity_sha256"] = (
                rebound_readback_identity
            )
            reseal_historical_nested_receipt(receipt)
            return rebound_ledger

