        def mutate_ack_before_attempt_state(
            context: dict[str, object],
        ) -> None:
            before_ledger = strict_completion_json_loads(
                context["before_ledger_raw"]
            )
            before_ledger["attempts"]["1"]["state"] = "posting"
            context["before_ledger_raw"] = completion_json(before_ledger)

        def add_ack_after_root_field(
            context: dict[str, object],
        ) -> None:
            after_ledger = strict_completion_json_loads(
                context["after_ledger_raw"]
            )
            after_ledger["unexpected"] = True
            context["after_ledger_raw"] = completion_json(after_ledger)

        def remove_ack_before_attempt_field(
            context: dict[str, object],
        ) -> None:
            before_ledger = strict_completion_json_loads(
                context["before_ledger_raw"]
            )
            before_ledger["attempts"]["1"].pop("result_deadline_at")
            context["before_ledger_raw"] = completion_json(before_ledger)

        def add_ack_parent_store_field(
            context: dict[str, object],
        ) -> None:
            context["parent_receipt_store"]["unexpected"] = True

        def change_only_ack_after_completion_byte(
            context: dict[str, object],
        ) -> None:
            after_ledger = strict_completion_json_loads(
                context["after_ledger_raw"]
            )
            after_ledger["provider_artifact_completion"][
                "last_mutated_epoch_revision"
            ] -= 1
            context["after_ledger_raw"] = completion_json(after_ledger)

