            first_artifact_identity, first_transaction_identity = (
                register_valid_completion(first)
            )
            first_status, first_after = (
                parent_harness_reconcile_completion_candidate(
                initial_completion_ledger_raw,
                first,
                artifact_validation_readback_identity=(
                    first_artifact_identity
                ),
                transaction_readback_identity=first_transaction_identity,
                )
            )
            self.assertEqual(first_status, "distinct-artifact-appended")
            second = build_parent_evidence_completion_candidate(
                before_ledger_raw=first_after,
                parent_receipt_records=first["parent_receipt_store"][
                    "records"
                ],
                prior_artifact_validation_records=[
                    first["artifact_validation_record"]
                ],
                native_id=second_native_id,
                provider_outcome=second_outcome,
                semantic_server_time=second_time,
            )
            second_artifact_identity, second_transaction_identity = (
                register_valid_completion(second)
            )
            if second_native_id in {813, 815}:
                distinct_composed_results[second_native_id] = (
                    compose_github_lane_from_completion_authority(
                        required_status_coordinates=(
                            required_status_coordinates_a
                        ),
                        marker=composed_reducer_marker,
                        artifact_validation_readback_identity=(
                            second_artifact_identity
                        ),
                        transaction_readback_identity=(
                            second_transaction_identity
                        ),
                    )
                )
            second_status, second_after = (
                parent_harness_reconcile_completion_candidate(
                first_after,
                second,
                artifact_validation_readback_identity=(
                    second_artifact_identity
                ),
                transaction_readback_identity=second_transaction_identity,
                )
            )
            return second_status, strict_completion_json_loads(second_after)

