        def synchronize_preinvoke_provider_reconciliation_receipt(
            receipt: dict[str, object],
            *,
            register_parent_row: bool = False,
        ) -> str:
            row = {
                key: value
                for key, value in receipt.items()
                if key
                not in {
                    "reconciliation_raw_utf8",
                    "reconciliation_sha256",
                    "reconciliation_readback_identity_sha256",
                    "service_liveness_parent_readback_identity_sha256",
                    "final_epoch_cas_service_liveness_readback_identity_sha256",
                }
            }
            raw = completion_json(row)
            receipt["reconciliation_raw_utf8"] = raw
            receipt["reconciliation_sha256"] = hashlib.sha256(
                raw.encode("utf-8")
            ).hexdigest()
            readback_identity = hashlib.sha256(
                raw.encode("utf-8")
            ).hexdigest()
            receipt["reconciliation_readback_identity_sha256"] = (
                readback_identity
            )
            receipt[
                "service_liveness_parent_readback_identity_sha256"
            ] = readback_identity
            receipt[
                "final_epoch_cas_service_liveness_readback_identity_sha256"
            ] = readback_identity
            if register_parent_row:
                self.assertEqual(
                    register_pending_reconciliation_readback(raw),
                    readback_identity,
                )
            return hashlib.sha256(
                completion_json(receipt).encode("utf-8")
            ).hexdigest()

        def mutate_pending_evidence_registry(
            receipt: dict[str, object],
            source_kind: str,
            mutate_capture: Callable[[dict[str, object]], None],
        ) -> None:
            old_identity = receipt[
                "provider_evidence_registry_readback_identity_sha256"
            ]
            old_raw = trusted_completion_evidence_readbacks[old_identity]
            readback = strict_completion_json_loads(old_raw)
            assert isinstance(readback, dict)
            records = readback["records"]
            assert isinstance(records, list)
            record = next(
                item
                for item in records
                if isinstance(item, dict)
                and item.get("source_kind") == source_kind
            )
            capture = strict_completion_json_loads(record["capture_raw_utf8"])
            assert isinstance(capture, dict)
            mutate_capture(capture)
            capture_raw = completion_json(capture)
            capture_sha256 = hashlib.sha256(
                capture_raw.encode("utf-8")
            ).hexdigest()
            record["capture_raw_utf8"] = capture_raw
            record["capture_raw_sha256"] = capture_sha256
            memberships = receipt["provider_evidence_memberships"]
            assert isinstance(memberships, list)
            membership = next(
                item
                for item in memberships
                if isinstance(item, dict)
                and item.get("check") == record["check"]
            )
            membership["evidence_raw_sha256"] = capture_sha256
            readback_raw = completion_json(readback)
            new_identity = register_completion_evidence_readback(readback_raw)
            receipt[
                "provider_evidence_registry_readback_identity_sha256"
            ] = new_identity
            receipt[
                "final_epoch_cas_evidence_readback_identity_sha256"
            ] = new_identity
            for item in memberships:
                assert isinstance(item, dict)
                item["evidence_readback_identity_sha256"] = new_identity

