        def make_review_thread_unresolved(
            capture: dict[str, object],
        ) -> None:
            rows = capture["pagination_rows"]
            assert isinstance(rows, list) and len(rows) == 1
            row = rows[0]
            assert isinstance(row, dict)
            response = strict_completion_json_loads(
                row["response_body_raw_utf8"]
            )
            response["data"]["repository"]["pullRequest"][
                "reviewThreads"
            ]["nodes"][0]["isResolved"] = False
            response_raw = completion_json(response)
            row["response_body_raw_utf8"] = response_raw
            row["response_body_sha256"] = hashlib.sha256(
                response_raw.encode("utf-8")
            ).hexdigest()

