        def reseal_liveness_authority(
            receipt: dict[str, object],
            capture: dict[str, object],
            *,
            receipt_inflight_keys: list[str] | None = None,
        ) -> None:
            capture_raw = completion_json(capture)
            capture_sha256 = hashlib.sha256(
                capture_raw.encode("utf-8")
            ).hexdigest()
            receipt["service_liveness_capture_raw_utf8"] = capture_raw
            receipt["service_liveness_capture_sha256"] = capture_sha256
            receipt["service_liveness_capture_membership"][
                "capture_raw_sha256"
            ] = capture_sha256
            if receipt_inflight_keys is not None:
                receipt["inflight_uncertainty_keys"] = receipt_inflight_keys
            synchronize_preinvoke_provider_reconciliation_receipt(
                receipt,
                register_parent_row=True,
            )

