        def closed_dispatch_claim_is_valid(claim: object) -> bool:
            if (
                not isinstance(claim, dict)
                or set(claim)
                != set(dispatch_claim["closed_claim_required_fields"])
                or not _type_sensitive_json_equal(
                    claim.get("review_epoch"), claimed_epoch
                )
                or type(claim.get("attempt")) is not int
                or claim["attempt"] <= 0
                or claim.get("marker_body_sha256") != marker_body_sha256
                or claim.get("dispatch_guard_receipt_sha256")
                != dispatch_guard_receipt_sha256
                or claim.get("provider_reconciliation_receipt_sha256")
                != provider_reconciliation_receipt_sha256
                or not isinstance(
                    claim.get("request_plane_producer_id"), str
                )
                or not claim["request_plane_producer_id"]
                or type(claim.get("request_plane_latest_revision")) is not int
                or claim["request_plane_latest_revision"] < 0
                or claim.get("process_nonce_sha256") != process_nonce_sha256
                or claim.get("expected_preclaim_epoch_revision") != 11
                or claim.get("claimed_epoch_revision") != 12
                or claim.get("dispatch_guard_clock_kind") != "CLOCK_BOOTTIME"
                or claim.get(
                    "dispatch_guard_clock_continuity_receipt_sha256"
                )
                != expected_continuity_digest
                or type(claim.get("claim_monotonic_ns")) is not int
                or claim["claim_monotonic_ns"] < 0
            ):
                return False
            for digest_field in (
                "marker_body_sha256",
                "dispatch_guard_receipt_sha256",
                "provider_reconciliation_receipt_sha256",
                "request_plane_readback_identity_sha256",
                "process_nonce_sha256",
                "dispatch_guard_clock_continuity_receipt_sha256",
            ):
                if (
                    re.fullmatch(r"[0-9a-f]{64}", claim[digest_field])
                    is None
                ):
                    return False
            return True

        def scope_and_lifecycle_receipt_classification(
            receipt: object,
        ) -> str | None:
            if (
                not isinstance(receipt, dict)
                or set(receipt) != set(scope_contract["closed_required_fields"])
            ):
                return None
            pull = receipt.get("pull_detail")
            compare = receipt.get("compare")
            response_base_fields = set(
                scope_snapshot_contract[
                    "pull_detail_and_compare_response_closed_required_fields"
                ]
            )
            if (
                not isinstance(pull, dict)
                or not isinstance(compare, dict)
                or set(pull)
                != response_base_fields
                | set(
                    scope_snapshot_contract[
                        "pull_detail_additional_required_fields"
                    ]
                )
                or set(compare)
                != response_base_fields
                | set(
                    scope_snapshot_contract[
                        "compare_additional_required_fields"
                    ]
                )
            ):
                return None
            for response, resource_kind, canonical_url in (
                (
                    pull,
                    scope_snapshot_contract["resource_kind_exact_values"][
                        "pull_detail"
                    ],
                    expected_pull_url,
                ),
                (
                    compare,
                    scope_snapshot_contract["resource_kind_exact_values"][
                        "compare"
                    ],
                    expected_compare_url,
                ),
            ):
                raw_body = response.get("raw_response_body_utf8")
                if (
                    response.get("resource_kind") != resource_kind
                    or response.get("request_method")
                    != scope_snapshot_contract["request_method_exact"]
                    or response.get("canonical_request_url") != canonical_url
                    or type(response.get("http_status")) is not int
                    or response["http_status"]
                    != scope_snapshot_contract["http_status_exact"]
                    or response.get("authenticated_operating_identity")
                    != authenticated_identity
                    or _parse_github_rfc3339_seconds(
                        response.get("http_date")
                    )
                    is None
                    or not isinstance(raw_body, str)
                    or response.get("raw_response_body_sha256")
                    != hashlib.sha256(raw_body.encode("utf-8")).hexdigest()
                ):
                    return None
            pull_date = _parse_github_rfc3339_seconds(pull["http_date"])
            compare_date = _parse_github_rfc3339_seconds(compare["http_date"])
            if (
                pull_date is None
                or compare_date is None
                or pull_date < claim_bound_latest_authenticated_date_seconds
                or compare_date < pull_date
            ):
                return None
            try:
                pull_payload = strict_completion_json_loads(
                    pull["raw_response_body_utf8"]
                )
                compare_payload = strict_completion_json_loads(
                    compare["raw_response_body_utf8"]
                )
            except (TypeError, UnicodeError, ValueError):
                return None
            if (
                not isinstance(pull_payload, dict)
                or not isinstance(compare_payload, dict)
                or not isinstance(pull_payload.get("base"), dict)
                or not isinstance(pull_payload.get("head"), dict)
                or not isinstance(pull_payload["base"].get("repo"), dict)
                or not isinstance(compare_payload.get("base_commit"), dict)
                or not isinstance(
                    compare_payload.get("merge_base_commit"), dict
                )
            ):
                return None
            derived_epoch = {
                "repository_id": pull_payload["base"]["repo"].get("id"),
                "repository_full_name": pull_payload["base"]["repo"].get(
                    "full_name"
                ),
                "pull_request_number": pull_payload.get("number"),
                "pr_merge_base": compare_payload[
                    "merge_base_commit"
                ].get("sha"),
                "head_sha": pull_payload["head"].get("sha"),
            }
            lifecycle = {
                "state": pull_payload.get("state"),
                "merged": pull_payload.get("merged"),
                "merged_at": pull_payload.get("merged_at"),
            }
            if (
                not _type_sensitive_json_equal(
                    receipt.get("derived_review_epoch"), derived_epoch
                )
                or not _type_sensitive_json_equal(
                    receipt.get("lifecycle"), lifecycle
                )
                or not _type_sensitive_json_equal(
                    {
                        "repository_id": pull.get("repository_id"),
                        "repository_full_name": pull.get(
                            "repository_full_name"
                        ),
                        "pull_request_number": pull.get(
                            "pull_request_number"
                        ),
                        "base_ref_name": pull.get("base_ref_name"),
                        "base_ref_oid": pull.get("base_ref_oid"),
                        "head_ref_oid": pull.get("head_ref_oid"),
                        "state": pull.get("state"),
                        "merged": pull.get("merged"),
                        "merged_at": pull.get("merged_at"),
                    },
                    {
                        "repository_id": derived_epoch["repository_id"],
                        "repository_full_name": derived_epoch[
                            "repository_full_name"
                        ],
                        "pull_request_number": derived_epoch[
                            "pull_request_number"
                        ],
                        "base_ref_name": pull_payload["base"].get("ref"),
                        "base_ref_oid": pull_payload["base"].get("sha"),
                        "head_ref_oid": derived_epoch["head_sha"],
                        "state": lifecycle["state"],
                        "merged": lifecycle["merged"],
                        "merged_at": lifecycle["merged_at"],
                    },
                )
                or not _type_sensitive_json_equal(
                    {
                        "repository_id": compare.get("repository_id"),
                        "repository_full_name": compare.get(
                            "repository_full_name"
                        ),
                        "base_ref_name": compare.get("base_ref_name"),
                        "base_ref_oid": compare.get("base_ref_oid"),
                        "head_ref_oid": compare.get("head_ref_oid"),
                        "pr_merge_base": compare.get("pr_merge_base"),
                    },
                    {
                        "repository_id": derived_epoch["repository_id"],
                        "repository_full_name": derived_epoch[
                            "repository_full_name"
                        ],
                        "base_ref_name": pull_payload["base"].get("ref"),
                        "base_ref_oid": compare_payload[
                            "base_commit"
                        ].get("sha"),
                        "head_ref_oid": derived_epoch["head_sha"],
                        "pr_merge_base": derived_epoch["pr_merge_base"],
                    },
                )
                or pull_payload["base"].get("sha")
                != compare_payload["base_commit"].get("sha")
            ):
                return None
            if (
                derived_epoch["repository_id"]
                != claimed_epoch["repository_id"]
                or derived_epoch["repository_full_name"]
                != claimed_epoch["repository_full_name"]
            ):
                return "repository-mismatch"
            if (
                derived_epoch["pull_request_number"]
                != claimed_epoch["pull_request_number"]
            ):
                return "pull-request-mismatch"
            if derived_epoch["head_sha"] != claimed_epoch["head_sha"]:
                return "head-mismatch"
            if (
                derived_epoch["pr_merge_base"]
                != claimed_epoch["pr_merge_base"]
            ):
                return "merge-base-mismatch"
            if not _type_sensitive_json_equal(
                lifecycle,
                {
                    "state": "open",
                    "merged": False,
                    "merged_at": None,
                },
            ):
                return "lifecycle-not-open"
            return "exact-current"

