        def append_extra_manual_transition(
            candidate: dict[str, object],
            *,
            transition_id: str,
            source_id: str,
        ) -> int:
            revision = candidate["producer"]["latest_revision"] + 1
            source_exists = any(
                source.get("source_id") == source_id
                for source in candidate["sources"]
                if isinstance(source, dict)
            )
            initial_transition = next(
                (
                    transition
                    for transition in candidate["transitions"]
                    if isinstance(transition, dict)
                    and transition.get("source_id") == source_id
                    and transition.get("previous_transition_id") is None
                ),
                None,
            )
            transition = {
                "transition_id": transition_id,
                "control_class": "manual",
                "source_id": source_id,
                "previous_transition_id": (
                    initial_transition["transition_id"]
                    if isinstance(initial_transition, dict)
                    else None
                ),
                "from_state": "pending" if source_exists else None,
                "to_state": "closed" if source_exists else "pending",
                "closure_authority_binding": (
                    request_plane_pending_closure_binding(claimed_epoch)
                    if source_exists
                    else None
                ),
                "append_revision": revision,
            }
            candidate["transitions"].append(transition)
            candidate["append_ledger"].append(
                {
                    "revision": revision,
                    "entry_kind": "transition",
                    "entry_id": transition_id,
                    "payload_sha256": hashlib.sha256(
                        completion_json(transition).encode("utf-8")
                    ).hexdigest(),
                }
            )
            candidate["producer"]["latest_revision"] = revision
            candidate["trigger_policy"]["manual"] = {
                "control_class": "manual",
                "state": transition["to_state"],
                "source_id": source_id,
                "transition_id": transition_id,
                "append_revision": revision,
            }
            return revision

