        self.assertEqual(
            invoke_after_mandatory_revalidation(
                replayed_old_head_candidate
            ),
            (preinvoke["proved_not_invoked_failure_action"], 0),
        )
        self.assertFalse(
            post_claim_transport_capability_state_by_object_id[
                id(replayed_old_head_capability)
            ]["consumed"]
        )
        convergence = transport_fences["persisted_marker_resolution_convergence"]
        self.assertEqual(
            convergence["exact_match_fields"],
            ["comment_api_id", "marker_body_sha256", "intended_marker_envelope"],
        )
        self.assertEqual(
            set(convergence["lifecycle_states_preserved_after-lifecycle-advanced"]),
            {
                "waiting_ack",
                "waiting_result",
                "missed_ack",
                "stalled",
                "timed_out",
            },
        )
        self.assertTrue(convergence["orchestration_exhausted-flag-preserved"])
        self.assertFalse(
            convergence[
                "resolution-may-regress-or-reopen-advanced-attempt-lifecycle"
            ]
        )
        lifecycle_effect_contract = convergence[
            "durable_lifecycle_effect_receipt"
        ]
        self.assertEqual(
            set(lifecycle_effect_contract["effect_union"]),
            {"enter-waiting_ack", "preserve-current"},
        )
        self.assertEqual(
            set(lifecycle_effect_contract["resolution_kind_union"]),
            {"first-resolution", "identical-loser"},
        )
        self.assertFalse(
            lifecycle_effect_contract[
                "dispatch-pending-to-resolved-persisted-allowed"
            ]
        )
        self.assertEqual(
            lifecycle_effect_contract["epoch_revision_contract"],
            {
                "first-resolution": "positive-safe-integers-with-after-equal-before-plus-one-for-the-single-atomic-fence-binding-and-lifecycle-effect-write",
                "identical-loser": "positive-safe-integer-with-before-equal-after;no-epoch-CAS-write",
            },
        )
        self.assertFalse(
            lifecycle_effect_contract[
                "epoch-artifact-completion-may-change-attempt-state"
            ]
        )
        self.assertIn(
            "surrounding-confirmed-response-or-adoption-attempt",
            lifecycle_effect_contract["resolved_attempt_contract"],
        )
        self.assertEqual(
            set(lifecycle_effect_contract["current_attempt_relation_union"]),
            {
                "resolved-attempt-current",
                "no-current-attempt",
                "proved-open-successor-current",
            },
        )
        self.assertFalse(
            lifecycle_effect_contract[
                "self_asserted-current_attempt_relation-without-ledger-proof-is-valid"
            ]
        )
        ledger_proof_contract = lifecycle_effect_contract[
            "current_attempt_ledger_proof_contract"
        ]
        self.assertTrue(ledger_proof_contract["required_for_all_relations"])
        self.assertFalse(ledger_proof_contract["additional_fields_allowed"])
        self.assertTrue(
            ledger_proof_contract[
                "must_cross_validate_against_parent_epoch_ledger_snapshots"
            ]
        )
        self.assertFalse(
            ledger_proof_contract["self-contained-or-self-hashed-proof-is-valid"]
        )
        self.assertEqual(
            ledger_proof_contract["snapshot_closed_fields_must_equal"],
            "epoch_attempt_transaction.closed_epoch_fields",
        )
        self.assertEqual(
            set(lifecycle_effect_contract["transport_fence_transition_union"]),
            {"first-resolution", "identical-loser"},
        )
        self.assertEqual(
            lifecycle_effect_contract[
                "first-resolution-with-open-successor-current-action"
            ],
            "state-conflict-preserve-open-fence-and-forbid-POST",
        )

        def lifecycle_effect_receipt_is_valid(
            receipt: object,
            *,
            parent_epoch_ledger_snapshots: object = None,
        ) -> bool:
            required_fields = set(
                lifecycle_effect_contract["closed_required_fields"]
            )
            if not isinstance(receipt, dict) or set(receipt) != required_fields:
                return False
            before = receipt.get("attempt_state_before")
            after = receipt.get("attempt_state_after")
            resolution_kind = receipt.get("resolution_kind")
            resolved_attempt = receipt.get("resolved_attempt")
            current_before = receipt.get("current_attempt_before")
            current_after = receipt.get("current_attempt_after")
            current_relation = receipt.get("current_attempt_relation")
            current_ledger_proof = receipt.get("current_attempt_ledger_proof")
            fence_before = receipt.get("transport_fence_status_before")
            fence_after = receipt.get("transport_fence_status_after")
            revision_before = receipt.get("epoch_revision_before")
            revision_after = receipt.get("epoch_revision_after")
            exhausted_before = receipt.get("orchestration_exhausted_before")
            exhausted_after = receipt.get("orchestration_exhausted_after")
            def positive_safe_integer(value: object) -> bool:
                return (
                    type(value) is int
                    and 0 < value <= 9_007_199_254_740_991
                )
            if (
                not positive_safe_integer(resolved_attempt)
                or (
                    current_before is not None
                    and not positive_safe_integer(current_before)
                )
                or current_before != current_after
                or not positive_safe_integer(revision_before)
                or type(exhausted_before) is not bool
                or exhausted_before is not exhausted_after
            ):
                return False
            first_resolution = (
                resolution_kind == "first-resolution"
                and
                fence_before in {"dispatch-entered", "posting-ambiguous"}
                and fence_after == "resolved-persisted"
            )
            identical_loser = (
                resolution_kind == "identical-loser"
                and fence_before == "resolved-persisted"
                and fence_after == "resolved-persisted"
            )
            if not (first_resolution or identical_loser):
                return False
            if first_resolution and revision_after != revision_before + 1:
                return False
            if identical_loser and revision_after != revision_before:
                return False
            relation_valid = (
                current_relation == "resolved-attempt-current"
                and current_before == resolved_attempt
            ) or (
                current_relation == "no-current-attempt"
                and current_before is None
            ) or (
                current_relation == "proved-open-successor-current"
                and positive_safe_integer(current_before)
                and current_before > resolved_attempt
            )
            if not relation_valid:
                return False
            proof_fields = set(ledger_proof_contract["closed_required_fields"])
            if (
                not isinstance(current_ledger_proof, dict)
                or set(current_ledger_proof) != proof_fields
                or not isinstance(parent_epoch_ledger_snapshots, dict)
            ):
                return False
            before_snapshot = parent_epoch_ledger_snapshots.get(revision_before)
            after_snapshot = parent_epoch_ledger_snapshots.get(revision_after)
            snapshot_fields = set(transaction["closed_epoch_fields"])
            if (
                not isinstance(before_snapshot, dict)
                or not isinstance(after_snapshot, dict)
                or set(before_snapshot) != snapshot_fields
                or set(after_snapshot) != snapshot_fields
            ):
                return False
            def snapshot_digest(snapshot: dict[str, object]) -> str:
                return hashlib.sha256(
                    json.dumps(
                        snapshot,
                        ensure_ascii=False,
                        separators=(",", ":"),
                        sort_keys=True,
                    ).encode("utf-8")
                ).hexdigest()
            before_attempts = before_snapshot.get("attempts")
            after_attempts = after_snapshot.get("attempts")
            before_fences = before_snapshot.get("transport_fences")
            after_fences = after_snapshot.get("transport_fences")
            resolved_before = (
                before_attempts.get(str(resolved_attempt))
                if isinstance(before_attempts, dict)
                else None
            )
            resolved_after = (
                after_attempts.get(str(resolved_attempt))
                if isinstance(after_attempts, dict)
                else None
            )
            resolved_fence_before = (
                before_fences.get(str(resolved_attempt))
                if isinstance(before_fences, dict)
                else None
            )
            resolved_fence_after = (
                after_fences.get(str(resolved_attempt))
                if isinstance(after_fences, dict)
                else None
            )
            if (
                current_ledger_proof.get("review_epoch")
                != before_snapshot.get("review_epoch")
                or current_ledger_proof.get("review_epoch")
                != after_snapshot.get("review_epoch")
                or current_ledger_proof.get("resolved_attempt")
                != resolved_attempt
                or current_ledger_proof.get("epoch_revision_before")
                != revision_before
                or current_ledger_proof.get("epoch_revision_after")
                != revision_after
                or current_ledger_proof.get("epoch_ledger_sha256_before")
                != snapshot_digest(before_snapshot)
                or current_ledger_proof.get("epoch_ledger_sha256_after")
                != snapshot_digest(after_snapshot)
                or before_snapshot.get("revision") != revision_before
                or after_snapshot.get("revision") != revision_after
                or before_snapshot.get("current_attempt") != current_before
                or after_snapshot.get("current_attempt") != current_after
                or before_snapshot.get("orchestration_exhausted")
                is not exhausted_before
                or after_snapshot.get("orchestration_exhausted")
                is not exhausted_after
                or not isinstance(resolved_before, dict)
                or not isinstance(resolved_after, dict)
                or resolved_before.get("state") != before
                or resolved_after.get("state") != after
                or not isinstance(resolved_fence_before, dict)
                or not isinstance(resolved_fence_after, dict)
                or resolved_fence_before.get("status") != fence_before
                or resolved_fence_after.get("status") != fence_after
            ):
                return False
            if identical_loser and (
                before_snapshot != after_snapshot
                or snapshot_digest(before_snapshot)
                != snapshot_digest(after_snapshot)
                or current_ledger_proof.get("epoch_ledger_sha256_before")
                != current_ledger_proof.get("epoch_ledger_sha256_after")
            ):
                return False
            if current_relation == "proved-open-successor-current":
                before_current = (
                    before_attempts.get(str(current_before))
                    if isinstance(before_attempts, dict)
                    else None
                )
                after_current = (
                    after_attempts.get(str(current_after))
                    if isinstance(after_attempts, dict)
                    else None
                )
                if (
                    not isinstance(before_current, dict)
                    or not isinstance(after_current, dict)
                    or before_current.get("state")
                    not in set(attempts["open_attempt_states"])
                    or after_current.get("state")
                    not in set(attempts["open_attempt_states"])
                ):
                    return False
            if receipt.get("effect") == "enter-waiting_ack":
                return (
                    before in {"posting", "posting_ambiguous"}
                    and after == "waiting_ack"
                    and current_relation == "resolved-attempt-current"
                    and first_resolution
                )
            if receipt.get("effect") == "preserve-current":
                if after != before:
                    return False
                if before in {"waiting_ack", "waiting_result"}:
                    return current_relation == "resolved-attempt-current"
                if before in {
                    "missed_ack",
                    "stalled",
                    "timed_out",
                }:
                    if first_resolution:
                        return current_relation == "no-current-attempt"
                    return current_relation in {
                        "no-current-attempt",
                        "proved-open-successor-current",
                    }
                return False
            return False

        fixture_review_epoch = {
            "repository_id": 1,
            "repository_full_name": "OWNER/REPO",
            "pull_request_number": 1,
            "pr_merge_base": "a" * 40,
            "head_sha": "b" * 40,
        }
        def completion_snapshot_digest(snapshot: object) -> str:
            return hashlib.sha256(
                json.dumps(
                    snapshot,
                    ensure_ascii=False,
                    separators=(",", ":"),
                    sort_keys=True,
                ).encode("utf-8")
            ).hexdigest()

        def pending_completion(revision: int) -> dict[str, object]:
            return {
                "kind": provider_completion["kind_exact"],
                "review_epoch": dict(fixture_review_epoch),
                "state": "pending",
                "completion_revision": 0,
                "receipt_memberships": [],
                "latest_provider_outcome": None,
                "last_mutated_epoch_revision": revision,
            }

        def uninitialized_custody(revision: int) -> dict[str, object]:
            return {
                "kind": max_wait_custody["kind_exact"],
                "review_epoch": dict(fixture_review_epoch),
                "state": "uninitialized",
                "custody_revision": 0,
                "first_authenticated_epoch_date": None,
                "cumulative_max_wait_deadline_at": None,
                "greatest_authenticated_epoch_date": None,
                "authenticated_date_receipts": [],
                "last_mutated_epoch_revision": revision,
            }

        registered_epoch_ledger = {
            "review_epoch": dict(fixture_review_epoch),
            "revision": 1,
            "current_attempt": None,
            "attempts": {},
            "transport_fences": {},
            "transport_outcome_evidence_memberships": {},
            "lifecycle_invalidated_fence": None,
            "provider_artifact_completion": pending_completion(1),
            "max_wait_authenticated_date_custody": uninitialized_custody(1),
            "max_wait_elapsed_transition": None,
            "orchestration_exhausted": False,
        }

        def completion_source_state(
            ledger: dict[str, object],
            control_class: str,
            controlled_attempt: object = None,
        ) -> dict[str, object]:
            attempts_ledger = ledger["attempts"]
            fences_ledger = ledger["transport_fences"]
            assert isinstance(attempts_ledger, dict)
            assert isinstance(fences_ledger, dict)
            selected_attempt = (
                controlled_attempt if control_class == "controlled" else None
            )
            selected_entry = attempts_ledger.get(str(selected_attempt))
            selected_fence = fences_ledger.get(str(selected_attempt))
            return {
                "control_class": control_class,
                "controlled_attempt": selected_attempt,
                "controlled_attempt_state": (
                    selected_entry.get("state")
                    if control_class == "controlled"
                    and isinstance(selected_entry, dict)
                    else None
                ),
                "controlled_transport_fence_status": (
                    selected_fence.get("status")
                    if control_class == "controlled"
                    and isinstance(selected_fence, dict)
                    else None
                ),
                "open_transport_fence_attempts": sorted(
                    int(attempt_number)
                    for attempt_number, fence in fences_ledger.items()
                    if isinstance(fence, dict)
                    and fence.get("status")
                    in {"dispatch-pending", "dispatch-entered", "posting-ambiguous"}
                ),
            }

        def make_completion_transition(
            before: dict[str, object],
            *,
            control_class: str,
            provider_outcome: str,
            controlled_attempt: int | None = None,
            semantic_server_time: str = "2027-01-15T08:00:00Z",
        ) -> tuple[dict[str, object], dict[str, object], tuple[object, ...]]:
            before_completion = before["provider_artifact_completion"]
            assert isinstance(before_completion, dict)
            next_completion_revision = before_completion["completion_revision"] + 1
            after_revision = before["revision"] + 1
            artifact_native_id = 600 + next_completion_revision
            artifact_api_url = (
                "https://api.github.com/repos/OWNER/REPO/issues/comments/"
                f"{artifact_native_id}"
            )
            artifact_get_raw = json.dumps(
                {
                    "id": artifact_native_id,
                    "url": artifact_api_url,
                    "created_at": semantic_server_time,
                    "updated_at": semantic_server_time,
                    "provider_outcome": provider_outcome,
                },
                separators=(",", ":"),
                sort_keys=True,
            )
            artifact_get_sha256 = hashlib.sha256(
                artifact_get_raw.encode("utf-8")
            ).hexdigest()
            artifact_identity = {
                "carrier": "issue-comment",
                "native_id": artifact_native_id,
                "canonical_api_url": artifact_api_url,
                "native_created_at": semantic_server_time,
                "semantic_server_time": semantic_server_time,
                "semantic_server_time_field": "created_at",
                "artifact_get_response_body_sha256": artifact_get_sha256,
            }
            artifact_scope_receipt_raw = json.dumps(
                {
                    "provider_artifact_identity": artifact_identity,
                    "provider_outcome": provider_outcome,
                    "semantic_server_time": semantic_server_time,
                    "semantic_server_time_field": "created_at",
                },
                separators=(",", ":"),
                sort_keys=True,
            )
            artifact_scope_receipt_sha256 = hashlib.sha256(
                artifact_scope_receipt_raw.encode("utf-8")
            ).hexdigest()
            provider_snapshot_raw = json.dumps(
                {
                    "complete": True,
                    "provider_artifact_identity": artifact_identity,
                    "provider_outcome": provider_outcome,
                    "semantic_server_time": semantic_server_time,
                    "semantic_server_time_field": "created_at",
                    "provider_artifact_scope_receipt_sha256": (
                        artifact_scope_receipt_sha256
                    ),
                },
                separators=(",", ":"),
                sort_keys=True,
            )
            provider_snapshot_sha256 = hashlib.sha256(
                provider_snapshot_raw.encode("utf-8")
            ).hexdigest()
            evidence_validation_raw = json.dumps(
                {
                    "kind": evidence_validation_receipt["kind_exact"],
                    "version": evidence_validation_receipt["version_exact"],
                    "review_epoch": fixture_review_epoch,
                    "provider_artifact_identity": artifact_identity,
                    "provider_outcome": provider_outcome,
                    "provider_artifact_scope_receipt_sha256": (
                        artifact_scope_receipt_sha256
                    ),
                    "complete_provider_snapshot_sha256": (
                        provider_snapshot_sha256
                    ),
                    "validated_check_memberships": [
                        {
                            "check": check,
                            "evidence_store_id": "transition-evidence-store",
                            "evidence_store_revision": len(
                                evidence_validation_receipt[
                                    "required_check_order"
                                ]
                            ),
                            "evidence_store_entry_index": entry_index,
                            "evidence_raw_sha256": hashlib.sha256(
                                f"{check}:evidence".encode("utf-8")
                            ).hexdigest(),
                            "evidence_readback_identity_sha256": (
                                hashlib.sha256(
                                    b"transition-evidence-readback"
                                ).hexdigest()
                            ),
                        }
                        for entry_index, check in enumerate(
                            evidence_validation_receipt[
                                "required_check_order"
                            ]
                        )
                    ],
                },
                separators=(",", ":"),
                sort_keys=True,
            )
            evidence_validation_sha256 = hashlib.sha256(
                evidence_validation_raw.encode("utf-8")
            ).hexdigest()
            artifact_validation_id = (
                f"transition-artifact-validation-{next_completion_revision}"
            )
            artifact_validation_readback_identity = hashlib.sha256(
                (
                    artifact_scope_receipt_raw + provider_snapshot_raw
                ).encode("utf-8")
            ).hexdigest()
            formal_scope_authority_lookup = {
                "kind": completion_formal_scope_lookup[
                    "lookup_binding_kind_exact"
                ],
                "store_id": completion_formal_scope_lookup["store_id_exact"],
                "store_revision": next_completion_revision,
                "store_entry_index": next_completion_revision - 1,
                "entry_sha256": hashlib.sha256(
                    f"transition-formal:{next_completion_revision}".encode(
                        "utf-8"
                    )
                ).hexdigest(),
                "readback_identity_sha256": hashlib.sha256(
                    f"transition-formal:{next_completion_revision}".encode(
                        "utf-8"
                    )
                ).hexdigest(),
                "admission_id": (
                    f"transition-admission-{next_completion_revision}"
                ),
                "admission_identity_sha256": hashlib.sha256(
                    f"transition-admission-{next_completion_revision}".encode(
                        "utf-8"
                    )
                ).hexdigest(),
                "admission_allocation_sha256": hashlib.sha256(
                    b"transition-formal-allocation"
                ).hexdigest(),
                "admission_sha256": hashlib.sha256(
                    b"transition-formal-admission"
                ).hexdigest(),
                "authority_context_sha256": hashlib.sha256(
                    b"transition-formal-context"
                ).hexdigest(),
            }
            membership = {
                "receipt_id": f"completion-{next_completion_revision}",
                "receipt_store_revision": next_completion_revision,
                "receipt_store_entry_index": next_completion_revision - 1,
                "completion_revision": next_completion_revision,
                "artifact_validation_id": artifact_validation_id,
                "artifact_validation_registry_revision": (
                    next_completion_revision
                ),
                "artifact_validation_registry_entry_index": (
                    next_completion_revision - 1
                ),
                "artifact_validation_readback_identity_sha256": (
                    artifact_validation_readback_identity
                ),
                "evidence_authority_validation_receipt_raw_utf8": (
                    evidence_validation_raw
                ),
                "evidence_authority_validation_receipt_sha256": (
                    evidence_validation_sha256
                ),
                "provider_artifact_identity": artifact_identity,
                "provider_outcome": provider_outcome,
                "semantic_server_time": semantic_server_time,
                "semantic_server_time_field": "created_at",
                "provider_artifact_scope_receipt_raw_utf8": (
                    artifact_scope_receipt_raw
                ),
                "provider_artifact_scope_receipt_sha256": (
                    artifact_scope_receipt_sha256
                ),
                "complete_provider_snapshot_raw_utf8": provider_snapshot_raw,
                "complete_provider_snapshot_sha256": (
                    provider_snapshot_sha256
                ),
                "formal_scope_authority_lookup": (
                    formal_scope_authority_lookup
                ),
                "recorded_epoch_revision": after_revision,
            }
            after = json.loads(json.dumps(before))
            after["revision"] = after_revision
            after["provider_artifact_completion"] = {
                "kind": provider_completion["kind_exact"],
                "review_epoch": dict(fixture_review_epoch),
                "state": "completed",
                "completion_revision": next_completion_revision,
                "receipt_memberships": [
                    *before_completion["receipt_memberships"],
                    membership,
                ],
                "latest_provider_outcome": provider_outcome,
                "last_mutated_epoch_revision": after_revision,
            }
            receipt = {
                "kind": completion_receipt["kind_exact"],
                "review_epoch": dict(fixture_review_epoch),
                "epoch_membership": membership,
                "source_state": completion_source_state(
                    before,
                    control_class,
                    controlled_attempt,
                ),
                "artifact_validation_id": artifact_validation_id,
                "artifact_validation_registry_revision": (
                    next_completion_revision
                ),
                "artifact_validation_registry_entry_index": (
                    next_completion_revision - 1
                ),
                "artifact_validation_readback_identity_sha256": (
                    artifact_validation_readback_identity
                ),
                "evidence_authority_validation_receipt_raw_utf8": (
                    evidence_validation_raw
                ),
                "evidence_authority_validation_receipt_sha256": (
                    evidence_validation_sha256
                ),
                "provider_artifact_identity": artifact_identity,
                "provider_outcome": provider_outcome,
                "semantic_server_time": semantic_server_time,
                "semantic_server_time_field": "created_at",
                "provider_artifact_scope_receipt_raw_utf8": (
                    artifact_scope_receipt_raw
                ),
                "provider_artifact_scope_receipt_sha256": (
                    artifact_scope_receipt_sha256
                ),
                "complete_provider_snapshot_raw_utf8": provider_snapshot_raw,
                "complete_provider_snapshot_sha256": (
                    provider_snapshot_sha256
                ),
                "formal_scope_authority_lookup": (
                    formal_scope_authority_lookup
                ),
                "epoch_revision_before": before["revision"],
                "epoch_revision_after": after_revision,
                "epoch_ledger_sha256_before": completion_snapshot_digest(before),
                "epoch_ledger_sha256_after": completion_snapshot_digest(after),
                "completion_state_before": before_completion["state"],
                "completion_state_after": "completed",
                "completion_revision_before": before_completion[
                    "completion_revision"
                ],
                "completion_revision_after": next_completion_revision,
            }
            storage_key = (
                membership["receipt_id"],
                membership["receipt_store_revision"],
                membership["receipt_store_entry_index"],
            )
            return after, receipt, storage_key

        def completion_transition_is_valid(
            receipt: object,
            *,
            before: object,
            after: object,
            parent_receipt_store: object,
        ) -> bool:
            if (
                not isinstance(receipt, dict)
                or not isinstance(before, dict)
                or not isinstance(after, dict)
                or not isinstance(parent_receipt_store, dict)
                or set(receipt) != set(completion_receipt["closed_required_fields"])
                or set(before) != set(transaction["closed_epoch_fields"])
                or set(after) != set(transaction["closed_epoch_fields"])
                or receipt.get("kind") != completion_receipt["kind_exact"]
                or receipt.get("review_epoch") != fixture_review_epoch
                or receipt.get("epoch_revision_before") != before.get("revision")
                or receipt.get("epoch_revision_after") != after.get("revision")
                or after.get("revision") != before.get("revision") + 1
                or receipt.get("epoch_ledger_sha256_before")
                != completion_snapshot_digest(before)
                or receipt.get("epoch_ledger_sha256_after")
                != completion_snapshot_digest(after)
            ):
                return False
            membership = receipt.get("epoch_membership")
            before_completion = before.get("provider_artifact_completion")
            after_completion = after.get("provider_artifact_completion")
            source_state = receipt.get("source_state")
            if (
                not isinstance(membership, dict)
                or set(membership)
                != set(provider_completion["membership_contract"]["closed_required_fields"])
                or not isinstance(before_completion, dict)
                or not isinstance(after_completion, dict)
                or not isinstance(source_state, dict)
                or set(source_state)
                != set(
                    completion_receipt["source_state_contract"][
                        "closed_required_fields"
                    ]
                )
                or source_state
                != completion_source_state(
                    before,
                    source_state.get("control_class"),
                    source_state.get("controlled_attempt"),
                )
                or source_state.get("control_class")
                not in completion_receipt["source_state_contract"][
                    "control_class_union"
                ]
                or receipt.get("completion_state_before")
                != before_completion.get("state")
                or receipt.get("completion_state_after") != "completed"
                or before_completion.get("state") not in {"pending", "completed"}
                or after_completion.get("state") != "completed"
                or receipt.get("completion_revision_before")
                != before_completion.get("completion_revision")
                or receipt.get("completion_revision_after")
                != before_completion.get("completion_revision") + 1
                or after_completion.get("completion_revision")
                != receipt.get("completion_revision_after")
                or after_completion.get("receipt_memberships")
                != [*before_completion.get("receipt_memberships", []), membership]
                or membership.get("artifact_validation_id")
                != receipt.get("artifact_validation_id")
                or membership.get("artifact_validation_registry_revision")
                != receipt.get("artifact_validation_registry_revision")
                or membership.get(
                    "artifact_validation_registry_entry_index"
                )
                != receipt.get("artifact_validation_registry_entry_index")
                or membership.get(
                    "artifact_validation_readback_identity_sha256"
                )
                != receipt.get(
                    "artifact_validation_readback_identity_sha256"
                )
                or membership.get(
                    "evidence_authority_validation_receipt_raw_utf8"
                )
                != receipt.get(
                    "evidence_authority_validation_receipt_raw_utf8"
                )
                or membership.get(
                    "evidence_authority_validation_receipt_sha256"
                )
                != receipt.get(
                    "evidence_authority_validation_receipt_sha256"
                )
                or membership.get("provider_artifact_identity")
                != receipt.get("provider_artifact_identity")
                or membership.get("provider_outcome")
                != receipt.get("provider_outcome")
                or membership.get("semantic_server_time")
                != receipt.get("semantic_server_time")
                or membership.get("semantic_server_time_field")
                != receipt.get("semantic_server_time_field")
                or membership.get(
                    "provider_artifact_scope_receipt_raw_utf8"
                )
                != receipt.get("provider_artifact_scope_receipt_raw_utf8")
                or membership.get("provider_artifact_scope_receipt_sha256")
                != receipt.get("provider_artifact_scope_receipt_sha256")
                or membership.get("complete_provider_snapshot_raw_utf8")
                != receipt.get("complete_provider_snapshot_raw_utf8")
                or membership.get("complete_provider_snapshot_sha256")
                != receipt.get("complete_provider_snapshot_sha256")
                or membership.get("formal_scope_authority_lookup")
                != receipt.get("formal_scope_authority_lookup")
                or not isinstance(
                    receipt.get("formal_scope_authority_lookup"), dict
                )
                or set(receipt["formal_scope_authority_lookup"])
                != set(
                    completion_formal_scope_lookup[
                        "lookup_binding_closed_required_fields"
                    ]
                )
                or hashlib.sha256(
                    receipt.get(
                        "provider_artifact_scope_receipt_raw_utf8", ""
                    ).encode("utf-8")
                ).hexdigest()
                != receipt.get("provider_artifact_scope_receipt_sha256")
                or hashlib.sha256(
                    receipt.get(
                        "complete_provider_snapshot_raw_utf8", ""
                    ).encode("utf-8")
                ).hexdigest()
                != receipt.get("complete_provider_snapshot_sha256")
                or hashlib.sha256(
                    receipt.get(
                        "evidence_authority_validation_receipt_raw_utf8",
                        "",
                    ).encode("utf-8")
                ).hexdigest()
                != receipt.get(
                    "evidence_authority_validation_receipt_sha256"
                )
            ):
                return False
            immutable_fields = set(transaction["closed_epoch_fields"]) - {
                "revision",
                "provider_artifact_completion",
            }
            if any(before[field] != after[field] for field in immutable_fields):
                return False
            storage_key = (
                membership.get("receipt_id"),
                membership.get("receipt_store_revision"),
                membership.get("receipt_store_entry_index"),
            )
            return parent_receipt_store.get(storage_key) == receipt

        manual_after, manual_receipt, manual_storage_key = (
            make_completion_transition(
                registered_epoch_ledger,
                control_class="manual",
                provider_outcome="clean",
            )
        )
        self.assertTrue(
            completion_transition_is_valid(
                manual_receipt,
                before=registered_epoch_ledger,
                after=manual_after,
                parent_receipt_store={manual_storage_key: manual_receipt},
            )
        )
        self.assertEqual(manual_after["attempts"], {})
        self.assertIsNone(manual_after["current_attempt"])

        open_completed_before = json.loads(json.dumps(manual_after))
        open_completed_before.update(
            {
                "revision": 40,
                "current_attempt": 1,
                "attempts": {"1": {"state": "posting_ambiguous"}},
                "transport_fences": {"1": {"status": "posting-ambiguous"}},
            }
        )
        automatic_after, automatic_receipt, automatic_storage_key = (
            make_completion_transition(
                open_completed_before,
                control_class="automatic",
                provider_outcome="findings",
            )
        )
        self.assertTrue(
            completion_transition_is_valid(
                automatic_receipt,
                before=open_completed_before,
                after=automatic_after,
                parent_receipt_store={
                    automatic_storage_key: automatic_receipt
                },
            )
        )
        self.assertEqual(
            automatic_after["transport_fences"],
            open_completed_before["transport_fences"],
        )
        self.assertEqual(
            automatic_receipt["completion_state_before"], "completed"
        )

        changed_fence_after = json.loads(json.dumps(automatic_after))
        changed_fence_after["transport_fences"]["1"]["status"] = (
            "resolved-persisted"
        )
        changed_fence_receipt = json.loads(json.dumps(automatic_receipt))
        changed_fence_receipt["epoch_ledger_sha256_after"] = (
            completion_snapshot_digest(changed_fence_after)
        )
        self.assertFalse(
            completion_transition_is_valid(
                changed_fence_receipt,
                before=open_completed_before,
                after=changed_fence_after,
                parent_receipt_store={
                    automatic_storage_key: changed_fence_receipt
                },
            )
        )
        self.assertFalse(
            completion_transition_is_valid(
                manual_receipt,
                before=registered_epoch_ledger,
                after=manual_after,
                parent_receipt_store={},
            )
        )

        def post_max_authenticated_date_receipt(
            *,
            receipt_id: str,
            source_kind: str,
            http_date: str,
            recorded_epoch_revision: int,
        ) -> dict[str, object]:
            raw_body = completion_json(
                {
                    "source_kind": source_kind,
                    "http_date": http_date,
                }
            )
            return {
                "kind": max_wait_custody[
                    "authenticated_date_receipt_contract"
                ]["kind_exact"],
                "receipt_id": receipt_id,
                "review_epoch": dict(fixture_review_epoch),
                "source_kind": source_kind,
                "request_method": "GET",
                "canonical_request_url": (
                    "https://api.github.com/repos/OWNER/REPO/pulls/1"
                    if source_kind != "pre-request-compare"
                    else (
                        "https://api.github.com/repos/OWNER/REPO/compare/"
                        f"{'a' * 40}...{'b' * 40}"
                    )
                ),
                "http_status": 200,
                "authenticated_operating_identity": "hoteng",
                "http_date": http_date,
                "raw_response_body_utf8": raw_body,
                "raw_response_body_sha256": hashlib.sha256(
                    raw_body.encode("utf-8")
                ).hexdigest(),
                "recorded_epoch_revision": recorded_epoch_revision,
            }

        post_max_first_date = "2027-01-15T08:00:00Z"
        post_max_deadline = "2027-01-15T10:00:00Z"
        post_max_artifact_time = "2027-01-15T10:00:01Z"
