        def acknowledgement_receipt_with_source(
            source_binding: dict[str, object],
        ) -> tuple[dict[str, object], str]:
            candidate = json.loads(json.dumps(valid_acknowledgement_receipt))
            source_raw = source_binding["raw_source_record_utf8"]
            assert isinstance(source_raw, str)
            source_sha256 = hashlib.sha256(source_raw.encode("utf-8")).hexdigest()
            source_binding["raw_source_record_sha256"] = source_sha256
            candidate["source_record_binding"] = source_binding
            candidate["acknowledgement_native_id"] = source_binding[
                "source_native_id"
            ]
            candidate["acknowledgement_semantic_time"] = source_binding[
                "semantic_time"
            ]
            candidate["acknowledgement_evidence_sha256"] = source_sha256
            candidate["epoch_membership"][
                "acknowledgement_native_id"
            ] = source_binding["source_native_id"]
            candidate["epoch_membership"][
                "acknowledgement_evidence_sha256"
            ] = source_sha256
            candidate["reconciliation_snapshot_binding"][
                "source_record_sha256"
            ] = source_sha256
            parent_snapshot = {
                "revision": 7,
                "records": [source_binding],
                "complete_pagination": True,
            }
            parent_snapshot_raw = json.dumps(
                parent_snapshot,
                ensure_ascii=False,
                separators=(",", ":"),
                sort_keys=True,
            )
            candidate["reconciliation_snapshot_binding"][
                "snapshot_sha256"
            ] = hashlib.sha256(parent_snapshot_raw.encode("utf-8")).hexdigest()
            candidate["epoch_membership"][
                "reconciliation_snapshot_sha256"
            ] = candidate["reconciliation_snapshot_binding"][
                "snapshot_sha256"
            ]
            return candidate, parent_snapshot_raw

        def arrange_acknowledgement_authority(
            receipt: dict[str, object],
            parent_snapshot_raw: str,
        ) -> str:
            context = build_acknowledgement_validation_context(
                receipt,
                parent_snapshot_raw,
            )
            return register_acknowledgement_validation_context(context)

        def late_acknowledgement_receipt_at(
            semantic_time: str,
            deadline_relation: str,
        ) -> tuple[dict[str, object], str]:
            source_record = json.loads(acknowledgement_source_raw)
            source_record["created_at"] = semantic_time
            source_binding = json.loads(
                json.dumps(acknowledgement_source_binding)
            )
            source_binding["semantic_time"] = semantic_time
            source_binding["raw_source_record_utf8"] = json.dumps(
                source_record,
                ensure_ascii=False,
                separators=(",", ":"),
                sort_keys=True,
            )
            candidate, parent_snapshot_raw = (
                acknowledgement_receipt_with_source(source_binding)
            )
            candidate["acknowledgement_semantic_time"] = semantic_time
            candidate["ack_deadline_relation"] = deadline_relation
            candidate["consumption_kind"] = (
                "late-ack-reopen-closed-missed-ack"
            )
            candidate["epoch_membership"][
                "ack_deadline_relation"
            ] = deadline_relation
            candidate["epoch_membership"]["consumption_kind"] = (
                "late-ack-reopen-closed-missed-ack"
            )
            candidate["attempt_state_before"] = "missed_ack"
            candidate["attempt_state_after"] = "waiting_result"
            candidate["current_attempt_before"] = None
            candidate["current_attempt_after"] = 1
            return candidate, parent_snapshot_raw

