        def claim_allowed(
            server_remaining_seconds: float,
            observed_round_trip_seconds: float,
            continuous_elapsed_before_claim_seconds: float,
            *,
            clock_continuity_proved: bool = True,
        ) -> bool:
            if not clock_continuity_proved:
                return False
            conservative_remaining = (
                server_remaining_seconds
                - observed_round_trip_seconds
                - dispatch_guard["whole-second-Date-uncertainty-seconds"]
                - dispatch_guard["additional-safety-margin-seconds"]
            )
            budget = min(
                dispatch_guard["maximum-receipt-to-claim-seconds"],
                conservative_remaining,
            )
            return budget > 0 and continuous_elapsed_before_claim_seconds < budget

