        def resealed_membership_snapshot_corruption(
            mutate_memberships: Callable[[list[object]], None],
        ) -> dict[str, object]:
            context = copy.deepcopy(original_valid_server_context)
            pointer_identity = context[
                "durable_membership_current_pointer_identity"
            ]
            pointer = json.loads(
                context["membership_current_pointers"][pointer_identity]
            )
            count = pointer["current_membership_count"]
            snapshot_identity = pointer[
                "current_snapshot_readback_identity_sha256"
            ]
            snapshot = json.loads(
                context["membership_snapshots"][snapshot_identity]
            )
            memberships = json.loads(snapshot["memberships_raw_utf8"])
            assert isinstance(memberships, list)
            mutate_memberships(memberships)
            memberships_raw = serialize_transport_outcome_evidence(
                memberships
            )
            memberships_sha256 = hashlib.sha256(
                memberships_raw.encode("utf-8")
            ).hexdigest()
            transaction_identity = snapshot[
                "membership_append_transaction_sha256"
            ]
            transaction = json.loads(
                context["membership_append_transactions"][
                    transaction_identity
                ]
            )
            transaction["after_memberships_sha256"] = memberships_sha256
            if memberships:
                transaction["appended_membership_sha256"] = hashlib.sha256(
                    serialize_transport_outcome_evidence(
                        memberships[-1]
                    ).encode("utf-8")
                ).hexdigest()
            transaction_raw = serialize_transport_outcome_evidence(
                transaction
            )
            transaction_identity = hashlib.sha256(
                transaction_raw.encode("utf-8")
            ).hexdigest()
            context["membership_append_transactions"][
                transaction_identity
            ] = transaction_raw
            snapshot["memberships_raw_utf8"] = memberships_raw
            snapshot["memberships_sha256"] = memberships_sha256
            snapshot["membership_append_transaction_sha256"] = (
                transaction_identity
            )
            snapshot_raw = serialize_transport_outcome_evidence(snapshot)
            snapshot_identity = hashlib.sha256(
                snapshot_raw.encode("utf-8")
            ).hexdigest()
            context["membership_snapshots"][snapshot_identity] = snapshot_raw
            pointer["current_snapshot_readback_identity_sha256"] = (
                snapshot_identity
            )
            pointer_raw = serialize_transport_outcome_evidence(pointer)
            pointer_identity = hashlib.sha256(
                pointer_raw.encode("utf-8")
            ).hexdigest()
            context["membership_current_pointers"][
                pointer_identity
            ] = pointer_raw
            context[
                "committed_membership_snapshot_identity_by_count"
            ][count] = snapshot_identity
            context[
                "committed_membership_pointer_identity_by_count"
            ][count] = pointer_identity
            context["durable_membership_current_pointer_identity"] = (
                pointer_identity
            )
            context["durable_membership_current_pointer_candidates"] = [
                pointer_identity
            ]
            return context

