        def source_values_match(
            source_kind: str,
            control_class: str,
            scope_class: str,
            whole_pr: bool,
        ) -> bool:
            return expected_source_values.get(source_kind) == {
                "control_class": control_class,
                "scope_class": scope_class,
                "whole_pr": whole_pr,
            }

        for source_kind, exact_values in expected_source_values.items():
            self.assertTrue(source_values_match(source_kind, **exact_values))
            self.assertFalse(
                source_values_match(source_kind, "automatic", "formal-broad", True)
            )
            self.assertFalse(
                source_values_match(
                    source_kind,
                    exact_values["control_class"],
                    "focused-or-nonformal",
                    True,
                )
            )
            self.assertFalse(
                source_values_match(
                    source_kind,
                    exact_values["control_class"],
                    "formal-broad",
                    False,
                )
            )

        candidate_epoch = ("owner/repo", 87, "b" * 40, "c" * 40)
        artifact_time = datetime.datetime(
            2026, 8, 4, 13, 0, tzinfo=datetime.timezone.utc
        )

        def scope_eligible(
            record_epoch: tuple[str, int, str, str],
            record_time: datetime.datetime,
            trusted: bool,
        ) -> bool:
            return (
                trusted
                and record_epoch == candidate_epoch
                and record_time < artifact_time
            )

        for control_class in ("automatic", "controlled", "manual"):
            with self.subTest(control_class=control_class):
                self.assertTrue(
                    scope_eligible(
                        candidate_epoch,
                        artifact_time - datetime.timedelta(seconds=1),
                        True,
                    )
                )
                self.assertFalse(
                    scope_eligible(
                        ("owner/repo", 87, "d" * 40, "c" * 40),
                        artifact_time - datetime.timedelta(seconds=1),
                        True,
                    )
                )
                self.assertFalse(scope_eligible(candidate_epoch, artifact_time, True))
                self.assertFalse(
                    scope_eligible(
                        candidate_epoch,
                        artifact_time + datetime.timedelta(seconds=1),
                        True,
                    )
                )
                self.assertFalse(
                    scope_eligible(
                        candidate_epoch,
                        artifact_time - datetime.timedelta(seconds=1),
                        False,
                    )
                )
