        def parse_recent_pull_discovery(
            fetch: object,
            *,
            expected_url: str,
            resource_tracker: dict[str, object],
        ) -> (
            tuple[
                dict[int, tuple[str, str, int, str]],
                list[dict[str, object]],
                str,
            ]
            | None
        ):
            if (
                not isinstance(fetch, dict)
                or set(fetch) != {"kind", "transport", "parent_comment_id", "pages"}
                or fetch.get("kind") != "recent_pull_requests"
                or fetch.get("transport") != "rest"
                or fetch.get("parent_comment_id") is not None
                or not isinstance(fetch.get("pages"), list)
                or not fetch["pages"]
            ):
                return None
            pages = fetch["pages"]
            recent_pulls: dict[int, tuple[str, str, int, str]] = {}
            projection: list[dict[str, object]] = []
            seen_all_pull_numbers: set[int] = set()
            previous_updated_at: int | None = None
            boundary_seen = False
            expected_page_url = expected_url
            declared_last_page: int | None = None
            for page_index, page in enumerate(pages):
                page_admitted = retained_representation_admission_state(
                    resource_tracker,
                    kind="raw-page",
                    value=page,
                )
                if (
                    boundary_seen
                    or page_admitted is None
                    or (
                        page_admitted is False
                        and not resource_budget_charge(
                            resource_tracker,
                            fetch_attempts=1,
                        )
                    )
                    or not isinstance(page, dict)
                    or set(page)
                    != {
                        "request_url",
                        "status",
                        "link_header",
                        "request_after",
                        "body_utf8",
                        "body_sha256",
                    }
                    or page.get("request_url") != expected_page_url
                    or _github_rest_page_number(
                        expected_page_url,
                        expected_url=expected_url,
                    )
                    != page_index + 1
                    or type(page.get("status")) is not int
                    or page.get("status") != 200
                    or page.get("request_after") is not None
                    or not isinstance(page.get("body_utf8"), str)
                ):
                    return None
                if page_admitted is False and not resource_budget_charge(
                    resource_tracker,
                    retained_pages=1,
                ):
                    return None
                retained_page_admission = consume_retained_page_utf8_admission(
                    page,
                    resource_tracker,
                )
                if (
                    retained_page_admission is None
                    or page.get("body_sha256")
                    != retained_page_admission[2]
                ):
                    return None
                try:
                    records = strict_json_loads(page["body_utf8"])
                except (TypeError, ValueError):
                    return None
                if (
                    not isinstance(records, list)
                    or len(records) > 100
                    or (
                        page_admitted is False
                        and not resource_budget_charge(
                            resource_tracker,
                            records=len(records),
                        )
                    )
                ):
                    return None
                page_boundary_seen = False
                for raw_pull in records:
                    if not isinstance(raw_pull, dict):
                        return None
                    pull_number = raw_pull.get("number")
                    base = raw_pull.get("base")
                    head = raw_pull.get("head")
                    base_oid = base.get("sha") if isinstance(base, dict) else None
                    head_oid = head.get("sha") if isinstance(head, dict) else None
                    state = raw_pull.get("state")
                    updated_at = _parse_github_rfc3339_seconds(
                        raw_pull.get("updated_at")
                    )
                    if (
                        type(pull_number) is not int
                        or pull_number <= 0
                        or pull_number in seen_all_pull_numbers
                        or raw_pull.get("url")
                        != (
                            "https://api.github.com/repos/"
                            f"{current_repository}/pulls/{pull_number}"
                        )
                        or not isinstance(base_oid, str)
                        or re.fullmatch(r"[0-9a-f]{40}", base_oid) is None
                        or not isinstance(head_oid, str)
                        or re.fullmatch(r"[0-9a-f]{40}", head_oid) is None
                        or type(state) is not str
                        or state not in {"open", "closed"}
                        or updated_at is None
                        or (
                            previous_updated_at is not None
                            and updated_at > previous_updated_at
                        )
                    ):
                        return None
                    seen_all_pull_numbers.add(pull_number)
                    previous_updated_at = updated_at
                    if updated_at <= history_start_exclusive:
                        page_boundary_seen = True
                        boundary_seen = True
                        continue
                    if page_boundary_seen:
                        return None
                    recent_pulls[pull_number] = (
                        base_oid,
                        head_oid,
                        updated_at,
                        state,
                    )
                    projection.append(
                        {
                            "pull_number": pull_number,
                            "base_oid": base_oid,
                            "head_oid": head_oid,
                        }
                    )
                relation_targets: dict[str, str] = {}
                link_valid, next_url = _github_link_header_next_target(
                    page.get("link_header"),
                    current_url=expected_page_url,
                    relation_targets_out=relation_targets,
                )
                if not link_valid:
                    return None
                current_page = _github_rest_page_number(
                    expected_page_url,
                    expected_url=expected_url,
                )
                if current_page is None:
                    return None
                current_last_target = relation_targets.get("last")
                if current_last_target is not None:
                    current_last_page = _github_rest_page_number(
                        current_last_target,
                        expected_url=expected_url,
                    )
                    if (
                        current_last_page is None
                        or (
                            declared_last_page is not None
                            and current_last_page != declared_last_page
                        )
                    ):
                        return None
                    declared_last_page = current_last_page
                next_page = (
                    _github_rest_page_number(
                        next_url,
                        expected_url=expected_url,
                    )
                    if next_url is not None
                    else None
                )
                if (
                    declared_last_page is not None
                    and (
                        current_page > declared_last_page
                        or (
                            next_page is not None
                            and next_page > declared_last_page
                        )
                    )
                ):
                    return None
                if page_index + 1 < len(pages):
                    if page_boundary_seen or next_url is None:
                        return None
                    expected_page_url = next_url
                else:
                    if next_url is not None and not page_boundary_seen:
                        return None
                    if (
                        not page_boundary_seen
                        and declared_last_page is not None
                        and current_page != declared_last_page
                    ):
                        return None
            stop_reason = (
                "window-boundary-complete"
                if next_url is not None
                else "natural-end-complete"
            )
            projection.sort(key=lambda item: int(item["pull_number"]))
            return recent_pulls, projection, stop_reason

        def raw_actor(value: object) -> str:
            if not isinstance(value, dict):
                return "ambiguous"
            login = value.get("login")
            user_type = value.get("type")
            if login == exact_login and user_type == "Bot":
                return "exact"
            if (
                isinstance(login, str)
                and login
                and login != exact_login
                and user_type == "User"
            ):
                return "different"
            if (
                isinstance(login, str)
                and login
                and login != exact_login
                and user_type == "Bot"
                and "codex" not in login.casefold()
            ):
                return "different"
            return "ambiguous"

        def raw_issue_actor(value: object) -> str:
            if not isinstance(value, dict):
                return "ambiguous"
            actor = raw_actor(value.get("user"))
            app_slug = value.get("app_slug")
            exact_app = "chatgpt-codex-connector"
            if actor == "exact" and app_slug == exact_app:
                return "exact"
            if actor == "exact" or app_slug == exact_app:
                return "ambiguous"
            if isinstance(app_slug, str) and "codex" in app_slug.casefold():
                return "ambiguous"
            return actor

        def parse_recent_request_discovery(
            fetch: object,
            *,
            expected_url: str,
            resource_tracker: dict[str, object],
        ) -> (
            tuple[
                dict[int, tuple[int, dict[str, object]]],
                list[dict[str, object]],
            ]
            | None
        ):
            raw_records = parse_rest_pages(
                fetch,
                expected_kind="recent_request_comments",
                expected_url=expected_url,
                resource_tracker=resource_tracker,
            )
            if not isinstance(raw_records, list):
                return None
            by_id: dict[int, tuple[int, dict[str, object]]] = {}
            projection: list[dict[str, object]] = []
            seen_controlled_comment_ids: set[int] = set()
            previous_updated_at: int | None = None
            for raw_record in raw_records:
                projected = project_raw_issue_record(raw_record)
                if projected is None or not isinstance(raw_record, dict):
                    return None
                updated_at = projected["updated_at"]
                if (
                    type(updated_at) is not int
                    or updated_at <= history_start_exclusive
                    or (
                        previous_updated_at is not None
                        and updated_at > previous_updated_at
                    )
                ):
                    return None
                previous_updated_at = updated_at
                request_user = projected.get("user")
                request_login = (
                    request_user.get("login")
                    if isinstance(request_user, dict)
                    else None
                )
                request_type = (
                    request_user.get("type")
                    if isinstance(request_user, dict)
                    else None
                )
                request_classification = (
                    _classify_github_codex_formal_request(
                        projected.get("body"),
                        request_login,
                        request_type,
                        expected_head=None,
                        request_contract=formal_request_contract,
                        allow_untrusted_controlled_shape=True,
                    )
                )
                broad_request_shape = request_classification in {
                    "formal-broad-manual",
                    "formal-broad-controlled",
                    "formal-broad-controlled-untrusted",
                }
                if not broad_request_shape:
                    created_at = projected.get("created_at")
                    if (
                        updated_at > history_as_of_server_time
                        and type(created_at) is int
                        and created_at > history_as_of_server_time
                        and raw_issue_actor(projected) == "different"
                    ):
                        continue
                    if updated_at > history_as_of_server_time:
                        return None
                    continue
                request_id = projected.get("id")
                issue_url = raw_record.get("issue_url")
                match = (
                    re.fullmatch(
                        (
                            r"https://api\.github\.com/repos/"
                            + re.escape(current_repository)
                            + r"/issues/([1-9][0-9]*)"
                        ),
                        issue_url,
                    )
                    if isinstance(issue_url, str)
                    else None
                )
                issue_number_digits = (
                    _canonical_positive_decimal(match.group(1))
                    if match is not None
                    else None
                )
                issue_number = (
                    int(issue_number_digits)
                    if isinstance(issue_number_digits, str)
                    else None
                )
                if (
                    type(request_id) is not int
                    or request_id <= 0
                    or request_id.bit_length() > _MAX_CANONICAL_DECIMAL_BITS
                    or request_id in seen_controlled_comment_ids
                    or type(issue_number) is not int
                    or issue_number.bit_length() > _MAX_CANONICAL_DECIMAL_BITS
                    or projected.get("url")
                    != (
                        "https://api.github.com/repos/"
                        f"{current_repository}/issues/comments/{request_id}"
                    )
                ):
                    return None
                seen_controlled_comment_ids.add(request_id)
                pull_html_url = (
                    f"https://github.com/{current_repository}/pull/"
                    f"{issue_number}#issuecomment-{request_id}"
                )
                issue_html_url = (
                    f"https://github.com/{current_repository}/issues/"
                    f"{issue_number}#issuecomment-{request_id}"
                )
                if projected.get("html_url") == issue_html_url:
                    # The repository feed also returns ordinary issue comments.
                    # Retain and charge their raw page, but never seed PR scope.
                    continue
                if (
                    projected.get("html_url") != pull_html_url
                    or updated_at > history_as_of_server_time
                ):
                    return None
                pull_number = issue_number
                raw_digest = hashlib.sha256(
                    canonical_raw_body(raw_record).encode("utf-8")
                ).hexdigest()
                by_id[request_id] = (pull_number, clone(raw_record))
                projection.append(
                    {
                        "request_id": request_id,
                        "pull_number": pull_number,
                        "updated_at": updated_at,
                        "source_record_sha256": raw_digest,
                    }
                )
            return by_id, projection

        def produce_raw_semantic_dataset(
            value: object,
            *,
            provider_declaration: object = None,
            current_ancestry: dict[str, int] | None = None,
            current_legacy_short_commit_resolutions: dict[str, str] | None = None,
            require_current_ancestry_exact: bool = True,
            _tightened_resource_limits: dict[str, int] | None = None,
            _monotonic_clock: object = time.monotonic,
            _single_scope_pull_number: int | None = None,
            _allow_post_as_of_requests: bool = False,
            _allow_post_as_of_artifacts: bool = False,
            _inventory_validation_context: dict[str, object] | None = None,
            _trusted_controlled_bindings: object = None,
        ) -> dict[str, object] | None:
            if (
                not isinstance(value, dict)
                or len(value) != 4
                or set(value)
                != {"schema_version", "repository", "scope_discovery", "scopes"}
                or type(value.get("schema_version")) is not int
                or value.get("schema_version") != 4
                or value.get("repository") != current_repository
                or not isinstance(value.get("scopes"), list)
                or type(_allow_post_as_of_requests) is not bool
                or type(_allow_post_as_of_artifacts) is not bool
                or (
                    _trusted_controlled_bindings is not None
                    and not isinstance(_trusted_controlled_bindings, dict)
                )
                or (
                    _single_scope_pull_number is not None
                    and (
                        type(_single_scope_pull_number) is not int
                        or _single_scope_pull_number <= 0
                    )
                )
            ):
                return None
            inventory_context = _inventory_validation_context
            if inventory_context is None:
                return None
            inventory_parts = inventory_validation_context_parts(inventory_context)
            effective_limits = effective_resource_limits(_tightened_resource_limits)
            if (
                inventory_parts is None
                or effective_limits is None
                or not typed_json_equal(
                    inventory_parts[1].get("limits"),
                    effective_limits,
                )
                or len(value["scopes"]) > effective_limits["max_seeded_pull_requests"]
            ):
                return None
            resource_tracker = inventory_parts[1]
            transcript_admitted = retained_representation_admission_state(
                resource_tracker,
                kind="discovery-transcript",
                value=value,
            )
            if transcript_admitted is None or (
                transcript_admitted is False
                and not resource_budget_charge(
                    resource_tracker,
                    seeded_pull_requests=len(value["scopes"]),
                )
            ):
                return None
            expected_declaration_raw: dict[str, object] | None = None
            if provider_declaration is not None:
                if not declaration_is_authoritative(
                    provider_declaration
                ) or not isinstance(provider_declaration, dict):
                    return None
                final_fetch = provider_declaration.get("final_fetch_receipt")
                if not isinstance(final_fetch, dict) or not isinstance(
                    final_fetch.get("body_utf8"), str
                ):
                    return None
                try:
                    fetched_declaration = strict_json_loads(final_fetch["body_utf8"])
                except (TypeError, ValueError):
                    return None
                if not isinstance(fetched_declaration, dict):
                    return None
                expected_declaration_raw = fetched_declaration
            api_root = f"https://api.github.com/repos/{current_repository}"
            recent_pull_requests_url = (
                f"{api_root}/pulls?state=all&sort=updated&direction=desc&per_page=100"
            )
            recent_request_comments_url = (
                f"{api_root}/issues/comments?sort=updated&direction=desc&since="
                f"{_format_github_rfc3339_seconds(history_start_exclusive)}"
                "&per_page=100"
            )
            scope_discovery = value.get("scope_discovery")
            discovered_pulls: dict[int, tuple[str, str, int, str] | None] = {}
            recent_request_by_id: dict[int, tuple[int, dict[str, object]]] = {}
            scope_discovery_projection: dict[str, object] | None = None
            future_prefix_pull_numbers: set[int] = set()
            request_seed_pull_numbers: set[int] = set()
            anchor_pull_numbers: set[int] = set()
            if _single_scope_pull_number is None:
                if (
                    not isinstance(scope_discovery, dict)
                    or set(scope_discovery)
                    != {"recent_pull_requests", "recent_request_comments", "anchors"}
                    or not isinstance(scope_discovery.get("anchors"), dict)
                    or set(scope_discovery["anchors"])
                    != {"current_pull_number", "declaration_pull_number"}
                ):
                    return None
                recent_pull_result = parse_recent_pull_discovery(
                    scope_discovery.get("recent_pull_requests"),
                    expected_url=recent_pull_requests_url,
                    resource_tracker=resource_tracker,
                )
                recent_request_result = parse_recent_request_discovery(
                    scope_discovery.get("recent_request_comments"),
                    expected_url=recent_request_comments_url,
                    resource_tracker=resource_tracker,
                )
                if recent_pull_result is None or recent_request_result is None:
                    return None
                recent_pulls, recent_pull_projection, stop_reason = recent_pull_result
                recent_request_by_id, recent_request_projection = recent_request_result
                future_prefix_pull_numbers = {
                    pull_number
                    for pull_number, (_, _, updated_at, _) in recent_pulls.items()
                    if updated_at > history_as_of_server_time
                }
                request_seed_pull_numbers = {
                    pull_number for pull_number, _ in recent_request_by_id.values()
                }
                anchors = scope_discovery["anchors"]
                anchor_values: list[int] = []
                for anchor_name in (
                    "current_pull_number",
                    "declaration_pull_number",
                ):
                    anchor = anchors.get(anchor_name)
                    if anchor is not None and (type(anchor) is not int or anchor <= 0):
                        return None
                    if type(anchor) is int:
                        anchor_values.append(anchor)
                anchor_pull_numbers = set(anchor_values)
                if anchors.get("current_pull_number") != current_pr:
                    return None
                if (
                    expected_declaration_raw is not None
                    and anchors.get("declaration_pull_number") != declaration_pr
                ):
                    return None
                union_pull_numbers = sorted(
                    set(recent_pulls) | request_seed_pull_numbers | set(anchor_values)
                )
                if len(union_pull_numbers) > effective_limits[
                    "max_seeded_pull_requests"
                ] or len(value["scopes"]) != len(union_pull_numbers):
                    return None
                discovered_pulls = {
                    pull_number: recent_pulls.get(pull_number)
                    for pull_number in union_pull_numbers
                }
                scope_discovery_projection = {
                    "cutoff_rfc3339": _format_github_rfc3339_seconds(
                        history_start_exclusive
                    ),
                    "stop_reason": stop_reason,
                    "recent_pull_requests": recent_pull_projection,
                    "recent_request_comments": recent_request_projection,
                    "anchors": clone(anchors),
                    "union_pull_numbers": union_pull_numbers,
                    "retained_pull_scope_audit": [],
                    "future_prefix_omission_eligibility_audit": [],
                }
            else:
                if (
                    scope_discovery is not None
                    or len(value["scopes"]) != 1
                    or not isinstance(value["scopes"][0], dict)
                    or value["scopes"][0].get("pull_number")
                    != _single_scope_pull_number
                ):
                    return None
                discovered_pulls[_single_scope_pull_number] = None

            raw_semantic_scopes: list[dict[str, object]] = []
            retained_pull_scope_audit: list[dict[str, object]] = []
            future_prefix_omission_eligibility_audit: list[dict[str, object]] = []
            seen_scopes: set[tuple[object, ...]] = set()
            seen_detail_pulls: set[int] = set()
            observed_current_ancestry_heads: set[str] = set()
            observed_current_legacy_short_commit_prefixes: set[str] = set()
            declaration_match_count = 0
            ancestry = current_ancestry if current_ancestry is not None else {}
            if not isinstance(ancestry, dict) or any(
                not isinstance(candidate, str)
                or re.fullmatch(r"[0-9a-f]{40}", candidate) is None
                or type(returncode) is not int
                or returncode not in {0, 1}
                for candidate, returncode in ancestry.items()
            ):
                return None
            legacy_short_commit_resolutions = (
                current_legacy_short_commit_resolutions
                if current_legacy_short_commit_resolutions is not None
                else {}
            )
            if not isinstance(legacy_short_commit_resolutions, dict) or any(
                not isinstance(raw_prefix, str)
                or re.fullmatch(r"[0-9a-f]{10}", raw_prefix) is None
                or not isinstance(resolved_commit, str)
                or re.fullmatch(r"[0-9a-f]{40}", resolved_commit) is None
                or not resolved_commit.startswith(raw_prefix)
                or current_head.startswith(raw_prefix)
                or resolved_commit == current_head
                for raw_prefix, resolved_commit in (
                    legacy_short_commit_resolutions.items()
                )
            ):
                return None
            detail_kinds = set(required_universe_pagination) - {
                "recent_pull_requests",
                "recent_request_comments",
            }

            def rest_fetch_initial_url(fetch: object) -> str | None:
                pages = fetch.get("pages") if isinstance(fetch, dict) else None
                first_page = pages[0] if isinstance(pages, list) and pages else None
                request_url = (
                    first_page.get("request_url")
                    if isinstance(first_page, dict)
                    else None
                )
                return request_url if isinstance(request_url, str) else None

            for scope_transcript in value["scopes"]:
                if (
                    not isinstance(scope_transcript, dict)
                    or len(scope_transcript) != 2
                    or set(scope_transcript) != {"pull_number", "fetches"}
                    or type(scope_transcript.get("pull_number")) is not int
                    or scope_transcript.get("pull_number") <= 0
                    or not isinstance(scope_transcript.get("fetches"), list)
                ):
                    return None
                pr = scope_transcript["pull_number"]
                if pr not in discovered_pulls or pr in seen_detail_pulls:
                    return None
                seen_detail_pulls.add(pr)
                repository = current_repository
                fetches = scope_transcript["fetches"]
                if (
                    len(fetches)
                    > len(detail_kinds)
                    + effective_limits["max_controlled_requests"]
                    + effective_limits["max_records"]
                ):
                    return None
                by_kind: dict[str, list[dict[str, object]]] = {}
                for fetch in fetches:
                    if not isinstance(fetch, dict) or len(fetch) != 4:
                        return None
                    kind = fetch.get("kind")
                    if not isinstance(kind, str):
                        return None
                    by_kind.setdefault(kind, []).append(fetch)
                singleton_kinds = detail_kinds - {
                    "inline_comments",
                    "request_reactions",
                }
                if (
                    not singleton_kinds.issubset(by_kind)
                    or "inline_comments" not in by_kind
                    or set(by_kind) - set(detail_kinds)
                ):
                    return None
                if any(len(by_kind[kind]) != 1 for kind in singleton_kinds):
                    return None
                if any(
                    by_kind[kind][0].get("parent_comment_id") is not None
                    for kind in singleton_kinds
                ):
                    return None
                if any(
                    fetch.get("parent_comment_id") is not None
                    for fetch in by_kind["inline_comments"]
                ):
                    return None
                pull_fetch = by_kind["pull_requests"][0]
                pull_records = parse_rest_pages(
                    pull_fetch,
                    expected_kind="pull_requests",
                    expected_url=f"{api_root}/pulls/{pr}",
                    response_shape="direct-object",
                    resource_tracker=resource_tracker,
                )
                if (
                    not isinstance(pull_records, list)
                    or len(pull_records) != 1
                    or not isinstance(pull_records[0], dict)
                ):
                    return None
                pull_record = pull_records[0]
                base = pull_record.get("base")
                pull_head = pull_record.get("head")
                base_oid = base.get("sha") if isinstance(base, dict) else None
                head = pull_head.get("sha") if isinstance(pull_head, dict) else None
                raw_merged_at = pull_record.get("merged_at")
                merged_at = (
                    None
                    if raw_merged_at is None
                    else _parse_github_rfc3339_seconds(raw_merged_at)
                )
                normalized_lifecycle = {
                    "state": pull_record.get("state"),
                    "merged": pull_record.get("merged"),
                    "merged_at": merged_at,
                }
                discovered_scope = discovered_pulls[pr]
                if (
                    type(pull_record.get("number")) is not int
                    or pull_record.get("number") != pr
                    or not isinstance(base_oid, str)
                    or re.fullmatch(r"[0-9a-f]{40}", base_oid) is None
                    or (
                        discovered_scope is not None and base_oid != discovered_scope[0]
                    )
                    or not isinstance(head, str)
                    or re.fullmatch(r"[0-9a-f]{40}", head) is None
                    or (discovered_scope is not None and head != discovered_scope[1])
                    or (
                        discovered_scope is not None
                        and normalized_lifecycle["state"] != discovered_scope[3]
                    )
                    or "merged_at" not in pull_record
                    or (raw_merged_at is not None and merged_at is None)
                    or not lifecycle_is_typed(
                        {"lifecycle": normalized_lifecycle},
                        require_open=False,
                    )
                ):
                    return None
                compare_records = parse_rest_pages(
                    by_kind["compare"][0],
                    expected_kind="compare",
                    expected_url=f"{api_root}/compare/{base_oid}...{head}",
                    response_shape="direct-object",
                    resource_tracker=resource_tracker,
                )
                if (
                    not isinstance(compare_records, list)
                    or len(compare_records) != 1
                    or not isinstance(compare_records[0], dict)
                ):
                    return None
                compare_record = compare_records[0]
                base_commit = compare_record.get("base_commit")
                merge_base_commit = compare_record.get("merge_base_commit")
                merge_base = (
                    merge_base_commit.get("sha")
                    if isinstance(merge_base_commit, dict)
                    else None
                )
                if (
                    not isinstance(base_commit, dict)
                    or base_commit.get("sha") != base_oid
                    or not isinstance(merge_base, str)
                    or re.fullmatch(r"[0-9a-f]{40}", merge_base) is None
                ):
                    return None
                parsed_scope = (current_repository, pr, merge_base, head)
                if parsed_scope in seen_scopes:
                    return None
                seen_scopes.add(parsed_scope)

                issue_records = parse_rest_pages(
                    by_kind["issue_comments"][0],
                    expected_kind="issue_comments",
                    expected_url=(f"{api_root}/issues/{pr}/comments?per_page=100"),
                    resource_tracker=resource_tracker,
                )
                review_records = parse_rest_pages(
                    by_kind["reviews"][0],
                    expected_kind="reviews",
                    expected_url=f"{api_root}/pulls/{pr}/reviews?per_page=100",
                    resource_tracker=resource_tracker,
                )
                global_inline_url = f"{api_root}/pulls/{pr}/comments?per_page=100"
                global_inline_fetches = [
                    fetch
                    for fetch in by_kind["inline_comments"]
                    if rest_fetch_initial_url(fetch) == global_inline_url
                ]
                if len(global_inline_fetches) != 1:
                    return None
                inline_records = parse_rest_pages(
                    global_inline_fetches[0],
                    expected_kind="inline_comments",
                    expected_url=global_inline_url,
                    resource_tracker=resource_tracker,
                )
                thread_nodes = parse_graphql_thread_pages(
                    by_kind["review_threads"][0],
                    repository=current_repository,
                    pull_number=pr,
                    resource_tracker=resource_tracker,
                )
                if not all(
                    isinstance(records, list)
                    for records in (
                        issue_records,
                        review_records,
                        inline_records,
                        thread_nodes,
                    )
                ):
                    return None
                assert issue_records is not None
                assert review_records is not None
                assert inline_records is not None
                assert thread_nodes is not None
                review_ids_for_pagination: set[int] = set()
                for raw_review in review_records:
                    review_id = (
                        raw_review.get("id")
                        if isinstance(raw_review, dict)
                        else None
                    )
                    if (
                        type(review_id) is not int
                        or review_id <= 0
                        or review_id in review_ids_for_pagination
                    ):
                        return None
                    review_ids_for_pagination.add(review_id)
                associated_inline_fetches = [
                    fetch
                    for fetch in by_kind["inline_comments"]
                    if fetch is not global_inline_fetches[0]
                ]
                if len(associated_inline_fetches) != len(
                    review_ids_for_pagination
                ):
                    return None
                for review_id in review_ids_for_pagination:
                    expected_associated_url = (
                        f"{api_root}/pulls/{pr}/reviews/{review_id}/"
                        "comments?per_page=100"
                    )
                    matching_associated_fetches = [
                        fetch
                        for fetch in associated_inline_fetches
                        if rest_fetch_initial_url(fetch) == expected_associated_url
                    ]
                    if len(matching_associated_fetches) != 1:
                        return None
                    associated_records = parse_rest_pages(
                        matching_associated_fetches[0],
                        expected_kind="inline_comments",
                        expected_url=expected_associated_url,
                        resource_tracker=resource_tracker,
                    )
                    if not isinstance(associated_records, list) or any(
                        not isinstance(record, dict)
                        or record.get("pull_request_review_id") != review_id
                        for record in associated_records
                    ):
                        return None
                    global_associated_records = [
                        record
                        for record in inline_records
                        if isinstance(record, dict)
                        and record.get("pull_request_review_id") == review_id
                    ]
                    if sorted(
                        canonical_raw_body(record)
                        for record in associated_records
                    ) != sorted(
                        canonical_raw_body(record)
                        for record in global_associated_records
                    ):
                        return None
                associated_inline_pagination_complete = True
                feed_request_records = {
                    request_id: raw_record
                    for request_id, (
                        feed_pr,
                        raw_record,
                    ) in recent_request_by_id.items()
                    if feed_pr == pr
                }
                matched_feed_request_ids: set[int] = set()

                request_times: dict[int, int] = {}
                request_records: dict[int, dict[str, object]] = {}
                request_actor_eligibility: dict[int, bool] = {}
                issue_artifacts: list[dict[str, object]] = []
                nonterminal_records: list[tuple[str, int, int | None, str]] = []
                seen_issue_ids: set[int] = set()
                if not associated_inline_pagination_complete:
                    return None
                for raw_issue in issue_records:
                    raw_issue_id = (
                        raw_issue.get("id") if isinstance(raw_issue, dict) else None
                    )
                    expected_feed_record = feed_request_records.get(raw_issue_id)
                    if expected_feed_record is not None:
                        if (
                            raw_issue_id in matched_feed_request_ids
                            or not typed_json_equal(raw_issue, expected_feed_record)
                        ):
                            return None
                        matched_feed_request_ids.add(raw_issue_id)
                    projected_issue = project_raw_issue_record(raw_issue)
                    if projected_issue is None:
                        return None
                    issue_id = projected_issue.get("id")
                    if type(issue_id) is not int or issue_id <= 0:
                        return None
                    if issue_id in seen_issue_ids:
                        return None
                    seen_issue_ids.add(issue_id)
                    body = projected_issue.get("body")
                    created_at = projected_issue.get("created_at")
                    updated_at = projected_issue.get("updated_at")
                    if (
                        not isinstance(body, str)
                        or type(created_at) is not int
                        or type(updated_at) is not int
                        or created_at <= 0
                        or updated_at < created_at
                        or projected_issue.get("url")
                        != f"{api_root}/issues/comments/{issue_id}"
                        or projected_issue.get("html_url")
                        != (
                            f"https://github.com/{repository}/pull/{pr}"
                            f"#issuecomment-{issue_id}"
                        )
                    ):
                        return None
                    actor = raw_issue_actor(projected_issue)
                    request_user = projected_issue.get("user")
                    request_classification = (
                        _classify_github_codex_formal_request(
                            body,
                            (
                                request_user.get("login")
                                if isinstance(request_user, dict)
                                else None
                            ),
                            (
                                request_user.get("type")
                                if isinstance(request_user, dict)
                                else None
                            ),
                            expected_head=head,
                            request_contract=formal_request_contract,
                            expected_review_epoch={
                                "repository_id": current_repository_id,
                                "repository_full_name": repository,
                                "pull_request_number": pr,
                                "pr_merge_base": merge_base,
                                "head_sha": head,
                            },
                            trusted_controlled_binding=(
                                _trusted_controlled_bindings.get(issue_id)
                                if isinstance(
                                    _trusted_controlled_bindings, dict
                                )
                                else None
                            ),
                        )
                    )
                    if request_classification in {
                        "formal-broad-manual",
                        "formal-broad-controlled",
                    }:
                        if (
                            not _allow_post_as_of_requests
                            and updated_at > history_as_of_server_time
                        ) or (
                            transcript_admitted is False
                            and not resource_budget_charge(
                                resource_tracker,
                                controlled_requests=1,
                            )
                        ):
                            return None
                        request_times[issue_id] = (
                            created_at if updated_at == created_at else updated_at
                        )
                        normalized_request = {
                            "id": issue_id,
                            "url": projected_issue["html_url"],
                            "created_at": created_at,
                            "updated_at": updated_at,
                            "request_server_time": request_times[issue_id],
                            "request_server_time_field": (
                                "created_at"
                                if updated_at == created_at
                                else "updated_at"
                            ),
                            "normalized_body": formal_request_contract["command"],
                            "user": clone(projected_issue.get("user")),
                        }
                        request_records[issue_id] = normalized_request
                        request_actor_eligibility[issue_id] = bool(
                            (
                                request_classification == "formal-broad-manual"
                                and actor == "different"
                                and isinstance(request_user, dict)
                                and request_user.get("type") == "User"
                                and isinstance(request_user.get("login"), str)
                                and request_user["login"]
                                and projected_issue.get("app_slug") is None
                            )
                            or request_classification
                            == "formal-broad-controlled"
                        )
                    else:
                        normalized_issue = _normalize_github_codex_body(body)
                        if normalized_issue is None:
                            return None
                        if created_at > history_as_of_server_time:
                            if actor == "different":
                                continue
                            if not _allow_post_as_of_artifacts:
                                return None
                        if (
                            updated_at > history_as_of_server_time
                            and not _allow_post_as_of_artifacts
                        ):
                            return None
                        terminal_looking = _github_codex_issue_terminal_looking(
                            normalized_issue
                        )
                        is_declaration_match = (
                            actor == "exact"
                            and expected_declaration_raw is not None
                            and typed_json_equal(
                                raw_issue,
                                expected_declaration_raw,
                            )
                        )
                        if is_declaration_match:
                            declaration_match_count += 1
                        if is_declaration_match and not terminal_looking:
                            continue
                        if actor == "different":
                            nonterminal_records.append(
                                (
                                    "different-issue-comment",
                                    issue_id,
                                    updated_at,
                                    hashlib.sha256(
                                        canonical_raw_body(projected_issue).encode(
                                            "utf-8"
                                        )
                                    ).hexdigest(),
                                )
                            )
                            continue
                        if not terminal_looking:
                            return None
                        if actor != "exact":
                            return None
                        if (
                            projected_issue.get("app_slug") != "chatgpt-codex-connector"
                            or projected_issue.get("url")
                            != f"{api_root}/issues/comments/{issue_id}"
                            or projected_issue.get("html_url")
                            != (
                                f"https://github.com/{repository}/pull/{pr}"
                                f"#issuecomment-{issue_id}"
                            )
                        ):
                            return None
                        issue_artifacts.append(projected_issue)
                if matched_feed_request_ids != set(feed_request_records):
                    return None

                reaction_records: list[dict[str, object]] = []
                reaction_fetches = by_kind.get("request_reactions", [])
                if len(reaction_fetches) != len(request_times):
                    return None
                seen_reaction_parents: set[int] = set()
                for reaction_fetch in reaction_fetches:
                    parent_comment_id = reaction_fetch.get("parent_comment_id")
                    if (
                        type(parent_comment_id) is not int
                        or parent_comment_id not in request_times
                        or parent_comment_id in seen_reaction_parents
                    ):
                        return None
                    seen_reaction_parents.add(parent_comment_id)
                    reactions_for_parent = parse_rest_pages(
                        reaction_fetch,
                        expected_kind="request_reactions",
                        expected_url=(
                            f"{api_root}/issues/comments/{parent_comment_id}/"
                            "reactions?per_page=100"
                        ),
                        resource_tracker=resource_tracker,
                    )
                    if reactions_for_parent is None:
                        return None
                    for raw_reaction in reactions_for_parent:
                        projected_reaction = project_raw_reaction_record(raw_reaction)
                        if projected_reaction is None:
                            return None
                        projected_reaction["parent_comment_id"] = parent_comment_id
                        reaction_records.append(projected_reaction)

                review_by_id: dict[int, dict[str, object]] = {}
                other_review_ids: set[int] = set()
                excluded_future_review_ids: set[int] = set()
                excluded_future_review_by_id: dict[int, dict[str, object]] = {}
                nonterminal_review_by_id: dict[int, dict[str, object]] = {}
                seen_review_ids: set[int] = set()
                for raw_review in review_records:
                    projected_review = project_raw_review_record(raw_review)
                    if projected_review is None:
                        return None
                    review_id = projected_review.get("id")
                    if (
                        type(review_id) is not int
                        or review_id <= 0
                        or review_id in seen_review_ids
                    ):
                        return None
                    seen_review_ids.add(review_id)
                    review_state = projected_review.get("state")
                    submitted_at = projected_review.get("submitted_at")
                    actor = raw_actor(projected_review.get("user"))
                    if (
                        projected_review.get("html_url")
                        != (
                            f"https://github.com/{repository}/pull/{pr}"
                            f"#pullrequestreview-{review_id}"
                        )
                        or re.fullmatch(
                            r"[0-9a-f]{40}",
                            str(projected_review.get("commit_id")),
                        )
                        is None
                    ):
                        return None
                    if review_state == "PENDING":
                        if submitted_at is not None:
                            return None
                    elif type(submitted_at) is not int or submitted_at <= 0:
                        return None
                    if (
                        type(submitted_at) is int
                        and submitted_at > history_as_of_server_time
                    ):
                        if actor == "different":
                            other_review_ids.add(review_id)
                            excluded_future_review_ids.add(review_id)
                            excluded_future_review_by_id[review_id] = projected_review
                            continue
                        if not _allow_post_as_of_artifacts:
                            return None
                    if actor == "different":
                        other_review_ids.add(review_id)
                        nonterminal_records.append(
                            (
                                "different-pull-request-review",
                                review_id,
                                submitted_at,
                                hashlib.sha256(
                                    canonical_raw_body(projected_review).encode("utf-8")
                                ).hexdigest(),
                            )
                        )
                        continue
                    if actor != "exact":
                        return None
                    if projected_review.get("state") == "PENDING":
                        if (
                            projected_review.get("html_url")
                            != (
                                f"https://github.com/{repository}/pull/{pr}"
                                f"#pullrequestreview-{review_id}"
                            )
                            or re.fullmatch(
                                r"[0-9a-f]{40}",
                                str(projected_review.get("commit_id")),
                            )
                            is None
                        ):
                            return None
                        nonterminal_review_by_id[review_id] = projected_review
                        continue
                    review_by_id[review_id] = projected_review
                if seen_review_ids != review_ids_for_pagination:
                    return None

                inline_by_review: dict[int, list[dict[str, object]]] = {
                    review_id: [] for review_id in review_by_id
                }
                associated_inline_by_review: dict[int, list[dict[str, object]]] = {
                    review_id: [] for review_id in review_by_id
                }
                nonterminal_inline_by_review: dict[int, list[dict[str, object]]] = {
                    review_id: [] for review_id in nonterminal_review_by_id
                }
                target_review_by_child_id: dict[str, int] = {}
                nonterminal_review_by_child_id: dict[str, int] = {}
                excluded_future_review_by_child_id: dict[
                    str, tuple[int, dict[str, object]]
                ] = {}
                seen_inline_ids: set[int] = set()
                for raw_inline in inline_records:
                    if not isinstance(raw_inline, dict):
                        return None
                    projected_inline = project_raw_inline_record(raw_inline)
                    if projected_inline is None:
                        return None
                    inline_id = projected_inline.get("id")
                    if (
                        type(inline_id) is not int
                        or inline_id in seen_inline_ids
                        or projected_inline.get("url")
                        != (
                            f"https://github.com/{repository}/pull/{pr}"
                            f"#discussion_r{inline_id}"
                        )
                    ):
                        return None
                    seen_inline_ids.add(inline_id)
                    parent_id = projected_inline.get("pull_request_review_id")
                    actor = raw_actor(
                        {
                            "login": projected_inline.get("user_login"),
                            "type": projected_inline.get("user_type"),
                        }
                    )
                    if actor == "ambiguous":
                        return None
                    if parent_id is not None and type(parent_id) is not int:
                        return None
                    if parent_id in excluded_future_review_ids:
                        future_parent = excluded_future_review_by_id[parent_id]
                        child_id = str(projected_inline["id"])
                        if (
                            actor != "different"
                            or projected_inline.get("url")
                            != (
                                f"https://github.com/{repository}/pull/{pr}"
                                f"#discussion_r{child_id}"
                            )
                            or projected_inline.get("commit_id")
                            != future_parent.get("commit_id")
                            or re.fullmatch(
                                r"[0-9a-f]{40}",
                                str(projected_inline.get("original_commit_id")),
                            )
                            is None
                            or child_id in excluded_future_review_by_child_id
                        ):
                            return None
                        excluded_future_review_by_child_id[child_id] = (
                            parent_id,
                            projected_inline,
                        )
                        continue
                    if parent_id in associated_inline_by_review:
                        associated_inline_by_review[parent_id].append(projected_inline)
                    if actor == "different":
                        nonterminal_records.append(
                            (
                                "different-inline-comment",
                                inline_id,
                                None,
                                hashlib.sha256(
                                    canonical_raw_body(projected_inline).encode("utf-8")
                                ).hexdigest(),
                            )
                        )
                        continue
                    if parent_id is None:
                        nonterminal_records.append(
                            (
                                "null-parent-inline-comment",
                                inline_id,
                                None,
                                hashlib.sha256(
                                    canonical_raw_body(projected_inline).encode("utf-8")
                                ).hexdigest(),
                            )
                        )
                        continue
                    if parent_id in other_review_ids:
                        nonterminal_records.append(
                            (
                                "unrelated-parent-inline-comment",
                                inline_id,
                                None,
                                hashlib.sha256(
                                    canonical_raw_body(projected_inline).encode("utf-8")
                                ).hexdigest(),
                            )
                        )
                        continue
                    if parent_id in nonterminal_inline_by_review:
                        child_id = str(projected_inline["id"])
                        if child_id in nonterminal_review_by_child_id:
                            return None
                        nonterminal_review_by_child_id[child_id] = parent_id
                        nonterminal_inline_by_review[parent_id].append(projected_inline)
                        continue
                    if parent_id not in inline_by_review:
                        return None
                    child_id = str(projected_inline["id"])
                    if child_id in target_review_by_child_id:
                        return None
                    target_review_by_child_id[child_id] = parent_id
                    inline_by_review[parent_id].append(projected_inline)

                thread_nodes_by_review: dict[int, list[dict[str, object]]] = {
                    review_id: [] for review_id in review_by_id
                }
                nonterminal_thread_nodes_by_review: dict[
                    int, list[dict[str, object]]
                ] = {review_id: [] for review_id in nonterminal_review_by_id}
                thread_audit_nodes: list[dict[str, object]] = []
                seen_graphql_comment_ids: set[str] = set()
                seen_graphql_database_ids: set[str] = set()
                matched_excluded_future_child_ids: set[str] = set()
                for thread in thread_nodes:
                    if not isinstance(thread, dict):
                        return None
                    comments = thread.get("comments")
                    pages = (
                        comments.get("pages") if isinstance(comments, dict) else None
                    )
                    target_review_ids: set[int] = set()
                    nonterminal_review_ids: set[int] = set()
                    excluded_future_child_ids_in_thread: set[str] = set()
                    if not isinstance(pages, list):
                        return None
                    for page in pages:
                        nodes = page.get("nodes") if isinstance(page, dict) else None
                        if not isinstance(nodes, list):
                            return None
                        for comment in nodes:
                            if not isinstance(comment, dict):
                                return None
                            graphql_comment_id = comment.get("id")
                            child_id = _canonical_positive_decimal(
                                comment.get("fullDatabaseId")
                            )
                            parent = comment.get("pullRequestReview")
                            if (
                                not isinstance(graphql_comment_id, str)
                                or not graphql_comment_id
                                or graphql_comment_id in seen_graphql_comment_ids
                                or child_id is None
                                or child_id in seen_graphql_database_ids
                                or comment.get("url")
                                != (
                                    f"https://github.com/{repository}/pull/{pr}"
                                    f"#discussion_r{child_id}"
                                )
                                or (
                                    parent is not None
                                    and (
                                        not isinstance(parent, dict)
                                        or set(parent) != {"id", "fullDatabaseId"}
                                        or not isinstance(parent.get("id"), str)
                                        or not parent["id"]
                                        or _canonical_positive_decimal(
                                            parent.get("fullDatabaseId")
                                        )
                                        is None
                                    )
                                )
                            ):
                                return None
                            seen_graphql_comment_ids.add(graphql_comment_id)
                            seen_graphql_database_ids.add(child_id)
                            target_review_id = target_review_by_child_id.get(child_id)
                            if target_review_id is not None:
                                target_review_ids.add(target_review_id)
                            nonterminal_review_id = nonterminal_review_by_child_id.get(
                                child_id
                            )
                            if nonterminal_review_id is not None:
                                nonterminal_review_ids.add(nonterminal_review_id)
                            excluded_future_binding = (
                                excluded_future_review_by_child_id.get(child_id)
                            )
                            parent_database_id = (
                                _canonical_positive_decimal(
                                    parent.get("fullDatabaseId")
                                )
                                if isinstance(parent, dict)
                                else None
                            )
                            if excluded_future_binding is not None:
                                excluded_review_id, excluded_inline = (
                                    excluded_future_binding
                                )
                                if (
                                    child_id in matched_excluded_future_child_ids
                                    or parent_database_id != str(excluded_review_id)
                                    or comment.get("url") != excluded_inline.get("url")
                                ):
                                    return None
                                matched_excluded_future_child_ids.add(child_id)
                                excluded_future_child_ids_in_thread.add(child_id)
                            elif (
                                parent_database_id is not None
                                and int(parent_database_id)
                                in excluded_future_review_ids
                            ):
                                return None
                    semantic_thread = clone(thread)
                    if excluded_future_child_ids_in_thread:
                        semantic_comments = semantic_thread.get("comments")
                        semantic_pages = (
                            semantic_comments.get("pages")
                            if isinstance(semantic_comments, dict)
                            else None
                        )
                        if not isinstance(semantic_pages, list):
                            return None
                        for semantic_page in semantic_pages:
                            semantic_nodes = (
                                semantic_page.get("nodes")
                                if isinstance(semantic_page, dict)
                                else None
                            )
                            if not isinstance(semantic_nodes, list):
                                return None
                            semantic_page["nodes"] = [
                                semantic_comment
                                for semantic_comment in semantic_nodes
                                if _canonical_positive_decimal(
                                    semantic_comment.get("fullDatabaseId")
                                )
                                not in excluded_future_child_ids_in_thread
                            ]
                    semantic_comments = semantic_thread.get("comments")
                    semantic_pages = (
                        semantic_comments.get("pages")
                        if isinstance(semantic_comments, dict)
                        else None
                    )
                    if not isinstance(semantic_pages, list):
                        return None
                    has_semantic_comments = any(
                        isinstance(semantic_page, dict)
                        and isinstance(semantic_page.get("nodes"), list)
                        and bool(semantic_page["nodes"])
                        for semantic_page in semantic_pages
                    )
                    if has_semantic_comments or not excluded_future_child_ids_in_thread:
                        thread_audit_nodes.append(semantic_thread)
                    for target_review_id in target_review_ids:
                        thread_nodes_by_review[target_review_id].append(semantic_thread)
                    for nonterminal_review_id in nonterminal_review_ids:
                        nonterminal_thread_nodes_by_review[
                            nonterminal_review_id
                        ].append(semantic_thread)
                if matched_excluded_future_child_ids != set(
                    excluded_future_review_by_child_id
                ):
                    return None

                if thread_audit_nodes:
                    thread_audit_bundle = {
                        "review_threads": clone(thread_audit_nodes),
                    }
                    nonterminal_records.append(
                        (
                            "review-thread-audit",
                            pr,
                            None,
                            hashlib.sha256(
                                canonical_raw_body(thread_audit_bundle).encode("utf-8")
                            ).hexdigest(),
                        )
                    )

                for review_id, raw_review in nonterminal_review_by_id.items():
                    source_bundle = {
                        "artifact": clone(raw_review),
                        "inline_comments": clone(
                            nonterminal_inline_by_review[review_id]
                        ),
                        "review_threads": clone(
                            nonterminal_thread_nodes_by_review[review_id]
                        ),
                    }
                    nonterminal_records.append(
                        (
                            "pull-request-review",
                            review_id,
                            None,
                            hashlib.sha256(
                                canonical_raw_body(source_bundle).encode("utf-8")
                            ).hexdigest(),
                        )
                    )

                artifact_bases: list[
                    tuple[int, int, str, str, str, str | None, str]
                ] = []
                audit_only_artifact_bases: list[
                    tuple[int, int, str, str, str, str | None, str]
                ] = []
                unresolved_artifact_bases: list[
                    tuple[int, int, str, str, str, str | None, str]
                ] = []
                invalid_review_state_blockers: list[
                    tuple[int, int, str, str, str, str | None, str]
                ] = []
                for review_id, raw_review in review_by_id.items():
                    user = raw_review.get("user")
                    submitted_at = raw_review.get("submitted_at")
                    review_commit = raw_review.get("commit_id")
                    if (
                        raw_actor(user) != "exact"
                        or type(submitted_at) is not int
                        or submitted_at <= 0
                        or (
                            submitted_at > history_as_of_server_time
                            and not _allow_post_as_of_artifacts
                        )
                        or raw_review.get("html_url")
                        != (
                            f"https://github.com/{repository}/pull/{pr}"
                            f"#pullrequestreview-{review_id}"
                        )
                        or not isinstance(review_commit, str)
                        or re.fullmatch(r"[0-9a-f]{40}", review_commit) is None
                    ):
                        return None
                    per_review_threads = {
                        "endpoint": "https://api.github.com/graphql",
                        "pagination_complete": True,
                        "pages": [
                            {
                                "after": None,
                                "nodes": thread_nodes_by_review[review_id],
                                "pageInfo": {
                                    "hasNextPage": False,
                                    "endCursor": None,
                                },
                            }
                        ],
                    }
                    joined = _review_thread_findings_from_raw(
                        inline_by_review[review_id],
                        per_review_threads,
                        repository=repository,
                        pull_request=pr,
                        parent_review_id=review_id,
                    )
                    if joined is None:
                        return None
                    body = raw_review.get("body")
                    state = raw_review.get("state")
                    target_child_ids = {
                        finding["child_id"] for finding in joined
                    }
                    child_finding_commits: dict[
                        int, tuple[str, str]
                    ] = {}
                    normalized_review_body = _normalize_github_codex_body(body)
                    is_legacy_native_review_finding = (
                        isinstance(normalized_review_body, str)
                        and state in {"COMMENTED", "CHANGES_REQUESTED"}
                        and not associated_inline_by_review[review_id]
                        and not joined
                        and _github_codex_legacy_top_level_review_finding_commit(
                            normalized_review_body,
                            repository=repository,
                            native_commit_id=review_commit,
                        )
                        == review_commit
                    )
                    for child in inline_by_review[review_id]:
                        normalized_child_body = _normalize_github_codex_body(
                            child.get("body")
                        )
                        child_commit = child.get("commit_id")
                        child_original_commit = child.get(
                            "original_commit_id"
                        )
                        if (
                            not isinstance(child_commit, str)
                            or re.fullmatch(r"[0-9a-f]{40}", child_commit)
                            is None
                            or not isinstance(child_original_commit, str)
                            or re.fullmatch(
                                r"[0-9a-f]{40}", child_original_commit
                            )
                            is None
                            or not normalized_child_body
                            or child.get("normalized_body") != normalized_child_body
                        ):
                            return None
                        child_id = child.get("id")
                        if child_id in target_child_ids:
                            assert type(child_id) is int
                            child_finding_commits[child_id] = (
                                child_commit,
                                child_original_commit,
                            )
                    semantic, semantic_commit = _github_codex_review_body_semantic(
                        body,
                        repository=repository,
                        state=state,
                        commit_id=review_commit,
                        current_head=head,
                        has_associated_children=bool(
                            associated_inline_by_review[review_id]
                        ),
                        target_thread_findings=joined,
                        allow_legacy_native_review=True,
                    )
                    if semantic_commit not in {None, review_commit}:
                        return None
                    source_bundle = {
                        "artifact": clone(raw_review),
                        "inline_comments": clone(inline_by_review[review_id]),
                        "review_threads": clone(thread_nodes_by_review[review_id]),
                    }
                    if semantic == "nonterminal":
                        nonterminal_records.append(
                            (
                                "pull-request-review",
                                review_id,
                                submitted_at,
                                hashlib.sha256(
                                    canonical_raw_body(source_bundle).encode("utf-8")
                                ).hexdigest(),
                            )
                        )
                        continue
                    finding_disposition: dict[str, object] | None = None
                    if (
                        parsed_scope == current_scope_key
                        and current_ancestry is not None
                        and (
                            semantic == "findings"
                            or (
                                semantic == "clean"
                                and bool(child_finding_commits)
                            )
                        )
                    ):
                        parent_is_finding = (
                            pull_request_review_has_top_level_finding(
                                raw_body=body,
                                repository=repository,
                                state=state,
                                parent_commit=review_commit,
                            )
                        )
                        resolution_by_child_id = {
                            finding["child_id"]: finding["is_resolved"]
                            for finding in joined
                        }
                        if (
                            parent_is_finding is None
                            or set(child_finding_commits)
                            != set(resolution_by_child_id)
                        ):
                            return None
                        reduced_children = [
                            {
                                "child_id": child_id,
                                "is_resolved": resolution_by_child_id[child_id],
                                "commit_id": commits[0],
                                "original_commit_id": commits[1],
                            }
                            for child_id, commits in child_finding_commits.items()
                        ]
                        ancestry_commits = {
                            commit
                            for commits in child_finding_commits.values()
                            for commit in commits
                        }
                        ancestry_commits.add(review_commit)
                        observed_current_ancestry_heads.update(ancestry_commits)
                        finding_disposition = reduce_pull_request_review_findings(
                            state=state,
                            parent_commit=review_commit,
                            parent_is_finding=parent_is_finding,
                            child_findings=reduced_children,
                            current_head=head,
                            finding_ancestry=ancestry,
                        )
                        if finding_disposition is None or (
                            semantic == "findings"
                            and finding_disposition.get("has_finding_history")
                            is not True
                        ):
                            return None
                        if (
                            semantic == "findings"
                            and finding_disposition.get("has_blocker") is False
                        ):
                            audit_only_artifact_bases.append(
                                (
                                    submitted_at,
                                    review_id,
                                    "pull-request-review",
                                    semantic,
                                    hashlib.sha256(
                                        canonical_raw_body(source_bundle).encode(
                                            "utf-8"
                                        )
                                    ).hexdigest(),
                                    review_commit,
                                    (
                                        "unresolved-thread-finding"
                                        if any(
                                            finding.get("is_resolved") is False
                                            for finding in joined
                                        )
                                        else "finding"
                                    ),
                                )
                            )
                            continue
                        if (
                            semantic == "clean"
                            and finding_disposition.get("has_blocker") is True
                        ):
                            return None
                    elif (
                        parsed_scope == current_scope_key
                        and semantic == "clean"
                        and child_finding_commits
                    ):
                        return None
                    elif review_commit != head:
                        if parsed_scope == current_scope_key and semantic == "clean":
                            continue
                        return None
                    invalid_review_state = (
                        _github_codex_invalid_review_state_terminal_signal(
                            body,
                            state=state,
                            has_associated_children=bool(
                                associated_inline_by_review[review_id]
                            ),
                        )
                    )
                    has_unresolved_finding = (
                        semantic == "findings"
                        and finding_disposition is not None
                        and finding_disposition.get("has_blocker") is True
                        and any(finding.get("is_resolved") is False for finding in joined)
                    )
                    raw_artifact_kind = (
                        "malformed-terminal-artifact"
                        if invalid_review_state or semantic == "malformed"
                        else (
                            "unresolved-thread-finding"
                            if has_unresolved_finding
                            else "terminal-payload"
                        )
                    )
                    role = (
                        legacy_finding_native_review_role
                        if is_legacy_native_review_finding
                        and raw_artifact_kind == "terminal-payload"
                        and semantic == "findings"
                        else artifact_authority_role(raw_artifact_kind, semantic)
                    )
                    if role is None:
                        return None
                    artifact_basis = (
                        submitted_at,
                        review_id,
                        "pull-request-review",
                        semantic,
                        hashlib.sha256(
                            canonical_raw_body(source_bundle).encode("utf-8")
                        ).hexdigest(),
                        review_commit,
                        role,
                    )
                    artifact_bases.append(artifact_basis)
                    if invalid_review_state:
                        invalid_review_state_blockers.append(artifact_basis)
                    if has_unresolved_finding:
                        unresolved_artifact_bases.append(artifact_basis)

                for raw_issue in issue_artifacts:
                    issue_id = raw_issue["id"]
                    created_at = raw_issue.get("created_at")
                    updated_at = raw_issue.get("updated_at")
                    if (
                        type(issue_id) is not int
                        or raw_issue_actor(raw_issue) != "exact"
                        or type(created_at) is not int
                        or type(updated_at) is not int
                        or created_at <= 0
                        or updated_at < created_at
                        or raw_issue.get("url")
                        != (f"{api_root}/issues/comments/{issue_id}")
                        or raw_issue.get("html_url")
                        != (
                            f"https://github.com/{repository}/pull/{pr}"
                            f"#issuecomment-{issue_id}"
                        )
                    ):
                        return None
                    server_time = created_at if updated_at == created_at else updated_at
                    body = raw_issue.get("body")
                    semantic, parsed_commit = _github_codex_issue_body_semantic(
                        body,
                        repository=repository,
                        head=head,
                        allow_foreign_finding_sha=(parsed_scope == current_scope_key),
                    )
                    normalized_issue_body = _normalize_github_codex_body(body)
                    pending_clean_marker = (
                        _github_codex_clean_issue_marker(normalized_issue_body)
                        if isinstance(normalized_issue_body, str)
                        else None
                    )
                    if (
                        semantic == "malformed"
                        and pending_clean_marker is not None
                        and len(pending_clean_marker[1]) == 10
                    ):
                        short_commit = pending_clean_marker[1]
                        resolved_ancestor: str | None = None
                        if head.startswith(short_commit):
                            resolved_ancestor = head
                        elif parsed_scope == current_scope_key:
                            resolved_ancestor = legacy_short_commit_resolutions.get(
                                short_commit
                            )
                            if resolved_ancestor is not None:
                                observed_current_legacy_short_commit_prefixes.add(
                                    short_commit
                                )
                        if resolved_ancestor is not None:
                            semantic = pending_short_clean_semantic
                            parsed_commit = short_commit
                    if semantic == "nonterminal":
                        nonterminal_records.append(
                            (
                                "issue-comment",
                                issue_id,
                                server_time,
                                hashlib.sha256(
                                    canonical_raw_body(raw_issue).encode("utf-8")
                                ).hexdigest(),
                            )
                        )
                        continue
                    if (
                        semantic == "findings"
                        and parsed_scope == current_scope_key
                        and current_ancestry is not None
                    ):
                        if not isinstance(parsed_commit, str):
                            return None
                        observed_current_ancestry_heads.add(parsed_commit)
                        relation = ancestry.get(parsed_commit)
                        if relation is None or (
                            parsed_commit == head and relation != 0
                        ):
                            return None
                        if relation == 1:
                            audit_only_artifact_bases.append(
                                (
                                    server_time,
                                    issue_id,
                                    "issue-comment",
                                    semantic,
                                    hashlib.sha256(
                                        canonical_raw_body(raw_issue).encode(
                                            "utf-8"
                                        )
                                    ).hexdigest(),
                                    parsed_commit,
                                    "finding",
                                )
                            )
                            continue
                    elif semantic == "findings" and parsed_commit != head:
                        return None
                    raw_artifact_kind = (
                        "active-top-level-finding"
                        if semantic == "findings"
                        else (
                            "malformed-terminal-artifact"
                            if semantic == "malformed"
                            else "terminal-payload"
                        )
                    )
                    role = (
                        pending_short_clean_role
                        if semantic == pending_short_clean_semantic
                        else artifact_authority_role(raw_artifact_kind, semantic)
                    )
                    if role is None:
                        return None
                    artifact_bases.append(
                        (
                            server_time,
                            issue_id,
                            "issue-comment",
                            semantic,
                            hashlib.sha256(
                                canonical_raw_body(raw_issue).encode("utf-8")
                            ).hexdigest(),
                            parsed_commit,
                            role,
                        )
                    )

                provider_reactions: list[tuple[int, int, int, str]] = []
                semantic_reaction_records: list[dict[str, object]] = []
                seen_reaction_ids: set[int] = set()
                for raw_reaction in reaction_records:
                    reaction_id = raw_reaction.get("id")
                    created_at = raw_reaction.get("created_at")
                    parent_comment_id = raw_reaction.get("parent_comment_id")
                    actor = raw_actor(raw_reaction.get("user"))
                    if (
                        type(reaction_id) is not int
                        or reaction_id <= 0
                        or reaction_id in seen_reaction_ids
                        or type(created_at) is not int
                        or created_at <= 0
                        or type(parent_comment_id) is not int
                        or parent_comment_id not in request_times
                    ):
                        return None
                    seen_reaction_ids.add(reaction_id)
                    if created_at > history_as_of_server_time:
                        if actor == "different":
                            continue
                        if not (
                            _allow_post_as_of_artifacts
                            and parsed_scope == current_scope_key
                            and artifact_bases
                        ):
                            return None
                    semantic_reaction_records.append(raw_reaction)
                    if actor == "different":
                        continue
                    if (
                        actor != "exact"
                        or raw_reaction.get("content") not in github_reaction_contents
                    ):
                        return None
                    provider_reactions.append(
                        (
                            created_at,
                            reaction_id,
                            parent_comment_id,
                            raw_reaction["content"],
                        )
                    )

                raw_semantic_scope = {
                    "pull_number": pr,
                    "scope_key": parsed_scope,
                    "repository": repository,
                    "base_oid": base_oid,
                    "merge_base": merge_base,
                    "head": head,
                    "lifecycle": clone(normalized_lifecycle),
                    "request_times": dict(request_times),
                    "request_records": {
                        request_id: clone(request_record)
                        for request_id, request_record in request_records.items()
                    },
                    "request_actor_eligibility": dict(request_actor_eligibility),
                    "feed_request_ids": (
                        None
                        if _single_scope_pull_number is not None
                        or parsed_scope == current_scope_key
                        else sorted(feed_request_records)
                    ),
                    "provider_reactions": list(provider_reactions),
                    "reaction_records": [
                        clone(reaction_record)
                        for reaction_record in semantic_reaction_records
                    ],
                    "artifact_bases": list(artifact_bases),
                    "audit_only_artifact_bases": list(
                        audit_only_artifact_bases
                    ),
                    "unresolved_artifact_bases": list(unresolved_artifact_bases),
                    "invalid_review_state_blockers": list(
                        invalid_review_state_blockers
                    ),
                    "nonterminal_records": list(nonterminal_records),
                }
                future_prefix_omission_eligible = (
                    _single_scope_pull_number is None
                    and pr in future_prefix_pull_numbers
                    and pr not in request_seed_pull_numbers
                    and pr not in anchor_pull_numbers
                    and not request_times
                    and not provider_reactions
                    and not semantic_reaction_records
                    and not artifact_bases
                    and not unresolved_artifact_bases
                    and not invalid_review_state_blockers
                    and not nonterminal_records
                )
                scope_identity_audit_item = {
                    "pull_number": pr,
                    "base_oid": base_oid,
                    "head_oid": head,
                    "merge_base": merge_base,
                    "lifecycle": clone(normalized_lifecycle),
                }
                retained_pull_scope_audit.append(scope_identity_audit_item)
                raw_semantic_scopes.append(raw_semantic_scope)
                if future_prefix_omission_eligible:
                    future_prefix_omission_eligibility_audit.append(
                        clone(scope_identity_audit_item)
                    )
            if (
                seen_detail_pulls != set(discovered_pulls)
                or current_scope_key not in seen_scopes
                or (
                    expected_declaration_raw is not None
                    and declaration_match_count != 1
                )
                or (
                    current_ancestry is not None
                    and require_current_ancestry_exact
                    and set(ancestry) != observed_current_ancestry_heads
                )
                or (
                    current_legacy_short_commit_resolutions is not None
                    and set(legacy_short_commit_resolutions)
                    != observed_current_legacy_short_commit_prefixes
                )
            ):
                return None
            if not resource_budget_charge(resource_tracker):
                return None
            if isinstance(scope_discovery_projection, dict):
                retained_pull_scope_audit.sort(
                    key=lambda item: int(item["pull_number"]),
                )
                expected_retained_pull_numbers = scope_discovery_projection.get(
                    "union_pull_numbers"
                )
                if not typed_json_equal(
                    [item["pull_number"] for item in retained_pull_scope_audit],
                    expected_retained_pull_numbers,
                ):
                    return None
                scope_discovery_projection["retained_pull_scope_audit"] = clone(
                    retained_pull_scope_audit
                )
                scope_discovery_projection[
                    "future_prefix_omission_eligibility_audit"
                ] = sorted(
                    future_prefix_omission_eligibility_audit,
                    key=lambda item: int(item["pull_number"]),
                )
            try:
                transcript_digest = hashlib.sha256(
                    canonical_raw_body(value).encode("utf-8")
                ).hexdigest()
            except (TypeError, UnicodeEncodeError, ValueError):
                return None
            return {
                "raw_semantic_dataset_version": 1,
                "transcript_sha256": transcript_digest,
                "scope_discovery_projection": clone(scope_discovery_projection),
                "scopes": raw_semantic_scopes,
            }

        def select_raw_terminal_artifact(
            raw_scope: dict[str, object],
            *,
            prefer_unresolved_thread_blocker: bool,
        ) -> tuple[bool, tuple[object, ...] | None, bool]:
            artifact_bases = raw_scope.get("artifact_bases")
            unresolved_artifact_bases = raw_scope.get("unresolved_artifact_bases")
            invalid_review_state_blockers = raw_scope.get(
                "invalid_review_state_blockers"
            )
            if (
                not isinstance(artifact_bases, list)
                or not isinstance(unresolved_artifact_bases, list)
                or not isinstance(invalid_review_state_blockers, list)
            ):
                return (False, None, False)
            if not artifact_bases:
                return (True, None, False)
            if prefer_unresolved_thread_blocker and unresolved_artifact_bases:
                return (
                    True,
                    tuple(
                        max(
                            unresolved_artifact_bases,
                            key=lambda item: (item[0], item[1]),
                        )
                    ),
                    bool(invalid_review_state_blockers),
                )
            if invalid_review_state_blockers:
                if len(invalid_review_state_blockers) > 1:
                    return (True, None, True)
                return (
                    True,
                    tuple(invalid_review_state_blockers[0]),
                    True,
                )
            blocking_findings = [
                item for item in artifact_bases if item[3] == "findings"
            ]
            malformed_artifacts = [
                item for item in artifact_bases if item[3] == "malformed"
            ]
            if blocking_findings:
                blocking_time = max(item[0] for item in blocking_findings)
                if len(
                    {
                        item[2]
                        for item in artifact_bases
                        if item[0] == blocking_time
                    }
                ) != 1:
                    return (False, None, bool(malformed_artifacts))
                return (
                    True,
                    tuple(
                        max(
                            blocking_findings,
                            key=lambda item: (item[0], item[1]),
                        )
                    ),
                    bool(malformed_artifacts),
                )
            latest_time = max(item[0] for item in artifact_bases)
            latest = [item for item in artifact_bases if item[0] == latest_time]
            if len({item[2] for item in latest}) != 1:
                return (False, None, False)
            priority = {
                "clean": 1,
                pending_short_clean_semantic: 1,
                "findings": 2,
                "malformed": 3,
            }
            if any(item[3] not in priority for item in latest):
                return (False, None, False)
            highest = max(priority[item[3]] for item in latest)
            return (
                True,
                tuple(
                    max(
                        (item for item in latest if priority[item[3]] == highest),
                        key=lambda item: item[1],
                    )
                ),
                False,
            )

        def raw_scope_authority_audit(
            raw_scope: dict[str, object],
            *,
            request_receipt_bindings: dict[int, dict[str, object]] | None,
        ) -> dict[str, object] | None:
            scope_value = raw_scope.get("scope_key")
            lifecycle = raw_scope.get("lifecycle")
            request_times = raw_scope.get("request_times")
            request_records = raw_scope.get("request_records")
            request_actor_eligibility = raw_scope.get("request_actor_eligibility")
            reaction_records = raw_scope.get("reaction_records")
            artifact_bases = raw_scope.get("artifact_bases")
            audit_only_artifact_bases = raw_scope.get(
                "audit_only_artifact_bases"
            )
            nonterminal_records = raw_scope.get("nonterminal_records")
            if (
                not isinstance(scope_value, tuple)
                or len(scope_value) != 4
                or not isinstance(lifecycle, dict)
                or not isinstance(request_times, dict)
                or not isinstance(request_records, dict)
                or not isinstance(request_actor_eligibility, dict)
                or set(request_actor_eligibility) != set(request_times)
                or any(
                    type(eligible) is not bool
                    for eligible in request_actor_eligibility.values()
                )
                or not isinstance(reaction_records, list)
                or not isinstance(artifact_bases, list)
                or not isinstance(audit_only_artifact_bases, list)
                or not isinstance(nonterminal_records, list)
            ):
                return None
            scope_audit_requests: list[dict[str, object]] = []
            for request_id in sorted(request_times):
                request_record = request_records.get(request_id)
                if not isinstance(request_record, dict):
                    return None
                binding = (
                    request_receipt_bindings.get(request_id)
                    if isinstance(request_receipt_bindings, dict)
                    else None
                )
                scope_audit_requests.append(
                    {
                        "request": clone(request_record),
                        "request_scope": (
                            list(binding["scope"])
                            if isinstance(binding, dict)
                            else None
                        ),
                        "request_scope_receipt": (
                            clone(binding["receipt"])
                            if isinstance(binding, dict)
                            else None
                        ),
                    }
                )
            scope_audit_reactions: list[dict[str, object]] = []
            for raw_reaction in sorted(
                reaction_records,
                key=lambda item: (
                    int(item["created_at"]),
                    int(item["id"]),
                    int(item["parent_comment_id"]),
                ),
            ):
                if not isinstance(raw_reaction, dict):
                    return None
                raw_user = raw_reaction.get("user")
                if not isinstance(raw_user, dict):
                    return None
                parent_comment_id = raw_reaction.get("parent_comment_id")
                if type(parent_comment_id) is not int:
                    return None
                scope_audit_reactions.append(
                    {
                        "id": raw_reaction["id"],
                        "parent_request_id": parent_comment_id,
                        "parent_reactions_api_url": (
                            "https://api.github.com/repos/"
                            f"{current_repository}/issues/comments/"
                            f"{parent_comment_id}/reactions?per_page=100"
                        ),
                        "created_at": raw_reaction["created_at"],
                        "content": raw_reaction["content"],
                        "user_login": raw_user.get("login"),
                        "user_type": raw_user.get("type"),
                    }
                )
            scope_audit_artifacts = [
                {
                    "server_time": server_time,
                    "id": artifact_id,
                    "channel": channel,
                    "semantic": semantic,
                    "role": role,
                    "source_record_sha256": source_digest,
                    "artifact_commit": artifact_commit,
                }
                for (
                    server_time,
                    artifact_id,
                    channel,
                    semantic,
                    source_digest,
                    artifact_commit,
                    role,
                ) in sorted([*artifact_bases, *audit_only_artifact_bases])
            ]
            scope_audit_nonterminal = [
                {
                    "channel": channel,
                    "id": record_id,
                    "server_time": server_time,
                    "source_record_sha256": source_digest,
                }
                for (
                    channel,
                    record_id,
                    server_time,
                    source_digest,
                ) in sorted(nonterminal_records)
            ]
            if not any(
                (
                    scope_audit_requests,
                    scope_audit_reactions,
                    scope_audit_artifacts,
                    scope_audit_nonterminal,
                )
            ):
                return None
            return {
                "scope_key": list(scope_value),
                "lifecycle": clone(lifecycle),
                "requests": scope_audit_requests,
                "reactions": scope_audit_reactions,
                "applicable_artifacts": scope_audit_artifacts,
                "nonterminal_records": scope_audit_nonterminal,
            }

        def project_raw_semantic_dataset(
            raw_dataset: object,
            *,
            request_scope_receipts: object,
            current_ancestry: dict[str, int] | None,
            prefer_unresolved_thread_blocker: bool,
            allow_post_as_of_requests: bool,
            allow_extra_request_scope_receipts_for_current_audit: bool,
            endpoint_plane_only: bool,
            sidecar_blind_audit: bool,
            inventory_validation_context: dict[str, object],
            trusted_controlled_bindings: object = None,
        ) -> dict[str, object] | None:
            if (
                type(allow_extra_request_scope_receipts_for_current_audit)
                is not bool
                or not isinstance(raw_dataset, dict)
                or set(raw_dataset)
                != {
                    "raw_semantic_dataset_version",
                    "transcript_sha256",
                    "scope_discovery_projection",
                    "scopes",
                }
                or raw_dataset.get("raw_semantic_dataset_version") != 1
                or not isinstance(raw_dataset.get("transcript_sha256"), str)
                or re.fullmatch(
                    r"[0-9a-f]{64}", str(raw_dataset.get("transcript_sha256"))
                )
                is None
                or not isinstance(raw_dataset.get("scopes"), list)
            ):
                return None
            raw_scopes = raw_dataset["scopes"]
            if endpoint_plane_only:
                endpoint_result: dict[str, object] = {
                    "endpoint_complete": True,
                    "transcript_sha256": raw_dataset["transcript_sha256"],
                }
                if not sidecar_blind_audit:
                    return endpoint_result
                scope_summaries: list[dict[str, object]] = []
                projected_audits: list[dict[str, object]] = []
                for raw_scope in raw_scopes:
                    if not isinstance(raw_scope, dict):
                        return None
                    scope_value = raw_scope.get("scope_key")
                    pull_number = raw_scope.get("pull_number")
                    lifecycle = raw_scope.get("lifecycle")
                    if (
                        not isinstance(scope_value, tuple)
                        or len(scope_value) != 4
                        or type(pull_number) is not int
                        or not isinstance(lifecycle, dict)
                    ):
                        return None
                    raw_audit = raw_scope_authority_audit(
                        raw_scope,
                        request_receipt_bindings=None,
                    )
                    (
                        terminal_ok,
                        selected,
                        has_invalid_review_state_blocker,
                    ) = select_raw_terminal_artifact(
                        raw_scope,
                        prefer_unresolved_thread_blocker=(
                            prefer_unresolved_thread_blocker
                        ),
                    )
                    if not terminal_ok or (
                        has_invalid_review_state_blocker
                        and tuple(scope_value) != current_scope_key
                    ):
                        return None
                    source_ordering_key: list[int] | None = None
                    source_evidence: dict[str, object] | None = None
                    category = "not-candidate"
                    if selected is not None:
                        source_ordering_key = [int(selected[0]), int(selected[1])]
                        source_evidence = {
                            "carrier": "terminal-artifact",
                            "channel": selected[2],
                            "semantic": selected[3],
                            "native_identity": [selected[2], selected[1]],
                            "source_record_sha256": selected[4],
                        }
                        if (
                            tuple(scope_value) != current_scope_key
                            and history_start_exclusive
                            < source_ordering_key[0]
                            <= history_as_of_server_time
                        ):
                            category = "required-terminal"
                    raw_classification = (
                        "current"
                        if tuple(scope_value) == current_scope_key
                        else (
                            "historical-candidate"
                            if category == "required-terminal"
                            else "confirmed-non-candidate"
                        )
                    )
                    scope_summaries.append(
                        {
                            "pull_number": pull_number,
                            "scope_key": list(scope_value),
                            "lifecycle": clone(lifecycle),
                            "raw_scope_category": category,
                            "raw_classification": raw_classification,
                            "source_ordering_key": source_ordering_key,
                            "source_evidence": source_evidence,
                        }
                    )
                    if raw_audit is not None:
                        projected_audit = clone(raw_audit)
                        assert isinstance(projected_audit, dict)
                        projected_requests = projected_audit.get("requests")
                        if not isinstance(projected_requests, list):
                            return None
                        for projected_request in projected_requests:
                            if not isinstance(projected_request, dict):
                                return None
                            projected_request.pop("request_scope", None)
                            projected_request.pop("request_scope_receipt", None)
                        projected_audits.append(projected_audit)
                endpoint_result["sidecar_blind_scope_summaries"] = sorted(
                    scope_summaries,
                    key=lambda item: int(item["pull_number"]),
                )
                endpoint_result["sidecar_blind_authority_audit"] = sorted(
                    projected_audits,
                    key=lambda item: int(item["scope_key"][1]),
                )
                endpoint_result["scope_discovery_projection"] = clone(
                    raw_dataset["scope_discovery_projection"]
                )
                return endpoint_result

            context_parts = inventory_validation_context_parts(
                inventory_validation_context
            )
            if context_parts is None:
                return None
            receipt_mapping_result = inventory_validation_memoized(
                inventory_validation_context,
                namespace=(
                    f"raw-request-scope-receipts-v1:{allow_post_as_of_requests}"
                ),
                inventory=request_scope_receipts,
                producer=lambda: request_scope_receipt_mapping(
                    request_scope_receipts,
                    resource_tracker=context_parts[2],
                    maximum_server_time=(
                        None if allow_post_as_of_requests else history_as_of_server_time
                    ),
                    trusted_controlled_bindings=trusted_controlled_bindings,
                ),
                budget_tracker=context_parts[2],
            )
            receipt_mapping = (
                receipt_mapping_result
                if isinstance(receipt_mapping_result, dict)
                else None
            )
            entries: list[dict[str, object]] = []
            scope_authority_audit: list[dict[str, object]] = []
            scope_classifications: list[dict[str, object]] = []
            used_receipt_ids: set[int] = set()
            request_receipt_closure_required = False
            for raw_scope in raw_scopes:
                if not isinstance(raw_scope, dict):
                    return None
                parsed_scope = raw_scope.get("scope_key")
                repository = raw_scope.get("repository")
                pr = raw_scope.get("pull_number")
                base_oid = raw_scope.get("base_oid")
                merge_base = raw_scope.get("merge_base")
                head = raw_scope.get("head")
                lifecycle = raw_scope.get("lifecycle")
                request_times = raw_scope.get("request_times")
                request_records = raw_scope.get("request_records")
                request_actor_eligibility = raw_scope.get("request_actor_eligibility")
                feed_request_ids = raw_scope.get("feed_request_ids")
                provider_reactions = raw_scope.get("provider_reactions")
                reaction_records = raw_scope.get("reaction_records")
                artifact_bases = raw_scope.get("artifact_bases")
                nonterminal_records = raw_scope.get("nonterminal_records")
                if (
                    not isinstance(parsed_scope, tuple)
                    or len(parsed_scope) != 4
                    or repository != current_repository
                    or type(pr) is not int
                    or not isinstance(base_oid, str)
                    or not isinstance(merge_base, str)
                    or not isinstance(head, str)
                    or not isinstance(lifecycle, dict)
                    or not isinstance(request_times, dict)
                    or not isinstance(request_records, dict)
                    or not isinstance(request_actor_eligibility, dict)
                    or set(request_actor_eligibility) != set(request_times)
                    or any(
                        type(eligible) is not bool
                        for eligible in request_actor_eligibility.values()
                    )
                    or (
                        feed_request_ids is not None
                        and (
                            not isinstance(feed_request_ids, list)
                            or any(
                                type(request_id) is not int
                                for request_id in feed_request_ids
                            )
                            or len(set(feed_request_ids)) != len(feed_request_ids)
                        )
                    )
                    or not isinstance(provider_reactions, list)
                    or not isinstance(reaction_records, list)
                    or not isinstance(artifact_bases, list)
                    or not isinstance(nonterminal_records, list)
                ):
                    return None
                request_receipt_bindings: dict[int, dict[str, object]] = {}
                for request_id, normalized_request in request_records.items():
                    if type(request_id) is not int or not isinstance(
                        normalized_request, dict
                    ):
                        return None
                    binding = (
                        receipt_mapping.get(request_id)
                        if isinstance(receipt_mapping, dict)
                        else None
                    )
                    if (
                        request_actor_eligibility.get(request_id) is True
                        and isinstance(binding, dict)
                        and typed_json_equal(binding.get("request"), normalized_request)
                    ):
                        request_receipt_bindings[request_id] = binding
                        used_receipt_ids.add(request_id)
                raw_audit = raw_scope_authority_audit(
                    raw_scope,
                    request_receipt_bindings=request_receipt_bindings,
                )
                if raw_audit is not None:
                    scope_authority_audit.append(raw_audit)
                current_request_times = {
                    request_id: request_time
                    for request_id, request_time in request_times.items()
                    if (
                        isinstance(request_receipt_bindings.get(request_id), dict)
                        and request_receipt_bindings[request_id].get("scope")
                        == parsed_scope
                    )
                }
                current_provider_reactions = [
                    item
                    for item in provider_reactions
                    if item[2] in current_request_times
                ]
                eligible_current_provider_reactions = list(current_provider_reactions)
                eligible_exact_request_ids = {
                    item[2] for item in eligible_current_provider_reactions
                }
                if feed_request_ids is not None:
                    eligible_exact_request_ids = {
                        request_id
                        for request_id in feed_request_ids
                        if request_id in current_request_times
                        and history_start_exclusive
                        < current_request_times[request_id]
                        <= history_as_of_server_time
                    }
                    eligible_current_provider_reactions = []
                    for item in current_provider_reactions:
                        if (
                            request_times[item[2]] <= history_start_exclusive
                            or item[0] <= history_start_exclusive
                        ):
                            continue
                        if (
                            item[0] > history_as_of_server_time
                            or item[2] not in feed_request_ids
                        ):
                            return None
                        eligible_current_provider_reactions.append(item)
                request_scope_kinds: dict[int, str] = {}
                for request_id in request_times:
                    binding = request_receipt_bindings.get(request_id)
                    binding_scope = (
                        binding.get("scope") if isinstance(binding, dict) else None
                    )
                    if binding_scope == parsed_scope:
                        request_scope_kinds[request_id] = "exact"
                    elif (
                        isinstance(binding_scope, tuple)
                        and binding_scope[:2] == parsed_scope[:2]
                        and binding_scope[3] != parsed_scope[3]
                    ):
                        request_scope_kinds[request_id] = "old-epoch"
                    elif (
                        isinstance(binding_scope, tuple)
                        and binding_scope[:2] == parsed_scope[:2]
                        and binding_scope[2] != parsed_scope[2]
                        and binding_scope[3] == parsed_scope[3]
                    ):
                        request_scope_kinds[request_id] = "base-changed-same-head"
                    else:
                        request_scope_kinds[request_id] = "invalid"
                (
                    terminal_ok,
                    selected,
                    has_invalid_review_state_blocker,
                ) = select_raw_terminal_artifact(
                    raw_scope,
                    prefer_unresolved_thread_blocker=(prefer_unresolved_thread_blocker),
                )
                if not terminal_ok or (
                    has_invalid_review_state_blocker
                    and parsed_scope != current_scope_key
                ):
                    return None
                if selected is not None:
                    source_ordering_key = [selected[0], selected[1]]
                    source_evidence = {
                        "carrier": "terminal-artifact",
                        "channel": selected[2],
                        "semantic": selected[3],
                        "native_identity": [selected[2], selected[1]],
                        "source_record_sha256": selected[4],
                    }
                elif has_invalid_review_state_blocker:
                    source_ordering_key = None
                    source_evidence = None
                else:
                    if "base-changed-same-head" in request_scope_kinds.values():
                        return None
                    if request_times and (
                        receipt_mapping is None
                        or set(request_receipt_bindings) != set(request_times)
                    ):
                        return None
                    if request_times:
                        request_receipt_closure_required = True
                    scope_classifications.append(
                        {
                            "pull_number": pr,
                            "scope_key": list(parsed_scope),
                            "classification": (
                                "current"
                                if parsed_scope == current_scope_key
                                else "confirmed-non-candidate"
                            ),
                        }
                    )
                    continue

                entry: dict[str, object] = {
                    "scope_key": list(parsed_scope),
                    "source_ordering_key": source_ordering_key,
                    "source_evidence": source_evidence,
                }
                if current_ancestry is not None:
                    entry["current_authority_projection"] = {
                        "scope": {
                            "repository": repository,
                            "pull_request": pr,
                            "base_oid": base_oid,
                            "merge_base": merge_base,
                            "head": head,
                        },
                        "lifecycle": clone(lifecycle),
                        "requests": [
                            {
                                "request": clone(request_records[request_id]),
                                "request_scope": (
                                    list(binding["scope"])
                                    if isinstance(
                                        (
                                            binding := request_receipt_bindings.get(
                                                request_id
                                            )
                                        ),
                                        dict,
                                    )
                                    else None
                                ),
                                "request_scope_receipt": (
                                    clone(binding["receipt"])
                                    if isinstance(binding, dict)
                                    else None
                                ),
                            }
                            for request_id in sorted(request_times)
                        ],
                        "applicable_artifacts": [
                            {
                                "server_time": server_time,
                                "id": artifact_id,
                                "channel": channel,
                                "semantic": semantic,
                                "role": role,
                                "source_record_sha256": source_digest,
                                "artifact_commit": artifact_commit,
                            }
                            for (
                                server_time,
                                artifact_id,
                                channel,
                                semantic,
                                source_digest,
                                artifact_commit,
                                role,
                            ) in sorted(artifact_bases)
                        ],
                        "provider_reactions": [
                            {
                                "created_at": created_at,
                                "id": reaction_id,
                                "parent_comment_id": parent_comment_id,
                                "content": content,
                            }
                            for (
                                created_at,
                                reaction_id,
                                parent_comment_id,
                                content,
                            ) in sorted(provider_reactions)
                        ],
                        "nonterminal_records": [
                            {
                                "channel": channel,
                                "id": record_id,
                                "server_time": server_time,
                                "source_record_sha256": source_digest,
                            }
                            for (
                                channel,
                                record_id,
                                server_time,
                                source_digest,
                            ) in sorted(nonterminal_records)
                        ],
                    }
                is_current_scope = parsed_scope == current_scope_key
                is_in_history_window = (
                    source_ordering_key is not None
                    and history_start_exclusive
                    < int(source_ordering_key[0])
                    <= history_as_of_server_time
                )
                classification = (
                    "current"
                    if is_current_scope
                    else (
                        "historical-candidate"
                        if is_in_history_window
                        else "confirmed-non-candidate"
                    )
                )
                scope_classifications.append(
                    {
                        "pull_number": pr,
                        "scope_key": list(parsed_scope),
                        "classification": classification,
                    }
                )
                if classification != "confirmed-non-candidate":
                    entries.append(entry)
            receipt_ids = (
                set(receipt_mapping)
                if isinstance(receipt_mapping, dict)
                else None
            )
            extra_only_current_audit = (
                allow_extra_request_scope_receipts_for_current_audit
                and request_receipt_closure_required
                and receipt_ids is not None
                and used_receipt_ids < receipt_ids
                and len(raw_scopes) == 1
                and isinstance(raw_scopes[0], dict)
                and raw_scopes[0].get("scope_key") == current_scope_key
                and not entries
            )
            if request_receipt_closure_required and (
                receipt_ids != used_receipt_ids
                and not extra_only_current_audit
            ):
                return None
            return {
                "entries": entries,
                "scope_discovery_projection": clone(
                    raw_dataset["scope_discovery_projection"]
                ),
                "scope_authority_audit": sorted(
                    scope_authority_audit,
                    key=lambda item: int(item["scope_key"][1]),
                ),
                "scope_classifications": sorted(
                    scope_classifications,
                    key=lambda item: int(item["pull_number"]),
                ),
            }

        def parse_discovery_endpoint_transcript(
            value: object,
            *,
            request_scope_receipts: object = None,
            provider_declaration: object = None,
            current_ancestry: dict[str, int] | None = None,
            current_legacy_short_commit_resolutions: dict[str, str] | None = None,
            require_current_ancestry_exact: bool = True,
            prefer_unresolved_thread_blocker: bool = False,
            _tightened_resource_limits: dict[str, int] | None = None,
            _monotonic_clock: object = time.monotonic,
            _single_scope_pull_number: int | None = None,
            _allow_post_as_of_requests: bool = False,
            _allow_post_as_of_artifacts: bool = False,
            _endpoint_plane_only: bool = False,
            _sidecar_blind_audit: bool = False,
            _allow_extra_request_scope_receipts_for_current_audit: bool = False,
            _inventory_validation_context: dict[str, object] | None = None,
            _memo_subject: object = None,
            _trusted_controlled_bindings: object = None,
        ) -> dict[str, object] | None:
            if (
                type(prefer_unresolved_thread_blocker) is not bool
                or type(require_current_ancestry_exact) is not bool
                or type(_allow_post_as_of_requests) is not bool
                or type(_allow_post_as_of_artifacts) is not bool
                or type(_endpoint_plane_only) is not bool
                or type(_sidecar_blind_audit) is not bool
                or type(
                    _allow_extra_request_scope_receipts_for_current_audit
                )
                is not bool
                or (
                    _trusted_controlled_bindings is not None
                    and not isinstance(_trusted_controlled_bindings, dict)
                )
                or (_sidecar_blind_audit and not _endpoint_plane_only)
                or (
                    _allow_extra_request_scope_receipts_for_current_audit
                    and (
                        _single_scope_pull_number != current_pr
                        or _allow_post_as_of_requests is not True
                        or not isinstance(current_ancestry, dict)
                        or _endpoint_plane_only
                        or _sidecar_blind_audit
                    )
                )
            ):
                return None
            inventory_context = _inventory_validation_context
            if inventory_context is None:
                return None
            inventory_parts = inventory_validation_context_parts(inventory_context)
            effective_limits = effective_resource_limits(_tightened_resource_limits)
            if (
                inventory_parts is None
                or effective_limits is None
                or not typed_json_equal(
                    inventory_parts[1].get("limits"), effective_limits
                )
            ):
                return None
            memo_subject = value
            memo_subject_mode = "complete-transcript"
            if _memo_subject is not None:
                scopes = value.get("scopes") if type(value) is dict else None
                scope_record = (
                    scopes[0]
                    if type(scopes) is list
                    and len(scopes) == 1
                    and type(scopes[0]) is dict
                    else None
                )
                if (
                    type(value) is not dict
                    or set(value)
                    != {"schema_version", "repository", "scope_discovery", "scopes"}
                    or type(value.get("schema_version")) is not int
                    or value.get("schema_version") != 4
                    or type(value.get("repository")) is not str
                    or value.get("repository") != current_repository
                    or type(_single_scope_pull_number) is not int
                    or _single_scope_pull_number <= 0
                    or value.get("scope_discovery") is not None
                    or scope_record is None
                    or set(scope_record) != {"pull_number", "fetches"}
                    or type(scope_record.get("pull_number")) is not int
                    or scope_record.get("pull_number") != _single_scope_pull_number
                    or type(scope_record.get("fetches")) is not list
                    or scope_record.get("fetches") is not _memo_subject
                ):
                    return None
                memo_subject = _memo_subject
                memo_subject_mode = "single-scope-fetches"
            trusted_controlled_binding_policy = None
            if _trusted_controlled_bindings is not None:
                if any(
                    type(comment_id) is not int or comment_id <= 0
                    for comment_id in _trusted_controlled_bindings
                ):
                    return None
                trusted_controlled_binding_policy = {
                    str(comment_id): _trusted_controlled_bindings[comment_id]
                    for comment_id in sorted(_trusted_controlled_bindings)
                }
            policy_binding = {
                "provider_declaration": provider_declaration,
                "current_ancestry": current_ancestry,
                "current_legacy_short_commit_resolutions": (
                    current_legacy_short_commit_resolutions
                ),
                "require_current_ancestry_exact": require_current_ancestry_exact,
                "history_start_exclusive": history_start_exclusive,
                "history_as_of_server_time": history_as_of_server_time,
                "single_scope_pull_number": _single_scope_pull_number,
                "allow_post_as_of_requests": _allow_post_as_of_requests,
                "allow_post_as_of_artifacts": _allow_post_as_of_artifacts,
                "resource_limits": effective_limits,
                "memo_subject_mode": memo_subject_mode,
                "trusted_controlled_bindings": (
                    trusted_controlled_binding_policy
                ),
            }
            policy_preflight = bounded_json_fingerprint_pass(
                policy_binding,
                resource_tracker=inventory_parts[1],
                calculate_digest=False,
            )
            if policy_preflight is None or policy_preflight[1] is not None:
                return None
            policy_fingerprint = bounded_json_fingerprint_pass(
                policy_binding,
                resource_tracker=inventory_parts[1],
                calculate_digest=True,
            )
            if (
                policy_fingerprint is None
                or policy_fingerprint[0] != policy_preflight[0]
                or not isinstance(policy_fingerprint[1], str)
            ):
                return None
            policy_digest = policy_fingerprint[1]
            raw_dataset = inventory_validation_memoized(
                inventory_context,
                namespace=f"raw_semantic_dataset_v1:{policy_digest}",
                inventory=memo_subject,
                producer=lambda: produce_raw_semantic_dataset(
                    value,
                    provider_declaration=provider_declaration,
                    current_ancestry=current_ancestry,
                    current_legacy_short_commit_resolutions=(
                        current_legacy_short_commit_resolutions
                    ),
                    require_current_ancestry_exact=(require_current_ancestry_exact),
                    _tightened_resource_limits=_tightened_resource_limits,
                    _monotonic_clock=_monotonic_clock,
                    _single_scope_pull_number=_single_scope_pull_number,
                    _allow_post_as_of_requests=_allow_post_as_of_requests,
                    _allow_post_as_of_artifacts=_allow_post_as_of_artifacts,
                    _inventory_validation_context=inventory_context,
                    _trusted_controlled_bindings=(
                        _trusted_controlled_bindings
                    ),
                ),
                budget_tracker=inventory_parts[1],
            )
            return project_raw_semantic_dataset(
                raw_dataset,
                request_scope_receipts=request_scope_receipts,
                current_ancestry=current_ancestry,
                prefer_unresolved_thread_blocker=prefer_unresolved_thread_blocker,
                allow_post_as_of_requests=_allow_post_as_of_requests,
                allow_extra_request_scope_receipts_for_current_audit=(
                    _allow_extra_request_scope_receipts_for_current_audit
                ),
                endpoint_plane_only=_endpoint_plane_only,
                sidecar_blind_audit=_sidecar_blind_audit,
                inventory_validation_context=inventory_context,
                trusted_controlled_bindings=_trusted_controlled_bindings,
            )

        def fixture_scope_classifications(
            raw_scopes: list[dict[str, object]],
            candidates: list[dict[str, object]],
        ) -> list[dict[str, object]]:
            candidate_scope_keys = {
                candidate_scope_key
                for candidate in candidates
                if (candidate_scope_key := scope_key(candidate)) is not None
            }
            classifications: list[dict[str, object]] = []
            for raw_scope in raw_scopes:
                raw_scope_key = scope_key(raw_scope)
                if raw_scope_key is None:
                    continue
                if raw_scope_key == current_scope_key:
                    classification = "current"
                elif raw_scope_key in candidate_scope_keys:
                    classification = "historical-candidate"
                else:
                    classification = "confirmed-non-candidate"
                classifications.append(
                    {
                        "pull_number": raw_scope_key[1],
                        "scope_key": list(raw_scope_key),
                        "classification": classification,
                    }
                )
            return sorted(
                classifications,
                key=lambda item: int(item["pull_number"]),
            )

        def universe_inventory(
            raw_scopes: list[dict[str, object]],
            candidates: list[dict[str, object]],
            *,
            provider_declaration: object = declaration,
            current_ancestry: dict[str, int] | None = None,
            _monotonic_clock: object = time.monotonic,
        ) -> dict[str, object]:
            inventory_context = new_inventory_validation_context(
                monotonic_clock=_monotonic_clock,
            )
            context_parts = inventory_validation_context_parts(inventory_context)
            if context_parts is None:
                raise EvidenceResourceBudgetExceeded(
                    "inventory resource trackers unavailable"
                )
            endpoint_tracker = context_parts[1]
            sidecar_tracker = context_parts[2]
            artifact_validation_context = context_parts[3]
            transcript = build_discovery_endpoint_transcript(
                raw_scopes,
                _resource_tracker=endpoint_tracker,
            )
            request_scope_receipts = request_scope_receipts_for_scopes(
                raw_scopes,
                _resource_tracker=sidecar_tracker,
            )
            projection = parse_discovery_endpoint_transcript(
                transcript,
                request_scope_receipts=request_scope_receipts,
                provider_declaration=provider_declaration,
                current_ancestry=current_ancestry,
                _inventory_validation_context=inventory_context,
            )
            scope_classifications = (
                clone(projection["scope_classifications"])
                if isinstance(projection, dict)
                and isinstance(projection.get("scope_classifications"), list)
                else fixture_scope_classifications(raw_scopes, candidates)
            )
            result = {
                "complete": True,
                "repository": current_repository,
                "resource_budget": clone(evidence_resource_budget_v1),
                "pagination": clone(required_universe_pagination),
                "discovery_endpoint_transcript": transcript,
                "request_scope_receipts": request_scope_receipts,
                "scope_discovery_projection": (
                    clone(projection["scope_discovery_projection"])
                    if isinstance(projection, dict)
                    else None
                ),
                "scope_classifications": scope_classifications,
                "entries": derived_inventory_entries(
                    candidates,
                    artifact_validation_context=artifact_validation_context,
                ),
            }
            if not inventory_validation_deadlines_hold(inventory_context):
                raise EvidenceResourceBudgetExceeded(
                    "inventory shared deadline exceeded"
                )
            return result

