        def artifact_receipt_identity(
            wrapper: object,
        ) -> tuple[str, int, str] | None:
            final_snapshot = (
                wrapper.get("final_snapshot")
                if isinstance(wrapper, dict)
                else None
            )
            if not isinstance(final_snapshot, dict):
                return None
            channel = final_snapshot.get("channel")
            artifact_id = final_snapshot.get("id")
            try:
                source_record_sha256 = hashlib.sha256(
                    canonical_raw_body(
                        artifact_source_bundle(final_snapshot)
                    ).encode("utf-8")
                ).hexdigest()
            except (TypeError, UnicodeEncodeError, ValueError):
                return None
            if (
                not isinstance(channel, str)
                or type(artifact_id) is not int
                or artifact_id <= 0
                or re.fullmatch(r"[0-9a-f]{64}", source_record_sha256) is None
            ):
                return None
            return (channel, artifact_id, source_record_sha256)

        def artifact_scope_receipt_sha256(wrapper: object) -> str | None:
            if not isinstance(wrapper, dict) or "artifact_scope_receipt" not in wrapper:
                return None
            try:
                receipt_utf8 = canonical_raw_body(
                    wrapper["artifact_scope_receipt"]
                )
            except (TypeError, UnicodeEncodeError, ValueError):
                return None
            return hashlib.sha256(receipt_utf8.encode("utf-8")).hexdigest()

        artifact_receipt_ledger_parent_binding_fields = {
            "kind",
            "canonical_ledger_payload_sha256",
            "exact_raw_endpoint_base_payload_sha256",
            "cutover_authority_binding",
            "sealed_pre_cutover_checkpoint_binding",
        }
        cutover_authority_parent_binding_fields = {
            "cutover_authority_id",
            "cutover_authority_revision",
            "cutover_authority_payload_sha256",
        }
        checkpoint_parent_binding_fields = {
            "checkpoint_id",
            "checkpoint_revision",
            "checkpoint_payload_sha256",
        }

        def artifact_receipt_ledger_parent_binding(
            *,
            ledger_sha256: str,
            endpoint_sha256: str,
            cutover_binding: tuple[str, int, str],
            checkpoint_binding: tuple[str, int, str] | None,
        ) -> dict[str, object]:
            return {
                "kind": (
                    "parent-recorded-artifact-scope-receipt-"
                    "disposition-binding-v1"
                ),
                "canonical_ledger_payload_sha256": ledger_sha256,
                "exact_raw_endpoint_base_payload_sha256": endpoint_sha256,
                "cutover_authority_binding": {
                    "cutover_authority_id": cutover_binding[0],
                    "cutover_authority_revision": cutover_binding[1],
                    "cutover_authority_payload_sha256": cutover_binding[2],
                },
                "sealed_pre_cutover_checkpoint_binding": (
                    None
                    if checkpoint_binding is None
                    else {
                        "checkpoint_id": checkpoint_binding[0],
                        "checkpoint_revision": checkpoint_binding[1],
                        "checkpoint_payload_sha256": checkpoint_binding[2],
                    }
                ),
            }

        def artifact_receipt_ledger_parent_binding_is_closed(
            value: object,
        ) -> bool:
            if (
                not isinstance(value, dict)
                or set(value) != artifact_receipt_ledger_parent_binding_fields
                or value.get("kind")
                != (
                    "parent-recorded-artifact-scope-receipt-"
                    "disposition-binding-v1"
                )
            ):
                return False
            for field in (
                "canonical_ledger_payload_sha256",
                "exact_raw_endpoint_base_payload_sha256",
            ):
                digest = value.get(field)
                if (
                    not isinstance(digest, str)
                    or re.fullmatch(r"[0-9a-f]{64}", digest) is None
                ):
                    return False
            cutover_binding = value.get("cutover_authority_binding")
            if (
                not isinstance(cutover_binding, dict)
                or set(cutover_binding)
                != cutover_authority_parent_binding_fields
                or not isinstance(
                    cutover_binding.get("cutover_authority_id"), str
                )
                or not cutover_binding["cutover_authority_id"]
                or type(cutover_binding.get("cutover_authority_revision"))
                is not int
                or not (
                    0
                    < cutover_binding["cutover_authority_revision"]
                    <= 9_007_199_254_740_991
                )
                or not isinstance(
                    cutover_binding.get("cutover_authority_payload_sha256"),
                    str,
                )
                or re.fullmatch(
                    r"[0-9a-f]{64}",
                    cutover_binding["cutover_authority_payload_sha256"],
                )
                is None
            ):
                return False
            checkpoint_binding = value.get(
                "sealed_pre_cutover_checkpoint_binding"
            )
            if checkpoint_binding is None:
                return True
            return (
                isinstance(checkpoint_binding, dict)
                and set(checkpoint_binding) == checkpoint_parent_binding_fields
                and isinstance(checkpoint_binding.get("checkpoint_id"), str)
                and bool(checkpoint_binding["checkpoint_id"])
                and type(checkpoint_binding.get("checkpoint_revision")) is int
                and (
                    0
                    < checkpoint_binding["checkpoint_revision"]
                    <= 9_007_199_254_740_991
                )
                and isinstance(
                    checkpoint_binding.get("checkpoint_payload_sha256"), str
                )
                and re.fullmatch(
                    r"[0-9a-f]{64}",
                    checkpoint_binding["checkpoint_payload_sha256"],
                )
                is not None
            )

        def trust_artifact_receipt_ledger_parent_binding(
            binding: object,
        ) -> bool:
            if not artifact_receipt_ledger_parent_binding_is_closed(binding):
                return False
            assert isinstance(binding, dict)
            key = (
                str(binding["canonical_ledger_payload_sha256"]),
                str(binding["exact_raw_endpoint_base_payload_sha256"]),
            )
            existing = _trusted_artifact_receipt_ledger_bindings.get(key)
            if existing is not None and not typed_json_equal(existing, binding):
                return False
            _trusted_artifact_receipt_ledger_bindings[key] = clone(binding)
            return True

