        def trust_direct_disposition_ledger(
            ledger: dict[str, object],
            endpoint_base_payload: dict[str, object],
            *,
            cutover_binding: tuple[str, int, str],
            checkpoint_binding: tuple[str, int, str] | None,
        ) -> dict[str, object]:
            parent_binding = artifact_receipt_ledger_parent_binding(
                ledger_sha256=hashlib.sha256(
                    canonical_raw_body(ledger).encode("utf-8")
                ).hexdigest(),
                endpoint_sha256=hashlib.sha256(
                    canonical_raw_body(endpoint_base_payload).encode("utf-8")
                ).hexdigest(),
                cutover_binding=cutover_binding,
                checkpoint_binding=checkpoint_binding,
            )
            self.assertTrue(
                artifact_receipt_ledger_parent_binding_is_closed(
                    parent_binding
                )
            )
            self.assertTrue(
                trust_artifact_receipt_ledger_parent_binding(parent_binding)
            )
            return parent_binding

