        def remove_reaction_basis_field(value: dict[str, object]) -> None:
            basis = value["candidate_basis"]
            assert isinstance(basis, dict)
            basis.pop("server_time")

        def extend_reaction_basis(value: dict[str, object]) -> None:
            basis = value["candidate_basis"]
            assert isinstance(basis, dict)
            basis["authority_override"] = True

        def set_boolean_reaction_time(value: dict[str, object]) -> None:
            basis = value["candidate_basis"]
            assert isinstance(basis, dict)
            basis["server_time"] = True

        def drift_reaction_time(value: dict[str, object]) -> None:
            basis = value["candidate_basis"]
            assert isinstance(basis, dict)
            basis["server_time"] = int(basis["server_time"]) + 1

        def drift_reaction_identity(value: dict[str, object]) -> None:
            basis = value["candidate_basis"]
            assert isinstance(basis, dict)
            basis["stable_artifact_id"] = int(basis["stable_artifact_id"]) + 1

        malformed_reaction_basis_mutations: dict[
            str, Callable[[dict[str, object]], None]
        ] = {
            "missing-basis": lambda value: value.pop("candidate_basis"),
            "null-basis": lambda value: value.update({"candidate_basis": None}),
            "non-object-basis": lambda value: value.update(
                {"candidate_basis": []}
            ),
            "missing-basis-field": remove_reaction_basis_field,
            "additional-basis-field": extend_reaction_basis,
            "boolean-reaction-time": set_boolean_reaction_time,
            "reaction-time-drift": drift_reaction_time,
            "reaction-identity-drift": drift_reaction_identity,
        }
