        def receipt_bound_invalid_state_artifact(
            artifact_id: int,
            state: object,
            *,
            body: str,
            child_actor: tuple[str, str] | None = None,
            exact_provider_child: bool = False,
            record: dict[str, object] | None = None,
            server_time: int | None = None,
        ) -> dict[str, object]:
            if child_actor is not None and exact_provider_child:
                raise AssertionError("invalid mixed child fixture")
            artifact_record = terminal_current if record is None else record
            artifact_server_time = (
                int(terminal_server_time) - 10
                if server_time is None
                else server_time
            )
            artifact = complete_review_artifact(
                artifact_record,
                artifact_id,
                artifact_server_time,
                artifact_kind=(
                    "unresolved-thread-finding"
                    if exact_provider_child
                    else "malformed-terminal-artifact"
                ),
                outcome="findings" if exact_provider_child else "malformed",
            )
            final_snapshot = artifact["final_snapshot"]
            assert isinstance(final_snapshot, dict)
            final_snapshot["artifact_kind"] = "malformed-terminal-artifact"
            final_snapshot["outcome"] = "malformed"
            final_snapshot["grammar_status"] = "malformed"
            final_snapshot["state"] = state
            final_snapshot["body"] = body
            final_snapshot["normalized_body"] = body
            if child_actor is not None:
                child_login, child_type = child_actor
                associated = final_snapshot["associated_inline_comments"]
                assert isinstance(associated, dict)
                associated["records"] = [
                    {
                        "id": artifact_id * 10,
                        "url": (
                            f"https://github.com/{current_repository}/pull/"
                            f"{artifact_record['scope']['pr']}"
                            f"#discussion_r{artifact_id * 10}"
                        ),
                        "user_login": child_login,
                        "user_type": child_type,
                        "pull_request_review_id": artifact_id,
                        "commit_id": artifact_record["scope"]["head"],
                        "original_commit_id": artifact_record["scope"]["head"],
                        "body": "Different-actor side discussion",
                        "normalized_body": "Different-actor side discussion",
                    }
                ]
            artifact["initial_snapshot"] = clone(final_snapshot)
            artifact["artifact_scope_receipt"] = artifact_scope_receipt(
                final_snapshot
            )
            return artifact

