        def lane_timing(
            codex_terminal_monotonic_ns: object,
            claude_terminal_monotonic_ns: object,
            *,
            pre_post_request_ids: list[int] | None = None,
            capture_started_monotonic_ns: object = None,
        ) -> dict[str, object]:
            if pre_post_request_ids is None:
                pre_post_request_ids = []
            latest_terminal = (
                max(
                    codex_terminal_monotonic_ns,
                    claude_terminal_monotonic_ns,
                )
                if type(codex_terminal_monotonic_ns) is int
                and type(claude_terminal_monotonic_ns) is int
                else 0
            )
            if capture_started_monotonic_ns is None:
                capture_started_monotonic_ns = latest_terminal + 1
            raw_response_body = json.dumps(
                [{"id": request_id} for request_id in pre_post_request_ids],
                ensure_ascii=False,
                separators=(",", ":"),
                sort_keys=True,
            )
            snapshot = {
                "clock_domains": {
                    "local_lane_terminal": "monotonic-nanoseconds",
                    "github_capture": (
                        "authenticated-http-date-rfc3339-seconds"
                    ),
                },
                "codex_terminal_monotonic_ns": (
                    codex_terminal_monotonic_ns
                ),
                "claude_terminal_monotonic_ns": (
                    claude_terminal_monotonic_ns
                ),
                "pre_post_absence_capture": {
                    "kind": (
                        "github-codex-pre-post-request-"
                        "absence-capture-v1"
                    ),
                    "clock_domain": (
                        "authenticated-http-date-rfc3339-seconds"
                    ),
                    "capture_started_monotonic_ns": (
                        capture_started_monotonic_ns
                    ),
                    "capture_finished_monotonic_ns": (
                        capture_started_monotonic_ns
                        if type(capture_started_monotonic_ns) is int
                        else 0
                    ),
                    "request_url": (
                        f"https://api.github.com/repos/{current_repository}/"
                        f"issues/{current_pr}/comments?per_page=100&page=1"
                    ),
                    "http_status": 200,
                    "authenticated_operating_identity": (
                        "fixture-authenticated-github-session"
                    ),
                    "http_date": "2027-01-15T08:00:00Z",
                    "link_header": None,
                    "pagination_complete": True,
                    "review_epoch_scope": clone(current["scope"]),
                    "request_native_ids": clone(pre_post_request_ids),
                    "raw_response_body_utf8": raw_response_body,
                    "raw_response_body_sha256": hashlib.sha256(
                        raw_response_body.encode("utf-8")
                    ).hexdigest(),
                },
            }
            return {
                "initial_snapshot": clone(snapshot),
                "final_snapshot": clone(snapshot),
            }

