        def raw_inline_records_for_current_scope(
            producer_name: str,
            producer_inventory: dict[str, object],
        ) -> list[dict[str, object]]:
            if producer_name == "current":
                fetches = producer_inventory.get("fetches")
            else:
                transcript = producer_inventory.get(
                    "discovery_endpoint_transcript"
                )
                self.assertIsInstance(transcript, dict)
                scopes = transcript.get("scopes")
                self.assertIsInstance(scopes, list)
                current_scopes = [
                    scope
                    for scope in scopes
                    if isinstance(scope, dict)
                    and scope.get("pull_number") == current_scope_key[1]
                ]
                self.assertEqual(len(current_scopes), 1)
                fetches = current_scopes[0].get("fetches")
            self.assertIsInstance(fetches, list)
            records: list[dict[str, object]] = []
            for fetch in fetches:
                if not isinstance(fetch, dict) or fetch.get("kind") != (
                    "inline_comments"
                ):
                    continue
                pages = fetch.get("pages")
                self.assertIsInstance(pages, list)
                for page in pages:
                    self.assertIsInstance(page, dict)
                    raw_records = strict_json_loads(page.get("body_utf8"))
                    self.assertIsInstance(raw_records, list)
                    records.extend(
                        record
                        for record in raw_records
                        if isinstance(record, dict)
                    )
            return records

