        def assert_registered_stage_chain_rejected(
            *,
            admission: dict[str, object],
            trusted_binding: dict[str, object],
            replacement_chain: list[dict[str, object]] | None = None,
            membership_mutation: tuple[str, str, object] | None = None,
        ) -> None:
            store_key = (
                trusted_binding["store_id"],
                trusted_binding["store_revision"],
                trusted_binding["store_entry_index"],
            )
            original_raw_utf8 = _parent_formal_scope_authority_ledger.get(
                store_key
            )
            if not isinstance(original_raw_utf8, str):
                raise AssertionError("authority mutation requires parent bytes")
            mutated_entry = strict_json_loads(original_raw_utf8)
            if not isinstance(mutated_entry, dict):
                raise AssertionError("authority mutation requires an entry")
            mutated_context = mutated_entry.get("authority_context")
            if not isinstance(mutated_context, dict):
                raise AssertionError("authority mutation requires context")
            chain = clone(mutated_entry.get("stage_memberships"))
            if not isinstance(chain, list) or not chain:
                raise AssertionError("authority mutation requires a stage chain")
            if replacement_chain is not None:
                chain = clone(replacement_chain)
            elif membership_mutation is not None:
                action, field, value = membership_mutation
                first_membership = chain[0]
                if not isinstance(first_membership, dict):
                    raise AssertionError("stage mutation requires membership")
                if action == "missing":
                    first_membership.pop(field)
                elif action in {"extra", "replace"}:
                    first_membership[field] = value
                else:
                    raise AssertionError("unknown stage membership mutation")
            mutated_context["parent_persistence_chain"] = clone(chain)
            mutated_context_raw_utf8 = canonical_raw_body(mutated_context)
            mutated_entry["authority_context"] = mutated_context
            mutated_entry["authority_context_raw_utf8"] = (
                mutated_context_raw_utf8
            )
            mutated_entry["authority_context_sha256"] = hashlib.sha256(
                mutated_context_raw_utf8.encode("utf-8")
            ).hexdigest()
            mutated_entry["stage_memberships"] = clone(chain)
            mutated_raw_utf8 = canonical_raw_body(mutated_entry)
            mutated_binding = clone(trusted_binding)
            mutated_binding["entry_sha256"] = hashlib.sha256(
                mutated_raw_utf8.encode("utf-8")
            ).hexdigest()
            mutated_binding["readback_identity_sha256"] = mutated_binding[
                "entry_sha256"
            ]
            mutated_binding["authority_context_sha256"] = mutated_entry[
                "authority_context_sha256"
            ]
            _parent_formal_scope_authority_ledger[store_key] = mutated_raw_utf8
            try:
                self.assertIsNone(
                    expected_report_from_inputs(
                        "accepted-terminal-clean",
                        declaration,
                        scope_admission_history,
                        terminal_current,
                        normal_lane_timing,
                        formal_scope_admission=admission,
                        formal_scope_authority_context=mutated_binding,
                        base_retarget_event=no_base_retarget_event,
                    )
                )
            finally:
                _parent_formal_scope_authority_ledger[store_key] = (
                    original_raw_utf8
                )

        def assert_registered_stage_receipt_rejected(
            *,
            admission: dict[str, object],
            trusted_binding: dict[str, object],
            stage_index: int,
            mutation: str,
        ) -> None:
            authority_readback = read_parent_formal_scope_ledger_entry(
                trusted_binding
            )
            authority_entry = (
                authority_readback.get("entry")
                if isinstance(authority_readback, dict)
                else None
            )
            chain = (
                clone(authority_entry.get("stage_memberships"))
                if isinstance(authority_entry, dict)
                else None
            )
            if not isinstance(chain, list) or not (
                0 <= stage_index < len(chain)
            ):
                raise AssertionError("stage receipt mutation requires a chain")
            membership = chain[stage_index]
            if not isinstance(membership, dict):
                raise AssertionError("stage receipt mutation requires membership")
            stage_store_key = (
                membership["store_id"],
                membership["store_revision"],
                membership["store_entry_index"],
            )
            original_stage_raw_utf8 = (
                _parent_formal_scope_authority_ledger.get(stage_store_key)
            )
            if not isinstance(original_stage_raw_utf8, str):
                raise AssertionError("stage receipt mutation requires parent bytes")
            stage_entry = strict_json_loads(original_stage_raw_utf8)
            if not isinstance(stage_entry, dict):
                raise AssertionError("stage receipt mutation requires an entry")
            stage_receipt = stage_entry.get("receipt")
            if not isinstance(stage_receipt, dict):
                raise AssertionError("stage receipt mutation requires a receipt")
            append_transaction = stage_entry.get("append_transaction")
            if not isinstance(append_transaction, dict):
                raise AssertionError(
                    "stage receipt mutation requires append transaction"
                )
            if mutation == "wrong-revision":
                stage_receipt["parent_ledger_revision"] = (
                    membership["store_revision"] + 1
                )
            elif mutation == "wrong-index":
                stage_receipt["parent_ledger_entry_index"] = (
                    membership["store_entry_index"] + 1
                )
            elif mutation == "wrong-store":
                stage_receipt["parent_ledger_store_id"] = (
                    "wrong-parent-formal-scope-ledger"
                )
            elif mutation == "late-append-old-self-report":
                if stage_index == 0 or not isinstance(chain[stage_index - 1], dict):
                    raise AssertionError("old self-report requires a prior stage")
                prior_membership = chain[stage_index - 1]
                stage_receipt["parent_ledger_revision"] = prior_membership[
                    "store_revision"
                ]
                stage_receipt["parent_ledger_entry_index"] = prior_membership[
                    "store_entry_index"
                ]
            elif mutation == "raw-parsed-mismatch":
                mismatched_receipt = clone(stage_receipt)
                mismatched_receipt["http_status"] = 201
                stage_entry["receipt_raw_utf8"] = canonical_raw_body(
                    mismatched_receipt
                )
            elif mutation == "duplicate-key-receipt-raw":
                canonical_receipt = canonical_raw_body(stage_receipt)
                stage_entry["receipt_raw_utf8"] = (
                    canonical_receipt[:-1]
                    + ',"kind":"formal-scope-authenticated-parent-persistence-date-receipt-v1"}'
                )
            elif mutation == "wrong-receipt-digest":
                stage_entry["receipt_sha256"] = "f" * 64
            elif mutation in {
                "transaction-wrong-store",
                "transaction-wrong-revision",
                "transaction-wrong-index",
            }:
                transaction_field, transaction_value = {
                    "transaction-wrong-store": (
                        "store_id",
                        "wrong-parent-formal-scope-ledger",
                    ),
                    "transaction-wrong-revision": (
                        "store_revision",
                        membership["store_revision"] + 1,
                    ),
                    "transaction-wrong-index": (
                        "store_entry_index",
                        membership["store_entry_index"] + 1,
                    ),
                }[mutation]
                append_transaction[transaction_field] = transaction_value
                stage_entry["append_transaction"] = append_transaction
                stage_entry["append_transaction_raw_utf8"] = (
                    canonical_raw_body(append_transaction)
                )
                transaction_digest = hashlib.sha256(
                    stage_entry["append_transaction_raw_utf8"].encode("utf-8")
                ).hexdigest()
                stage_entry["append_transaction_sha256"] = transaction_digest
                membership["append_transaction_sha256"] = transaction_digest
                stage_receipt["append_transaction_sha256"] = transaction_digest
            elif mutation == "transaction-raw-parsed-mismatch":
                mismatched_transaction = clone(append_transaction)
                mismatched_transaction["stage"] = "forged-stage"
                stage_entry["append_transaction_raw_utf8"] = (
                    canonical_raw_body(mismatched_transaction)
                )
                transaction_digest = hashlib.sha256(
                    stage_entry["append_transaction_raw_utf8"].encode("utf-8")
                ).hexdigest()
                stage_entry["append_transaction_sha256"] = transaction_digest
                membership["append_transaction_sha256"] = transaction_digest
                stage_receipt["append_transaction_sha256"] = transaction_digest
            elif mutation == "transaction-duplicate-key-raw":
                canonical_transaction = canonical_raw_body(append_transaction)
                stage_entry["append_transaction_raw_utf8"] = (
                    canonical_transaction[:-1]
                    + ',"kind":"formal-scope-parent-stage-append-transaction-v1"}'
                )
                transaction_digest = hashlib.sha256(
                    stage_entry["append_transaction_raw_utf8"].encode("utf-8")
                ).hexdigest()
                stage_entry["append_transaction_sha256"] = transaction_digest
                membership["append_transaction_sha256"] = transaction_digest
                stage_receipt["append_transaction_sha256"] = transaction_digest
            elif mutation == "transaction-wrong-digest":
                stage_entry["append_transaction_sha256"] = "e" * 64
                membership["append_transaction_sha256"] = "e" * 64
                stage_receipt["append_transaction_sha256"] = "e" * 64
            else:
                raise AssertionError("unknown stage receipt mutation")
            if mutation not in {
                "raw-parsed-mismatch",
                "duplicate-key-receipt-raw",
                "wrong-receipt-digest",
            }:
                stage_entry["receipt"] = stage_receipt
                stage_entry["receipt_raw_utf8"] = canonical_raw_body(
                    stage_receipt
                )
                stage_entry["receipt_sha256"] = hashlib.sha256(
                    stage_entry["receipt_raw_utf8"].encode("utf-8")
                ).hexdigest()
            elif mutation in {
                "raw-parsed-mismatch",
                "duplicate-key-receipt-raw",
            }:
                stage_entry["receipt_sha256"] = hashlib.sha256(
                    stage_entry["receipt_raw_utf8"].encode("utf-8")
                ).hexdigest()
            mutated_stage_raw_utf8 = canonical_raw_body(stage_entry)
            mutated_stage_digest = hashlib.sha256(
                mutated_stage_raw_utf8.encode("utf-8")
            ).hexdigest()
            membership["entry_sha256"] = mutated_stage_digest
            membership["readback_identity_sha256"] = mutated_stage_digest
            _parent_formal_scope_authority_ledger[
                stage_store_key
            ] = mutated_stage_raw_utf8
            try:
                assert_registered_stage_chain_rejected(
                    admission=admission,
                    trusted_binding=trusted_binding,
                    replacement_chain=chain,
                )
            finally:
                _parent_formal_scope_authority_ledger[
                    stage_store_key
                ] = original_stage_raw_utf8

