        def activate_base_retarget_snapshot(classification: str) -> None:
            nonlocal trusted_base_retarget_classification_head_identity
            snapshot_records, snapshot_head = (
                retarget_activity_snapshots[classification]
            )
            trusted_base_retarget_classification_records[:] = clone(
                snapshot_records
            )
            trusted_base_retarget_classification_head_identity = snapshot_head

