        def reseal_base_retarget_evidence(
            record: dict[str, object],
        ) -> dict[str, object]:
            digest_input = {
                key: value
                for key, value in record.items()
                if key != "evidence_sha256"
            }
            record["evidence_sha256"] = hashlib.sha256(
                canonical_raw_body(digest_input).encode("utf-8")
            ).hexdigest()
            return record

