        def reseal_automatic_admission(
            admission: dict[str, object],
        ) -> None:
            preliminary = admission["preliminary_admission"]
            finalization = admission["finalization_binding"]
            fence = admission["post_finalization_date_fence_receipt"]
            assert isinstance(preliminary, dict)
            assert isinstance(finalization, dict)
            assert isinstance(fence, dict)
            payload = preliminary["payload"]
            assert isinstance(payload, dict)
            preliminary["payload_utf8"] = canonical_raw_body(payload)
            preliminary_sha256 = hashlib.sha256(
                preliminary["payload_utf8"].encode("utf-8")
            ).hexdigest()
            preliminary["payload_sha256"] = preliminary_sha256
            finalization["preliminary_payload_sha256"] = preliminary_sha256
            finalization["source_event_sha256"] = payload[
                "source_event_sha256"
            ]
            finalization["source_event_registry_membership"] = clone(
                payload["source_event_registry_membership"]
            )
            fence["preliminary_payload_sha256"] = preliminary_sha256

