        def history_with_unmatched_raw_request_scope_receipt(
            candidates: list[dict[str, object]],
            current_record: dict[str, object],
            *,
            request_id: int,
        ) -> dict[str, object]:
            unmatched_history = history(
                candidates,
                current_raw=current_record,
            )
            unmatched_request = request(
                request_id,
                history_as_of_server_time + 1,
                pr=current_pr,
            )
            current_scope = current_record.get("scope")
            if not isinstance(current_scope, dict):
                raise AssertionError("current scope is unavailable")
            unmatched_receipt = request_scope_receipt(
                unmatched_request,
                current_scope,
            )
            for phase in ("initial", "final"):
                raw_inventory = unmatched_history[
                    f"{phase}_current_raw_inventory"
                ]
                if not isinstance(raw_inventory, dict):
                    raise AssertionError("raw inventory is unavailable")
                raw_receipts = raw_inventory.get("request_scope_receipts")
                if not isinstance(raw_receipts, list):
                    raise AssertionError("raw request receipts are unavailable")
                raw_receipts.append(clone(unmatched_receipt))
            if not reissue_current_inventory_capture_chain(unmatched_history):
                raise AssertionError("raw inventory capture chain reissue failed")
            return unmatched_history

