    def test_github_codex_router_sections_stay_within_prompt_budgets(
        self,
    ) -> None:
        def section_bytes(
            path: pathlib.Path,
            start_heading: bytes,
            end_heading: bytes,
        ) -> bytes:
            raw = path.read_bytes()
            self.assertEqual(raw.count(start_heading), 1, str(path))
            self.assertEqual(raw.count(end_heading), 1, str(path))
            start = raw.index(start_heading)
            end = raw.index(end_heading)
            self.assertLess(start, end, str(path))
            return raw[start:end]

        interface_path = SKILL_ROOT / "agents/openai.yaml"
        self.assertLessEqual(len(interface_path.read_bytes()), 12_288)

        skill_github = section_bytes(
            SKILL_ROOT / "SKILL.md",
            b"## GitHub Codex Lane\n",
            b"## Workflow\n",
        )
        self.assertLessEqual(len(skill_github), 12_288)

        if CI_PROFILE == "canonical":
            readme_named_review = section_bytes(
                REPO_ROOT / "README.md",
                b"## Named Review At A Glance\n",
                b"## Low-Level `isolated_review` Helper Only\n",
            )
            self.assertLessEqual(len(readme_named_review), 8_192)

    def test_github_codex_lifecycle_first_router_order_is_stable(
        self,
    ) -> None:
        def assert_order(
            content: str,
            anchors: tuple[str, ...],
            *,
            document: str,
        ) -> None:
            positions: list[int] = []
            for anchor in anchors:
                with self.subTest(document=document, ordered_anchor=anchor):
                    self.assertIn(anchor, content)
                    positions.append(content.index(anchor))
            self.assertEqual(positions, sorted(positions), document)

        skill = (SKILL_ROOT / "SKILL.md").read_text(encoding="utf-8")
        workflow = skill.split("## Workflow\n", 1)[1].split(
            "\n## Egress Consent", 1
        )[0]
        self.assertIn(
            "If the request is explicit-range-only single or double, skip PR selection and continue at step 5.",
            workflow,
        )
        assert_order(
            workflow,
            (
                "1. Preserve the caller's explicit committed range",
                "2. For PR-specific or triple work",
                "3. Classify selected-PR lifecycle first.",
                "4. Read base ref name/tip and head",
                "5. Freeze the exact range.",
                "6. Launch the requested local lanes",
                "7. If triple remains eligible",
                "9. Only with explicit delivery or PR-orchestration authorization",
                "10. Report exact range",
            ),
            document="SKILL Workflow",
        )

        readiness = (SKILL_ROOT / "references/pr-readiness.md").read_text(
            encoding="utf-8"
        )
        gate_order = readiness.split("## Gate Order\n", 1)[1].split(
            "\n## Effective Review Shape", 1
        )[0]
        self.assertIn(
            "Explicit-range-only single or double review bypasses all selected-PR gates.",
            gate_order,
        )
        assert_order(
            gate_order,
            (
                "1. Preserve the caller's explicit committed `base_sha..head_sha`",
                "2. Select an explicitly named PR",
                "3. Classify selected-PR lifecycle first.",
                "4. Only after lifecycle passes",
                "5. Apply the canonical base-only-retarget machine before generic scope mismatch.",
                "6. Freeze the range",
                "7. For an eligible triple",
                "8. Require canonical current-head Action-status `PASS`, then run local delivery gates",
                "9. Report merge-ready",
            ),
            document="PR Readiness Gate Order",
        )

        interface = (SKILL_ROOT / "agents/openai.yaml").read_text(
            encoding="utf-8"
        )
        self.assertIn(
            "Explicit-range-only single or double review requires no PR probe.",
            interface,
        )
        assert_order(
            interface,
            (
                "Preserve an explicit caller base_sha..head_sha independently from PR selection.",
                "For every selected PR, classify lifecycle before reading scope for lane consumption",
                "Only after lifecycle passes, read baseRefName, baseRefOid, and headRefOid",
                "Single is exactly one fresh-context Codex reviewer",
                "One GitHub lane is one immutable review epoch.",
                "Readiness requires canonical current-head Action-status PASS plus all other current-head CI",
            ),
            document="OpenAI Interface",
        )

        if CI_PROFILE == "canonical":
            readme = (REPO_ROOT / "README.md").read_text(encoding="utf-8")
            named_review = readme.split(
                "## Named Review At A Glance\n", 1
            )[1].split("\n## Low-Level `isolated_review` Helper Only", 1)[0]
            self.assertIn(
                "Explicit-range-only single or double review needs no PR.",
                named_review,
            )
            assert_order(
                named_review,
                (
                    "Preserve an explicit caller range independently from PR selection.",
                    "For a selected PR, classify lifecycle first",
                    "only then derive base/head/merge-base scope",
                    "Local named lanes share one committed range",
                    "One GitHub review epoch",
                    "PR readiness is a separate current-head delivery gate",
                ),
                document="README Named Review",
            )

        authority = (
            SKILL_ROOT / "references/github-codex-evidence-authority.md"
        ).read_text(encoding="utf-8")
        self.assertIn(
            "`base_ref_oid` and `pr_merge_base` are independently authenticated and may be byte-equal or different; neither substitutes for the other.",
            authority,
        )
        current_contract_boundary = "\n## Current v41/v23 invariants"
        self.assertIn(current_contract_boundary, authority)
        ownership_parts = authority.split("## Ownership And Load Order\n", 1)
        self.assertEqual(len(ownership_parts), 2)
        current_contract_parts = ownership_parts[1].split(
            current_contract_boundary,
            1,
        )
        self.assertEqual(len(current_contract_parts), 2)
        ownership = current_contract_parts[0]
        normalized_ownership = " ".join(ownership.split())
        assert_order(
            normalized_ownership,
            (
                "Load this authority first, then the review-epoch machine.",
                "Load the retarget machine only for a same-head base-only retarget",
                "[GitHub PR probes](github-pr-probes.md)",
                "[PR readiness](pr-readiness.md)",
            ),
            document="Provider Authority Load Order",
        )

