        def canonical_bytes(value: object) -> bytes:
            return json.dumps(
                value,
                ensure_ascii=False,
                allow_nan=False,
                sort_keys=True,
                separators=(",", ":"),
            ).encode("utf-8")

        def retarget_strict_json_loads(raw: object) -> object:
            if isinstance(raw, bytes):
                text = raw.decode("utf-8", errors="strict")
            elif isinstance(raw, str):
                text = raw
                text.encode("utf-8", errors="strict")
            else:
                raise ValueError("retarget parent readback must be UTF-8 text")

            def reject_duplicate_keys(
                pairs: list[tuple[str, object]],
            ) -> dict[str, object]:
                parsed: dict[str, object] = {}
                for key, value in pairs:
                    if key in parsed:
                        raise ValueError("duplicate retarget parent-readback key")
                    parsed[key] = value
                return parsed

            def reject_constant(value: str) -> object:
                raise ValueError(f"nonstandard retarget JSON constant: {value}")

            def parse_finite_float(value: str) -> float:
                parsed_float = float(value)
                if not math.isfinite(parsed_float):
                    raise ValueError("non-finite retarget JSON number")
                return parsed_float

            parsed = json.loads(
                text,
                object_pairs_hook=reject_duplicate_keys,
                parse_constant=reject_constant,
                parse_float=parse_finite_float,
            )
            stack = [parsed]
            while stack:
                item = stack.pop()
                if isinstance(item, dict):
                    stack.extend(item.keys())
                    stack.extend(item.values())
                elif isinstance(item, list):
                    stack.extend(item)
                elif isinstance(item, str):
                    item.encode("utf-8", errors="strict")
                elif isinstance(item, float) and not math.isfinite(item):
                    raise ValueError("non-finite decoded retarget JSON number")
            return parsed

        def retarget_exact_oid(value: object) -> bool:
            return (
                type(value) is str
                and re.fullmatch(r"[0-9a-f]{40}", value) is not None
            )

        def retarget_exact_sha256(value: object) -> bool:
            return (
                type(value) is str
                and re.fullmatch(r"[0-9a-f]{64}", value) is not None
            )

        def retarget_review_epoch_scalars_are_exact(
            epoch: object,
        ) -> bool:
            return (
                isinstance(epoch, dict)
                and set(epoch)
                == {
                    "repository_id",
                    "repository_full_name",
                    "pull_request_number",
                    "pr_merge_base",
                    "head_sha",
                }
                and type(epoch.get("repository_id")) is int
                and epoch["repository_id"] > 0
                and type(epoch.get("repository_full_name")) is str
                and bool(epoch["repository_full_name"])
                and type(epoch.get("pull_request_number")) is int
                and epoch["pull_request_number"] > 0
                and retarget_exact_oid(epoch.get("pr_merge_base"))
                and retarget_exact_oid(epoch.get("head_sha"))
            )

