        def resealed_semantic_variant_is_valid(
            mutation: Callable[
                [
                    dict[str, object],
                    dict[str, object],
                    dict[str, object],
                    dict[str, object],
                    dict[str, object],
                    dict[str, object],
                ],
                None,
            ],
        ) -> bool:
            candidate_record = copy.deepcopy(supersession_record)
            candidate_classification = copy.deepcopy(
                future_none_classification
            )
            candidate_prior_origin = copy.deepcopy(prior_origin)
            candidate_current_scope = copy.deepcopy(current_pr_scope)
            candidate_new_origin_reservation = copy.deepcopy(
                new_origin_reservation
            )
            candidate_new_origin = copy.deepcopy(new_origin)
            candidate_transition = copy.deepcopy(authorized_transition)
            mutation(
                candidate_record,
                candidate_classification,
                candidate_prior_origin,
                candidate_current_scope,
                candidate_new_origin,
                candidate_transition,
            )
            candidate_prior_origin_sha256 = hashlib.sha256(
                canonical_bytes(candidate_prior_origin)
            ).hexdigest()
            candidate_classification["prior_origin_sha256"] = (
                candidate_prior_origin_sha256
            )
            candidate_classification["evidence_sha256"] = hashlib.sha256(
                canonical_bytes(
                    {
                        field: candidate_classification[field]
                        for field in evidence_digest_preimage_fields
                    }
                )
            ).hexdigest()
            candidate_record.update(
                {
                    "prior_origin_sha256": candidate_prior_origin_sha256,
                    "classification_id": candidate_classification[
                        "classification_id"
                    ],
                    "classification_evidence_sha256": (
                        candidate_classification["evidence_sha256"]
                    ),
                    "authenticated_current_pr_scope_sha256": (
                        hashlib.sha256(
                            canonical_bytes(candidate_current_scope)
                        ).hexdigest()
                    ),
                    "authorized_range_transition_sha256": (
                        hashlib.sha256(
                            canonical_bytes(candidate_transition)
                        ).hexdigest()
                    ),
                    "new_origin_reservation_sha256": hashlib.sha256(
                        canonical_bytes(candidate_new_origin_reservation)
                    ).hexdigest(),
                    "new_origin_sha256": hashlib.sha256(
                        canonical_bytes(candidate_new_origin)
                    ).hexdigest(),
                }
            )
            return supersession_semantic_cross_binding_is_valid(
                candidate_record,
                classification=candidate_classification,
                classification_readback_identity=future_none_readback,
                prior_origin=candidate_prior_origin,
                current_scope=candidate_current_scope,
                new_origin_reservation=candidate_new_origin_reservation,
                new_origin=candidate_new_origin,
                authorized_transition=candidate_transition,
            )

